// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 치유
// ==========================================

// ── 요리사 (cook) · 자원 없음 ──
kJob('cook', 'B', [

{ at:'B', t:'숨은 자리 — 불 없는 한 끼',
  x:`문을 잠그고 숨었다. 밖에서 발소리가 오간다. 정해진 간격으로.<br><br>
    다들 하루 종일 못 먹었다. 손이 떨린다. 떨리는 손은 소리를 낸다.<br>
    불은 못 피운다. 연기도, 냄새도, 냄비 뚜껑 소리도 안 된다.<br><br>
    부엌에서 오래 산 사람은 안다. 불 없이 하는 요리가 있다. 그게 제일 어렵다.`,
  o:[
    { l:'① 말린 고기를 찢어 꿀과 소금에 버무린다.', k:'heal', dc:20,
      ok:`말린 고기를 손으로 실처럼 찢었다. 칼은 안 썼다. 칼은 도마에 닿으면 소리가 난다.<br><br>꿀을 조금, 소금을 손톱만큼. 손바닥으로 굴려 엄지만 한 덩이로 빚었다. 하나씩 입에 넣어 주었다.<br>씹지 말고 혀로 녹여 먹으라고 했다. 씹는 소리도 소리다.<br><br>다들 눈을 감고 녹여 먹었다. 손 떨림이 멎었다. 발소리가 문 앞을 두 번 지나갔다. 두 번 다 서지 않았다.`,
      ng:`꿀 단지 뚜껑이 손에서 미끄러졌다.<br><br>바닥에 떨어져 한 바퀴 굴렀다. 작은 소리다. 이 방에서는 작지 않다.<br>발소리가 멈췄다. 문고리가 한 번 내려갔다 올라간다. 잠금쇠가 버텼다.<br><br>그 뒤로 아무도 아무것도 먹지 못했다. 숨도 반만 쉬었다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ mind:-14, spirit:-12 } },
    { l:'② 내 몫을 빼고 넷에게만 나눈다.', k:'bond', dc:19,
      ok:`넷 몫으로만 나눴다. 이쪽 몫은 처음부터 없었다.<br><br>넷이 먹는 동안 문에 등을 대고 앉았다. 발소리를 셌다. 배가 울리려 할 때마다 숨을 참았다.<br>배고픈 배는 가장 정직한 소리를 낸다.<br><br>다 먹고 나서 누가 이쪽 손에 한 조각을 쥐여 주었다. 자기 몫을 반 남긴 것이다. 받았다. 녹여 먹었다.`,
      ng:`넷에게 나누는데 이쪽 배가 울렸다.<br><br>길고 낮게. 방 안이 굳는다. 문밖 발소리도 굳는다.<br>한참 뒤에 발소리가 다시 움직였다. 문 앞을 지나쳐 갔다. 지나가는 척했는지는 모른다.<br><br>그 뒤로 내내 배를 끌어안고 있었다. 손끝이 하얗게 식었다.`,
      win:{ exp:14, dream:2, spirit:6 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B', t:'비 — 젖은 남자의 냄새',
  x:`빗속에서 남자 하나가 일행에 붙었다. 자기도 갇혀 있었다고 한다. 쫓기는 중이라고.<br><br>
    젖은 외투, 젖은 머리. 숨이 가쁘다. 손등에 긁힌 상처도 있다.<br>
    부엌 사람은 냄새로 사람이 어디 있다 왔는지 안다. 생선 만진 손, 기름 앞에 선 옷, 마늘 깐 손톱.<br><br>
    남자가 가까이 와서 고맙다고 한다. 비 냄새 밑에 다른 냄새가 있다.`,
  o:[
    { l:'① 상처를 봐 주는 척 소매 냄새를 맡는다.', k:'sense', dc:20, wake:1,
      ok:`상처를 봐 주는 척 소매를 잡았다. 코를 가까이 댔다.<br><br>비 냄새. 그 밑에 표백제. 그 밑에 담배. 맨 밑에 아주 옅게 쇠 냄새.<br>갇혀 있던 사람한테서 표백제 냄새가 날 일이 없다. 바닥을 닦던 사람한테서 난다.<br><br>손을 놓고 웃어 주었다. 남자도 웃었다. 일행에게 손가락으로 신호했다. 다음 모퉁이에서 남자를 두고 뛰었다.<br>코가 음식이 아니라 사람을 맡았다. 맛을 가르던 감각이 거짓을 가르기 시작했다.`,
      ng:`소매를 잡는 순간 남자가 팔을 뺐다.<br><br>웃는다. 괜찮다고. 웃음이 너무 빠르다.<br>그 뒤로 남자는 이쪽 뒤에서만 걸었다. 다음 모퉁이에서 남자가 없었다. 대신 뒤쪽에서 발소리가 셋으로 늘었다.<br><br>뛰었다. 넘어졌다. 무릎이 찢어졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 먹을 것을 건네고 먹는 모양을 본다.', k:'gaze', dc:19,
      ok:`말린 고기 한 조각을 건넸다. 쫓기던 사람은 먹는 모양이 정해져 있다. 급하게, 흘리면서.<br><br>남자는 받아서 주머니에 넣었다. 고맙다고만 했다.<br>배고픈 사람은 받은 것을 넣어 두지 않는다. 배부른 사람이 넣어 둔다.<br><br>그 뒤로 남자 앞에서는 길 이야기를 하지 않았다. 남자는 모퉁이마다 뒤를 돌아보았다. 쫓아오는 게 있는지가 아니라 쫓아오는 게 잘 오는지 보는 눈이었다.`,
      ng:`건네는데 남자가 덥석 받아 먹었다.<br><br>급하게, 흘리면서. 정말 굶은 사람 같다. 의심을 거뒀다.<br>한 시간 뒤 남자가 사라졌다. 이쪽 가방도 같이. 남은 먹을 것이 다 거기 있었다.<br><br>굶은 척도 배울 수 있다. 먹는 척처럼.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-10 } }
  ] },

{ at:'B', t:'건네받은 국 — 보온병',
  x:`비를 피해 들어선 자리에 먼저 온 사람이 있었다. 늙은 여자다. 무릎에 보온병을 올려 두었다.<br><br>
    여자가 말없이 뚜껑 잔에 국을 따라 내민다. 김이 오른다. 다들 침을 삼킨다.<br>
    요리사는 남이 끓인 국을 받으면 먼저 양을 본다. 양을 보면 몇 사람 몫을 끓였는지 안다.<br><br>
    보온병이 딱 이쪽 일행만큼이다. 여자는 일행이 몇인지 묻지 않았다.`,
  o:[
    { l:'① 한 모금 맛을 본다.', k:'sense', dc:21,
      doom:{ title:'한 모금', what:'국을 삼키고 눈이 감기기 시작했습니다', dc:17, sec:55,
        text:`혀끝에 대고 굴렸다. 멸치, 무, 파. 간이 잘 맞는다. 잘 끓인 국이다.<br><br>그래서 삼켰다. 넘기고 나서 끝맛이 왔다. 쇠 맛. 아주 옅게.<br>잔이 무거워진다. 손에서 기운다.<br><br>여자가 잔을 받아 든다. 흘리면 아깝다는 듯이. 그리고 기다린다. 다른 사람들이 잔을 들기를.<br>누가 이쪽 목구멍에 손가락을 넣어 토하게 해야 한다. 지금.`,
        dieText:`맛을 봐야 아는 혀는 맛있는 것에 약하다.<br><br>그 국은 정말 잘 끓인 국이었다. 그래서 끝까지 의심하지 못했다.<br>다음 날 밤에도 그 자리에 여자가 앉아 있었다. 보온병 양이 한 사람 몫 줄어 있었다.` },
      ok:`잔을 입술에만 댔다. 삼키지 않았다.<br><br>국물이 너무 맑다. 이 정도 건더기면 국물이 흐려야 한다. 누가 위에 뜬 것을 한 번 걷었다. 걷어 낸 건 기름이 아니다.<br>잔을 내려놓고 고맙다고 했다. 일행 손에서도 잔을 하나씩 내려놓게 했다.<br><br>여자는 아무 말 없이 보온병 뚜껑을 잠갔다. 잠그는 손이 아쉬워하지 않는다. 다음 손님이 있다는 손이다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 국을 쏟고 건더기만 씻어 다시 만다.', k:'heal', dc:20,
      ok:`잔을 받아 들고 바닥 배수구에 국물을 쏟았다. 여자가 처음으로 표정을 바꾼다.<br><br>건더기만 건져 맑은 물에 헹궜다. 새 물에 소금 한 조각을 녹여 다시 말았다. 찬 국이다.<br>맛은 반으로 줄었다. 대신 다 같이 먹고 다 같이 일어났다.<br><br>나갈 때 돌아보니 여자가 국물 쏟은 자리를 걸레로 닦고 있었다. 무릎을 꿇고, 아주 꼼꼼히.`,
      ng:`잔을 쏟으려는데 여자가 손목을 잡는다.<br><br>두 손이 잔 위에서 맞섰다. 뜨거운 국이 이쪽 손등에 쏟아졌다.<br>여자가 그제야 손을 놓았다. 미안하다고 한다. 미안해하는 얼굴이 아니다.<br><br>손등이 하얗게 부풀었다. 칼을 쥐는 손이다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-26, mind:-10 } }
  ] },

{ at:'B', t:'시계 없는 방 — 뜸 들이는 시간',
  x:`시계를 빼앗겼다. 창도 없다. 몇 시인지 모른다.<br><br>
    문밖 순찰은 일정한 간격으로 지나간다. 그 간격을 알면 나갈 틈을 안다.<br>
    부엌에서 산 사람은 시계를 잘 안 본다. 밥은 뜸으로 재고 국은 끓는 소리로 잰다. 몸에 시계가 있다.<br><br>
    발소리가 지나갔다. 다음 발소리까지가 한 번의 틈이다.`,
  o:[
    { l:'① 밥 한 솥 짓는 시간으로 센다.', k:'fix', dc:20, wake:1,
      ok:`눈을 감고 쌀을 씻었다. 머릿속에서. 물을 맞추고 불을 올렸다. 끓어오르고, 불을 줄이고, 뜸을 들인다.<br><br>뜸이 다 들 즈음 발소리가 왔다. 다음 번에도 그랬다. 그다음 번에는 국 한 그릇 데울 만큼 빨랐다.<br>순찰이 빨라지고 있다. 새벽이 가까운 것이다.<br><br>뜸 시간의 반에 문을 열었다. 복도를 다 지날 때 뒤에서 발소리가 났다. 딱 맞았다.<br>불 앞에서 익힌 시간이 바깥의 시간과 맞물렸다. 손이 아니라 몸 전체가 불 앞에 서는 법을 알았다.`,
      ng:`세다가 머릿속 솥이 넘쳤다.<br><br>불을 줄이는 걸 잊었다. 몇 번째 뜸이었는지 모르겠다. 처음부터 다시 셌다.<br>문을 열었을 때 복도 끝에 손전등이 있었다. 빛이 이쪽 얼굴에 박혔다.<br><br>문을 닫았다. 문틈으로 빛이 한참 머물렀다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 동료의 맥박으로 센다.', k:'steady', dc:19,
      ok:`동료 손목을 잡고 맥을 셌다. 순찰 한 번에 사백 남짓.<br><br>정확하지는 않다. 겁먹은 맥은 빠르다. 그래서 셀 때마다 말을 걸어 맥을 가라앉혔다.<br>세 번을 재고 나서 문을 열었다. 틈은 있었다. 좁았다.<br><br>복도를 반쯤 지났을 때 발소리가 들렸다. 뛰었다. 아슬아슬하게 모퉁이를 돌았다.`,
      ng:`세는 동안 동료 맥이 점점 빨라졌다.<br><br>무엇을 기다리는지 알아 버린 것이다.<br>숫자가 엉망이 됐다. 엉망인 숫자로 문을 열었다. 틈이 없었다. 쫓겼다. 어깨를 문틀에 찧었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'잠긴 문 — 부엌칼 한 자루',
  x:`탁자 서랍에서 칼이 나왔다. 부엌칼이다. 날이 무디다.<br><br>
    일행이 칼을 보더니 눈빛이 바뀐다. 무기가 생겼다고 생각한다.<br>
    요리사는 칼을 그렇게 보지 않는다. 칼은 써는 물건이다. 찌르는 물건이 아니다. 써는 쪽으로 쓰면 훨씬 많은 걸 한다.<br><br>
    문은 바깥에서 끈으로 감겼다. 문틈으로 끈 한 가닥이 보인다.`,
  o:[
    { l:'① 칼날을 눕혀 문틈의 끈을 바른다.', k:'fix', dc:20, wake:1,
      ok:`칼날을 눕혀 문틈에 넣었다. 찌르지 않고 밀고 당겼다. 고기 힘줄을 바를 때처럼.<br><br>무딘 날도 각도가 맞으면 든다. 끈 섬유가 한 올씩 끊어지는 게 손끝에 전해진다.<br>마지막 한 올이 끊기자 문이 한 치 벌어졌다.<br><br>칼을 손에서 놓지 않고 나섰다. 쥔 자리가 달라졌다. 손잡이가 아니라 날 뿌리를 쥐었다. 거기를 쥐면 칼이 손가락이 된다.`,
      ng:`무딘 날이 끈 위에서 미끄러졌다.<br><br>다시 넣으려다 날이 문틈에 끼었다. 빼려고 당기는데 쇠가 운다. 끼익.<br>복도 저편에서 발소리가 멈췄다가, 이쪽으로 온다.<br><br>칼을 버려두고 문에서 떨어졌다. 문틈에 박힌 칼을 저쪽이 뽑아 갔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-12 } },
    { l:'② 시멘트 모서리에 날을 세운다.', k:'steady', dc:19,
      ok:`바닥 시멘트 모서리에 칼날을 눕혀 갈았다. 소리가 안 나게 침을 묻혀 가며.<br><br>오래 걸렸다. 손목이 저리다. 엄지손톱 위를 그어 보니 걸린다. 날이 섰다.<br>이제 끈이든 테이프든 썬다.<br><br>일행이 칼을 달라고 했다. 안 줬다. 날 선 칼은 아는 손에 있어야 한다.`,
      ng:`가는 소리가 컸다. 아무리 침을 묻혀도.<br><br>밖에서 무언가 문에 귀를 댔다. 문짝이 아주 조금 안쪽으로 휜다.<br>숨을 멈추고 칼을 쥐고 있었다. 너무 세게. 날이 서기도 전에 손바닥부터 베였다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'도망 끝 — 하얗게 질린 동료',
  x:`한참을 뛰었다. 겨우 숨었다. 동료 하나가 주저앉았다.<br><br>
    얼굴이 하얗다. 식은땀이 난다. 다친 데는 크지 않은데 손이 차다. 말이 느리다.<br>
    부엌 사람은 이걸 본 적이 있다. 잔칫날 하루 종일 굶고 불 앞에 선 사람이 이렇게 쓰러진다.<br><br>
    몸이 바닥났다. 약보다 먼저 들어가야 할 것이 있다.`,
  o:[
    { l:'① 꿀과 소금을 물에 타서 조금씩 먹인다.', k:'heal', dc:19,
      ok:`물 반 컵에 꿀 한 숟가락, 소금 한 꼬집. 손가락으로 저었다.<br><br>한 모금씩, 숨 열 번에 한 번. 한꺼번에 주면 토한다.<br>컵이 비어 갈 때쯤 동료 손에 온기가 돈다. 눈이 이쪽을 제대로 본다.<br><br>단 것과 짠 것. 사람이 쓰러질 때 제일 먼저 빠져나가는 두 가지다. 부엌에서 배운 의술이다.`,
      ng:`급하게 먹였다. 동료가 사레가 들려 기침을 한다.<br><br>기침이 멈추지 않는다. 숨은 자리에서 내는 기침은 위험하다. 손으로 입을 막아 주었다.<br>막는 동안 동료 얼굴이 더 하얘졌다. 꿀물은 반이 바닥에 쏟아졌다.`,
      win:{ exp:16, hp:10 }, lose:{ hp:-20, mind:-12 } },
    { l:'② 다리를 높이고 품에 넣어 데운다.', k:'bond', dc:20,
      ok:`바닥에 눕히고 다리를 상자 위에 올렸다. 외투를 벗어 덮고 손을 품에 넣어 녹였다.<br><br>피가 머리로 돌아간다. 얼굴에 색이 돈다.<br>동료가 배고프다고 말한다. 배고프다는 말이 나오면 산 것이다.<br><br>남은 고기 한 점을 쥐여 주었다. 씹는 걸 끝까지 보았다.`,
      ng:`다리를 올리는데 동료가 몸을 비튼다. 무섭다고 한다. 누워 있으면 못 뛴다고.<br><br>실랑이하는 사이 동료가 정신을 놓았다. 한참 뺨을 두드려 깨웠다.<br>깨고 나서도 손이 차다. 이쪽 손도 같이 차졌다.`,
      win:{ exp:15, dream:2, spirit:6 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B', t:'깨진 창 — 받아 둔 빗물',
  x:`깨진 창으로 빗물이 샌다. 창 아래 누가 양동이를 받쳐 두었다. 찰랑찰랑 찼다.<br><br>
    다들 목이 탄다. 뛰느라 땀을 다 흘렸다.<br>
    부엌 사람은 물을 보면 무엇에 쓸 물인지 안다. 받아 둔 물은 받은 사람이 무엇에 쓰려 했는지에 달렸다.<br><br>
    창밖 네온이 물 위에 번진다. 빨간 빛이 흔들리다가, 한 군데서 흔들리지 않는다.`,
  o:[
    { l:'① 위쪽만 떠서 천에 거른다.', k:'heal', dc:19,
      ok:`손바닥으로 수면을 살살 밀어 위쪽만 떴다. 손수건 두 겹에 걸렀다.<br><br>맑다. 쇠 맛이 조금 난다. 창틀 녹이다. 이 정도는 괜찮다.<br>수통 하나를 다 채웠다.<br><br>마지막에 수면을 다시 봤다. 흔들리지 않던 자리가 없다. 바닥으로 가라앉았거나, 처음부터 창밖에서 비친 것이었다.`,
      ng:`뜨는데 손등에 무언가 닿았다. 미끈하다.<br><br>양동이 안에서 무엇이 손을 스치고 내려갔다. 손을 뺐다. 물이 사방으로 튄다.<br>그 소리에 복도 쪽 그림자가 멈춘다. 물은 한 모금도 못 챙기고 뛰었다. 깨진 유리에 팔뚝이 그어졌다.`,
      win:{ exp:15, dream:2, item:'맑은 물' }, lose:{ hp:-20, spirit:-14 } },
    { l:'② 흔들리지 않는 자리를 들여다본다.', k:'gaze', dc:21,
      ok:`고개를 숙여 양동이 안을 봤다. 흔들리지 않는 자리는 빛이 아니다. 물 위에 뜬 기름막이다.<br><br>돼지기름이다. 튀김 솥에서 쓰는 것. 누가 이 양동이로 기름 솥을 헹궜다.<br>근처에 부엌이 있다. 부엌에는 늘 뒷문이 있다. 기름 든 양동이를 날라야 하니까.<br><br>바닥에 기름 자국이 점점이 이어진다. 따라가니 작은 쇠문이 나왔다. 잠겨 있지 않다.`,
      ng:`들여다보는데 물에 비친 얼굴이 하나 더 있다.<br><br>이쪽 어깨 뒤에. 돌아보지 않았다. 돌아보면 확인이 된다.<br>천천히 일어나 걸었다. 뒤통수가 내내 따가웠다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 문 앞 — 남은 것으로 한 상',
  x:`마지막 문 앞이다. 저 문만 지나면 밖이다. 아니면 끝이다.<br><br>
    다들 가방을 털었다. 주운 것이 이것저것이다. 소금 한 조각, 고기 몇 점, 마른 나물 한 줌.<br>
    요리사는 남은 것을 보면 무엇이 될지 안다. 지금 먹어야 할 것과 아껴야 할 것도 안다.<br><br>
    문 너머에서 시계 소리가 들린다. 째깍, 째깍. 시간이 많지 않다.`,
  o:[
    { l:'① 불 없이 한 그릇으로 만다.', k:'heal', dc:20, wake:1,
      ok:`물에 소금을 녹이고 마른 나물을 불렸다. 고기를 잘게 찢어 넣었다. 손으로 주물렀다. 불 대신 손의 열로.<br><br>찬 국이다. 다섯이 한 모금씩. 짜고 비리고 시다. 다 먹었다.<br>먹고 나서 다들 일어선다. 다리가 일어선다.<br><br>불도 솥도 없이 한 상을 차렸다. 있는 것만으로 되는 맛을 손이 먼저 찾아냈다. 재료를 보기 전에 손이 맛을 짓기 시작했다.`,
      ng:`서두르다 소금을 너무 넣었다.<br><br>한 모금씩 먹고 다들 물을 찾는다. 물은 문 앞에 서기 전에 다 마셨다.<br>마른 입으로 문 앞에 섰다. 목이 갈라진다.`,
      win:{ exp:24, dream:3, hp:10 }, lose:{ hp:-20, mind:-12 } },
    { l:'② 반만 먹이고 반은 문 밖을 위해 싼다.', k:'fix', dc:19,
      ok:`반만 나누고 반은 기름종이에 쌌다. 문 밖이 끝이 아닐 수도 있다.<br><br>배가 덜 찼다. 대신 다들 주머니 속 무게를 안다. 다음 끼니가 있다는 무게.<br>사람은 다음 끼니가 있으면 덜 무너진다.`,
      ng:`싸 두는 걸 일행 하나가 봤다.<br><br>자기 몫을 더 달라고 한다. 목소리가 커진다. 문 너머 시계 소리가 멎었다. 듣고 있다.<br>입을 막고 나눠 주었다. 싼 것은 남지 않았다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 비린 것을 복도 반대쪽에 미끼로 둔다.', k:'hide', dc:21,
      ok:`고기 한 점을 복도 반대쪽 끝에 놓았다. 비린 것, 냄새 나는 것.<br><br>문 너머의 시계 소리가 그쪽으로 옮겨 간다. 냄새를 맡는 것이다. 배고픈 것은 이쪽만이 아니다.<br>소리가 멀어진 틈에 문을 지났다.<br><br>상을 어디에 차리느냐도 요리다.`,
      ng:`놓고 돌아서는데 복도 끝에서 무언가 이미 기다리고 있었다.<br><br>고기는 놓기도 전에 사라졌다. 이쪽 손목까지 같이 사라질 뻔했다.<br>손등에 이빨 같은 자국이 남았다. 무엇의 이빨인지는 보지 못했다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 소금 자루',
  x:`창고 한쪽에 소금 자루가 팔레트째 쌓였다. 천장 가까이까지.<br><br>
    자루 겉에 『천일염 20kg』이라고 찍혀 있다. 비가 새서 아래쪽 자루들이 젖었다 말라 굳었다.<br>
    부엌 사람은 소금 자루를 들어 보면 안다. 소금은 무게가 정직하다. 젖으면 무거워지고 마르면 가벼워진다. 그뿐이다.<br><br>
    맨 아래 줄 가운데 자루 하나가 다른 것보다 낮게 내려앉았다. 젖지도 않았는데.`,
  o:[
    { l:'① 굳은 자루를 칼끝으로 째어 덩이를 떼어 낸다.', k:'fix', dc:19,
      ok:`맨 위 귀퉁이 자루를 칼끝으로 쨌다. 젖었다 마른 소금이 돌처럼 엉겨 있다.<br><br>손바닥만 한 덩이를 둘 떼어 냈다. 자루는 도로 여며 두었다. 쌓인 줄이 흐트러지면 누가 센다.<br>소금이 있으면 무엇이든 먹을 만해진다. 상처도 씻는다.<br><br>여미면서 보니 자루마다 꿰맨 실 색이 같다. 하나만 다르다. 맨 아래 가운데 것.`,
      ng:`째는데 자루 줄이 기울었다.<br><br>위에서 한 자루가 미끄러져 떨어진다. 이십 킬로다. 어깨로 받았다. 쇄골이 울린다.<br>떨어지는 소리는 빗소리가 먹었다. 어깨는 먹지 못했다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-26, mind:-10 } },
    { l:'② 내려앉은 자루 귀퉁이를 들어 본다.', k:'steady', dc:21,
      ok:`무릎을 꿇고 맨 아래 가운데 자루 귀퉁이를 들어 봤다. 들리지 않는다.<br><br>이십 킬로가 아니다. 그보다 훨씬 무겁다. 그리고 무게가 한쪽으로 쏠렸다. 소금은 쏠리지 않는다.<br>손을 놓고 일어났다. 자루 겉에 손자국이 남지 않게 털었다.<br><br>무엇이 들었는지는 묻지 않기로 했다. 칠판에 적힌 숫자를 생각했다. 다섯. 모자라면 채울 것.`,
      ng:`들어 보려는데 자루가 꿈틀했다.<br><br>아니다. 손이 떨린 것이다. 그렇게 생각하기로 했다. 그런데 손을 떼자 자루 겉에 젖은 자국이 번진다. 안에서 밖으로.<br>뒷걸음질 치다 팔레트 모서리에 정강이를 찍었다. 오래 아무 말도 못 했다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B1', t:'냉동 창고 — 걸린 고기',
  x:`냉동 창고 레일에 고기가 걸려 있다. 반으로 가른 돼지, 소 다리, 껍질 벗긴 무언가.<br><br>
    입김이 하얗다. 손가락이 금방 굳는다. 오래 있으면 안 되는 곳이다.<br>
    고기 단면을 보면 누가 잘랐는지 안다. 칼을 아는 손은 결을 따라 가르고, 모르는 손은 결을 끊는다.<br><br>
    레일 끝 몇 덩이는 결을 끊었다. 같은 손이 아니다. 최근이다.`,
  o:[
    { l:'① 결대로 잘린 고기에서 한 덩이를 바른다.', k:'heal', dc:20,
      ok:`결대로 잘린 돼지 앞다리에 칼을 넣었다. 언 고기는 결을 따라야 들어간다.<br><br>주먹만 한 덩이를 발라 기름종이에 쌌다. 녹으면 먹을 수 있다. 얼어 있는 동안은 상하지 않는다.<br>손가락 끝이 하얗다. 고기를 싸 쥐고 입김으로 손을 녹였다.<br><br>나오며 레일 끝을 다시 보지 않았다. 다 봐야 하는 건 아니다.`,
      ng:`칼을 넣는데 언 고기가 칼날을 문다.<br><br>빼려고 비틀다 칼끝이 튀었다. 엄지 밑이 베였다. 피가 바로 얼어붙는다.<br>베인 줄도 모르고 있다가 한참 뒤에 알았다. 손이 언 것이다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-24, mind:-10 } },
    { l:'② 결을 끊은 단면을 읽는다.', k:'gaze', dc:21, wake:1,
      ok:`레일 끝 덩이 앞에 섰다. 단면을 봤다.<br><br>톱이 아니라 큰 칼이다. 한 번에 내리쳤다. 결은 끊었지만 망설인 자국이 없다. 칼을 모르는 손이 아니라 고기를 모르는 손이다. 다른 것을 많이 잘라 본 손이다.<br>칼질 방향이 전부 오른쪽 위에서 왼쪽 아래로. 왼손잡이다.<br><br>나중에 회색 비옷이 양동이를 왼손으로 드는 걸 봤다. 그때 알았다. 고기의 결을 읽던 눈이 손의 버릇을 읽는다. 단면 하나가 서명처럼 보였다.`,
      ng:`단면을 들여다보는 사이 레일이 덜컹 움직였다.<br><br>고기들이 일제히 한 칸씩 밀려온다. 언 덩이가 어깨를 친다. 갈고리가 귀 옆을 스쳤다.<br>바닥에 엎드려 기었다. 뺨이 바닥 성에에 붙었다 떨어졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-12 } },
    { l:'③ 안쪽 깊이 걸린 좋은 고기를 고르러 들어간다.', k:'sense', dc:20,
      doom:{ title:'안쪽 레일', what:'냉동 창고 문이 바깥에서 닫혔습니다', dc:17, sec:50,
        text:`안쪽으로 갈수록 고기가 좋다. 기름이 곱게 박혔다. 좋은 고기는 늘 깊숙이 둔다. 부엌의 셈이다.<br><br>맨 안쪽 덩이에 칼을 대는데 뒤에서 철컥 소리가 났다. 문이다. 바깥 손잡이 내려가는 소리.<br>불이 꺼진다. 입김만 하얗다. 손끝부터 감각이 없어진다.<br><br>문에 손바닥을 댔다. 안쪽 손잡이가 없다. 누가 밖에서 걸쇠를 풀어야 한다.`,
        dieText:`좋은 고기는 늘 깊숙이 둔다.<br><br>새벽에 문이 열렸다. 회색 비옷이 들어와 레일을 한 칸 밀었다. 맨 안쪽에 한 덩이가 늘었다.<br>칼은 아직 손에 있다. 결대로 쥐고.` },
      ok:`안쪽으로 세 걸음 들어가다 멈췄다. 문 걸쇠를 봤다.<br><br>안쪽 손잡이가 없다. 뜯겨 나갔다. 이 문은 밖에서만 열린다.<br>나무 상자 하나를 문틈에 끼워 놓고 들어갔다. 좋은 덩이를 금방 발라 나왔다.<br><br>상자를 빼자 문이 저절로 닫혔다. 묵직하게. 문이 기다리고 있었다.`,
      win:{ exp:18, dream:3, item:'짐승 고기' } }
  ] },

{ at:'B1', t:'경매장 — 맑은 칸 하나',
  x:`어시장 경매장 바닥에 수조가 줄지어 있다. 물이 흐리다. 산소 기계가 꺼졌다.<br><br>
    생선은 대부분 배를 뒤집었다. 맨 끝 수조 하나만 물이 맑다. 그 칸만 따로 기계가 돈다.<br>
    생선은 눈과 아가미를 보면 언제 잡혔는지 안다. 장을 오래 본 사람은 그걸로 값을 부른다.<br><br>
    맑은 칸 팻말에 『민물 · 비매품』이라고 적혀 있다. 누가 아껴 둔 고기다.`,
  o:[
    { l:'① 맑은 칸에 손을 넣어 한 마리 건진다.', k:'luck', dc:20,
      ok:`소매를 걷고 손을 넣었다. 물이 차다. 메기다. 팔뚝만 하다.<br><br>아가미가 붉다. 오늘 들어온 것이다. 바다 항구에 민물고기가 오늘 들어왔다. 누가 먹으려고.<br>젖은 신문지에 싸 품에 넣었다. 꿈틀댄다.<br><br>팻말을 다시 봤다. 비매품 밑에 작게 적혀 있다. 『청소 끝나고.』`,
      ng:`손을 넣는데 메기가 손을 문다. 메기 이빨은 작고 많다.<br><br>손 빼는 소리, 물 튀는 소리. 경매장 이층 유리창에 불이 켜진다.<br>수조 뒤에 엎드려 있었다. 손에서 피가 수조 물로 떨어진다. 메기들이 그쪽으로 몰린다.`,
      win:{ exp:16, dream:2, item:'민물고기' }, lose:{ hp:-22, mind:-12 } },
    { l:'② 죽은 생선 눈으로 기계가 꺼진 때를 잰다.', k:'gaze', dc:19,
      ok:`배 뒤집은 생선 눈을 봤다. 아직 맑다. 아가미도 분홍이다.<br><br>기계가 꺼진 지 한 시간이 안 됐다. 누가 끈 것이다. 이 수조에 볼일이 끝났다는 뜻이다.<br>한 시간 전에 이 경매장에 누가 있었다. 지금도 있을지 모른다.<br><br>수조 사이를 피해 벽을 따라 걸었다. 발자국이 젖은 바닥에 남지 않게.`,
      ng:`눈을 들여다보는데 생선 눈에 무언가 비친다. 이쪽 뒤로.<br><br>돌아섰다. 아무것도 없다. 바닥에 젖은 발자국만 이쪽 발자국 옆에 나란히 찍혀 있다.<br>한참 그 자리에서 움직이지 못했다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'야적장 — 해무호 주방 상자',
  x:`컨테이너 사이에 나무 상자가 쌓였다. 상자에 『해무호 · 주방』이라고 스텐실로 찍혔다.<br><br>
    배에 실을 식료품이다. 쌀, 마른 나물, 통조림, 장.<br>
    부엌 사람은 식료품 목록을 보면 그 배에 몇 사람이 타는지 안다. 쌀 몇 되, 며칠, 몇 끼.<br><br>
    상자 옆에 목록이 붙어 있다. 비에 젖어 글자가 번졌다.`,
  o:[
    { l:'① 목록으로 배에 탈 사람을 셈한다.', k:'gaze', dc:20, wake:1,
      ok:`번진 글자를 손가락으로 따라 읽었다. 쌀 넉 말, 사흘 항해. 하루 세 끼.<br><br>셈하면 열둘이다. 선원이 열둘이다. 그런데 국그릇 칸에 열일곱이라고 적혔다. 쌀은 열둘 몫인데 그릇은 열일곱.<br>그릇은 있는데 밥은 없는 다섯. 먹지 않는 승객이다.<br><br>목록을 떼어 품에 넣었다. 장 보는 셈이 사람을 읽는 셈이 됐다. 쌀 됫수 뒤에 숨은 머릿수가 보이기 시작했다.`,
      ng:`읽는데 글자가 비에 녹아 흘렀다.<br><br>손가락에 잉크만 묻었다. 컨테이너 위에서 탐조등이 돈다. 빛이 상자 위를 지나간다.<br>상자 그림자에 납작 붙었다. 빛이 한 번 되돌아왔다. 잉크 묻은 손가락이 떨렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 못이 헐거운 상자에서 마른 나물을 뺀다.', k:'luck', dc:19,
      ok:`상자 하나의 못이 헐겁다. 손으로 들었다. 마른 고사리와 시래기가 꾹꾹 눌려 있다.<br><br>한 묶음을 빼 품에 넣었다. 물에 불리면 열 배가 된다. 가벼운 것이 많이 먹인다.<br>상자를 닫고 못을 손바닥으로 눌러 박았다.<br><br>박고 나서 보니 다른 상자들 못은 전부 새것이다. 이것만 헐거웠다. 누가 먼저 열어 봤다.`,
      ng:`상자를 여는데 안에서 무언가 튀어나온다.<br><br>고양이다. 놀라서 이쪽 팔을 할퀴고 달아났다.<br>할퀸 자리에서 피가 빗물에 섞인다. 고양이가 달아난 쪽에서 누가 손전등을 켰다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ hp:-22, mind:-12 } },
    { l:'③ 된장 단지를 깨뜨려 바닥을 더럽혀 둔다.', k:'hide', dc:21,
      ok:`된장 단지 하나를 골목 바닥에 내려쳤다. 퍽. 진한 것이 빗물에 번진다.<br><br>컨테이너 끝에서 회색 비옷이 나타났다. 번진 자리 앞에서 멈춘다. 그냥 못 지나간다. 무릎을 꿇고 걸레를 꺼낸다.<br>닦는 사람은 더러운 것을 두고 못 간다. 그걸 이용했다.<br><br>그가 닦는 동안 반대쪽 골목으로 빠졌다. 걸레 소리가 오래 따라왔다. 아주 꼼꼼한 소리였다.`,
      ng:`내려치는 소리가 컸다.<br><br>탐조등이 바로 이쪽으로 돌아온다. 된장이 신발에 튀었다. 걸음마다 자국이 찍힌다.<br>자국을 따라 발소리가 온다. 서두르지 않는다. 컨테이너 모서리에 이마를 찧으며 뛰었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B2', t:'배식 수레 — 이름 붙은 식판',
  x:`복도에 배식 수레가 서 있다. 밤 아홉 시 배식이다. 식판마다 침대 명패와 같은 이름표가 붙었다.<br><br>
    죽, 무른 반찬 둘, 국. 다 같은 메뉴다.<br>
    요리사는 같은 솥에서 나온 음식이 다르게 생기면 안다. 국자를 다른 데서 떴거나, 무언가를 나중에 넣었다.<br><br>
    이쪽 침대 명패의 이름이 붙은 식판이 있다. 그 죽만 표면에 막이 판판하게 졌다.`,
  o:[
    { l:'① 이름 붙은 식판의 죽을 맛본다.', k:'sense', dc:21,
      doom:{ title:'이름 붙은 죽', what:'식판의 약이 돌기 시작합니다', dc:17, sec:55,
        text:`숟가락 끝으로 막을 걷고 한 입 떴다. 쌀죽이다. 간이 없다. 병원 죽이 원래 그렇다.<br><br>그래서 삼켰다. 넘기고 나서 혀뿌리가 쓰다. 쓴맛이 늦게 온다. 늦게 오는 쓴맛은 녹인 알약이다.<br>복도 불빛이 길게 늘어난다. 무릎이 접힌다. 수레 손잡이를 잡았다. 수레가 굴러간다. 이쪽을 끌고.<br><br>저 끝에서 딸깍 소리가 난다. 계수기다. 누가 토하게 해 주어야 한다. 정각이 되기 전에.`,
        dieText:`이름이 붙은 그릇은 그 이름이 먹으라고 차린 것이다.<br><br>그 이름은 이쪽 것이 아니었다. 먹고 나서 그 이름이 되었다.<br>다음 정각에 간호사가 그 이름을 불렀다. 침대에서 대답이 나왔다. 아주 순하게.` },
      ok:`숟가락을 들다 내려놓았다. 막이 너무 판판하다.<br><br>죽은 식으면서 막이 진다. 다른 식판들은 막이 쭈글쭈글하다. 이것만 판판하다. 다 식은 뒤에 누가 무언가를 저어 넣고 다시 데웠다.<br>이름 붙은 죽을 이름표 없는 식판의 죽과 바꿔 두었다.<br><br>정각에 간호사가 수레를 끌고 갔다. 식판 수를 세고 고개를 끄덕였다. 숫자는 맞았다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 이름 없는 식판만 골라 일행에게 돌린다.', k:'heal', dc:20,
      ok:`이름표 없는 식판만 골라 일행에게 하나씩 돌렸다. 죽, 국, 무른 나물.<br><br>먹기 전에 하나하나 혀끝으로 맛을 봤다. 쓴맛이 없다. 이름 없는 그릇에는 아무도 무엇을 넣지 않는다. 먹일 사람이 정해지지 않았으니까.<br>다들 허겁지겁 먹었다. 병원 죽도 굶은 배에는 잔치다.<br><br>빈 식판은 수레에 되돌려 놓았다. 있던 순서대로.`,
      ng:`고르는 사이 수레 바퀴가 삐걱했다.<br><br>복도 끝 간호사실 유리창 너머로 흰 모자가 고개를 든다. 이쪽을 본다. 숫자를 세는 눈이다.<br>식판 하나만 들고 침대로 숨어들었다. 다른 사람들 몫은 없다. 그 식판마저 차갑게 식어 있었다.`,
      win:{ exp:16, dream:2, hp:10 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B2', t:'병동 주방 — 식은 솥',
  x:`배식구 뒤로 작은 주방이 있다. 스테인리스 솥이 셋. 다 식었다.<br><br>
    벽에 식단표가 붙어 있다. 일주일 내내 같은 죽이다. 날짜 칸만 매일 바뀌었다.<br>
    남의 부엌에 들어가면 먼저 찬장을 연다. 찬장을 보면 그 부엌이 무엇을 먹이는지 안다.<br><br>
    복도 시계가 열한 시 오십 분이다. 정각 점검까지 십 분.`,
  o:[
    { l:'① 찬장 깊숙이 남은 것을 챙긴다.', k:'luck', dc:20,
      ok:`찬장 위 칸은 비었다. 아래 칸 깊숙이 굵은 소금 통이 있다. 굳어서 덩어리졌다.<br><br>한 덩이 깨서 챙겼다. 이 부엌은 소금을 안 쓴다. 통 뚜껑에 먼지가 앉았다.<br>간이 없는 밥을 오래 먹으면 사람이 순해진다. 부엌은 그걸 안다. 이 부엌도 알았다.<br><br>오십팔 분에 주방을 나왔다.`,
      ng:`찬장 문을 여는데 경첩이 운다.<br><br>복도에서 딸깍 소리가 멈춘다. 다가온다. 솥 뒤에 웅크렸다. 솥에 볼이 닿는다. 차갑다.<br>흰 신발이 배식구 앞에 섰다가 갔다. 그 뒤로 정각까지 숨도 못 쉬었다. 저린 무릎으로 일어나다 넘어졌다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-20, mind:-14 } },
    { l:'② 솥 바닥 누룽지를 긁어 다섯 몫을 만든다.', k:'heal', dc:19,
      ok:`솥 바닥에 죽이 눌어붙었다. 주걱으로 긁었다. 소리가 안 나게 천천히.<br><br>누룽지 한 판. 물에 불려 손으로 뭉쳤다. 다섯 덩이. 간은 소금 한 꼬집.<br>병원 죽보다 낫다. 누룽지에는 불 맛이 있다.<br><br>정각 전에 침대로 돌아가 하나씩 쥐여 주었다. 이불 속에서 먹었다. 바스락 소리를 숨에 묻었다.`,
      ng:`긁다가 주걱이 솥에 부딪쳤다. 텅.<br><br>스테인리스는 소리를 오래 끈다. 웅웅거린다. 손바닥으로 솥을 눌러 떨림을 죽였다.<br>죽였을 때는 이미 복도 끝에서 계수기 소리가 다가오고 있었다. 빈손으로 기어 나왔다. 손등이 솥 테두리에 길게 긁혔다.`,
      win:{ exp:15, hp:8 }, lose:{ hp:-22, spirit:-10 } },
    { l:'③ 식단표 뒷면을 본다.', k:'gaze', dc:21,
      ok:`식단표 압정을 빼고 뒤집었다.<br><br>뒷면에 연필로 적혀 있다. 누가 몰래 적었다. 『죽 끓이는 날 밤에는 빈 솥이 화물칸으로 내려간다. 뚜껑 닫고.』<br>솥은 내려간다. 사람 하나 들어갈 만한 솥이다.<br><br>식단표를 도로 붙였다. 압정 구멍에 맞춰 정확히.`,
      ng:`뒤집는데 압정이 바닥에 떨어졌다. 굴러서 배식구 밑으로 들어갔다.<br><br>찾느라 엎드렸다. 정각 종이 울렸다. 주방 문이 열린다.<br>압정을 못 찾고 식단표를 손으로 누르고 서 있었다. 흰 마스크가 이쪽을 오래 봤다. 이쪽 이름을 외워 두는 눈이었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'휴게실 — 창가의 요구르트 병',
  x:`휴게실 창가에 요구르트 병이 줄지어 있다. 병마다 흙이 담겼고 풀이 자란다.<br><br>
    부추, 쑥갓, 이름 모를 잎 하나. 누가 길렀다. 정성 들여.<br>
    풀을 보면 먹을 것인지 안다. 병원 창가에서 자란 풀은 대개 먹으려고 기른 것이다. 먹을 게 없는 곳이니까.<br><br>
    창가 의자에 노인이 앉아 있다. 숟가락으로 물을 한 방울씩 준다. 세면서.`,
  o:[
    { l:'① 노인에게 몇 잎 얻을 수 있는지 묻는다.', k:'bond', dc:20,
      ok:`옆에 앉아 물 주는 걸 지켜봤다. 한참 지나 물었다. 한 줌만 얻을 수 있겠냐고.<br><br>노인이 숟가락을 멈춘다. 손가락으로 부추 한 병을 가리킨다. 그것만. 다른 건 안 된다.<br>뿌리는 두고 잎만 잘랐다. 노인이 자른 자리를 보고 고개를 끄덕인다. 잘 자르는 손이라고.<br><br>노인이 마지막으로 말했다. 이 부추는 일곱 번째 잘랐다고. 아무도 안 먹었다고. 먹어 줘서 고맙다고.`,
      ng:`묻자 노인이 대답을 안 한다. 계속 센다.<br><br>몇 방울까지 셌는지 이쪽이 끼어들어 잊게 했다. 노인 손이 떨린다. 처음부터 다시 센다. 하나, 둘.<br>정각까지 다 세지 못하면 어떻게 되는지 노인 얼굴이 말해 준다. 물러났다. 등 뒤의 숫자가 오래 들렸다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 이름 모를 잎을 비벼 냄새를 맡는다.', k:'sense', dc:21,
      ok:`잎 하나를 손끝으로 비볐다. 쓰고 맵다. 먹는 잎이 아니다.<br><br>먹는 잎 사이에 먹지 않는 잎을 길렀다. 감추려고. 혀 밑에 넣고 있으면 잠이 덜 오는 잎이다.<br>이 병동 밥을 먹고도 깨어 있는 사람이 하나 있다. 이 노인이다.<br><br>노인이 한 잎을 따서 이쪽 손에 쥐여 주었다. 아무 말 없이.`,
      ng:`비비는 손을 노인이 덥석 잡았다.<br><br>손아귀가 세다. 노인의 손이 아니다. 숟가락이 바닥에 떨어졌다. 세던 숫자가 끊겼다.<br>노인이 운다. 소리 없이. 간호사실 쪽에서 딸깍 소리가 다가온다. 손을 빼서 도망쳤다. 손목에 손톱자국이 남았다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B2', t:'당직실 — 불어 터진 컵라면',
  x:`당직실 문이 반쯤 열렸다. 안에 아무도 없다.<br><br>
    탁자에 야식 그릇이 놓였다. 컵라면 용기 여섯, 나무젓가락 여섯 벌.<br>
    먹은 그릇을 보면 누가 먹었는지 안다. 국물을 남기는 사람, 다 마시는 사람, 젓가락을 꺾어 두는 사람.<br><br>
    여섯 그릇 다 물을 부었다. 다섯 그릇은 손대지 않았다. 면이 불어서 그릇 위로 넘쳤다.`,
  o:[
    { l:'① 먹은 한 그릇의 주인을 읽는다.', k:'gaze', dc:20, wake:1,
      ok:`한 그릇만 비었다. 국물까지. 젓가락은 반으로 꺾어 그릇 안에 넣었다. 다 먹은 사람의 버릇이다.<br><br>그릇 옆 먼지에 열쇠 꾸러미 자국이 찍혔다. 경비다. 다섯은 먹는 시늉만 하고, 경비 하나만 정말 먹었다.<br>이 층에 배고픈 사람은 하나다.<br><br>남은 그릇으로 사람을 셌다. 무엇을 먹었는지보다 무엇을 안 먹었는지가 더 많이 말한다. 부엌의 눈이 사람 사는 자리를 셈하기 시작했다.`,
      ng:`그릇을 들여다보는데 넘친 면이 아직 따뜻하다.<br><br>방금 부었다. 방금 여섯이 여기 있었다. 문이 뒤에서 천천히 닫힌다.<br>문틈으로 겨우 빠져나왔다. 손가락이 문에 끼었다. 손톱이 검게 죽었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 서랍의 간식을 챙긴다.', k:'luck', dc:19,
      ok:`탁자 서랍에 육포 봉지가 있다. 반쯤 먹었다. 경비 것이다.<br><br>봉지째 챙겼다. 미안했다. 서랍에 쪽지를 남겼다. 고맙다고. 이름은 안 썼다. 여기서는 이름을 쓰면 안 된다.<br>나오면서 생각했다. 이 층에서 서랍에 간식을 넣어 두는 사람은 하나다. 배고픈 사람.`,
      ng:`서랍을 여는데 안에서 무전기가 지직거린다.<br><br>『칠층. 인원 확인.』 낮은 목소리가 대답을 기다린다. 대답하지 않았다. 무전기가 다시 묻는다. 이번에는 이쪽 침대 명패의 이름으로.<br>서랍을 닫고 뛰었다. 복도 모서리에 어깨를 찧었다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B3', t:'식당칸 주방 — 빈 도마 소리',
  x:`식당칸 끝, 주방 문이 반쯤 열렸다. 안에서 도마 소리가 난다. 탁, 탁, 탁. 열차 덜컹임과 박자가 맞는다.<br><br>
    흰 조리복을 입은 사람이 등을 보이고 서 있다. 키도 어깨도 보통이다.<br>
    요리사는 칼 소리를 들으면 무엇을 써는지 안다. 파는 사각사각, 무는 탁탁, 고기는 툭툭.<br><br>
    이건 아무것에도 맞지 않는다. 도마만 치는 소리다.`,
  o:[
    { l:'① 문틈으로 칼 쥔 손을 본다.', k:'gaze', dc:20, wake:1,
      ok:`문틈에 눈을 댔다. 도마 위에 아무것도 없다. 칼이 빈 도마를 친다.<br><br>그 사람이 칼을 바지에 닦는다. 허벅지에 쓱. 주방에서 오래 일한 사람은 칼을 허리 행주에 닦는다. 손이 그렇게 굳는다. 바지에 닦는 손은 주방 손이 아니다.<br>조리복은 남의 것이다. 얼굴도 그럴 것이다.<br><br>일행에게 말했다. 흰 옷이 다가오면 손을 보라고. 얼굴은 바꿔 써도 손버릇은 못 바꾼다. 칼 쥔 손을 읽던 눈이 사람을 가르기 시작했다.`,
      ng:`문틈에 눈을 대는 순간 도마 소리가 멎었다.<br><br>그 사람이 고개만 돌린다. 몸은 그대로. 얼굴이 이쪽 일행 하나와 똑같다.<br>뒷걸음질 치다 식탁 모서리에 허리를 찍었다. 다시 보니 주방 문이 닫혀 있다. 도마 소리가 다시 난다. 이번엔 무언가를 써는 소리다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 들어가 옆에 서서 같이 칼을 잡는다.', k:'bond', dc:21,
      doom:{ title:'같은 도마', what:'주방의 흰 옷에게 끌려갑니다', dc:17, sec:50,
        text:`들어가서 옆에 섰다. 행주를 허리에 차고 칼 하나를 집었다. 주방에서는 옆에 선 사람을 동료로 본다.<br><br>그 사람이 이쪽을 보지도 않고 말한다. 늦었네. 목소리가 이쪽 목소리다.<br>손목이 잡혔다. 도마 쪽으로. 칼이 손에서 빠져 그 사람 손으로 간다.<br><br>주방 안쪽 냉장고 문이 열려 있다. 안이 깊다. 누가 이쪽 허리를 잡아당겨야 한다.`,
        dieText:`주방에서는 옆에 선 사람을 동료로 본다.<br><br>그 주방에서는 아니었다.<br>다음 운행 때 식당칸 주방에 흰 조리복이 서 있었다. 얼굴이 낯익었다. 이번에는 칼을 허리 행주에 닦았다.` },
      ok:`들어가려다 문지방에서 멈췄다.<br><br>행주를 허리에 차고 문 앞에서 말했다. 주문 들어왔다고. 주방 말이다.<br>그 사람이 뒤를 돌아보지 않고 대답한다. 네. 대답은 하는데 손이 갈 데를 모른다. 주문표 걸이를 보는 버릇이 없다.<br><br>그 틈에 주방 앞을 지나갔다. 진짜 주방 사람은 주문 소리에 눈보다 손이 먼저 움직인다.`,
      win:{ exp:18, dream:3 } },
    { l:'③ 도마 박자에 맞춰 뒤 찬장을 연다.', k:'hide', dc:20,
      ok:`식탁 사이를 기어 주방 뒷문 쪽 찬장에 닿았다. 도마 소리에 맞춰 문을 열었다. 탁, 열고. 탁, 집고. 탁, 닫고.<br><br>마른 표고 한 봉지. 식당칸은 좋은 것을 쓴다.<br>도마 소리는 끝까지 같은 박자였다. 이쪽 박자와 맞았다.`,
      ng:`박자를 놓쳤다. 찬장 문이 탁 소리 사이에 닫혔다.<br><br>도마 소리가 멈췄다. 칼 놓는 소리가 났다. 발소리는 안 났다.<br>뒤로 기어 나왔다. 무릎이 다 까졌다. 주방 문이 열려 있었는지 닫혀 있었는지 끝내 못 봤다.`,
      win:{ exp:16, dream:2, item:'야생 버섯' }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'식당칸 — 엎어 둔 수저',
  x:`식당칸 식탁마다 상이 차려졌다. 접시, 포크, 나이프, 냅킨. 흰 천.<br><br>
    아무도 앉아 있지 않다. 접시 위의 음식은 김이 나지 않는다. 식은 지 오래다.<br>
    상차림을 보면 누구를 위한 상인지 안다. 냅킨 접은 모양, 포크 놓인 자리, 물잔 높이.<br><br>
    식탁 하나만 다르다. 수저가 접시 위에 엎어져 있다.`,
  o:[
    { l:'① 엎어진 수저의 뜻을 읽는다.', k:'gaze', dc:21,
      ok:`수저를 엎어 두는 건 다 먹었다는 뜻이 아니다. 잠깐 자리를 비운 것이다. 곧 돌아온다는 표시다.<br><br>다른 식탁은 수저가 반듯하다. 돌아올 사람이 없다는 뜻이다. 차려 놓고 끝까지 아무도 오지 않는 상이다.<br>엎어진 식탁의 의자에 아직 온기가 있다.<br><br>그 식탁을 크게 돌아 지나갔다. 돌아올 사람과 마주치지 않으려고.`,
      ng:`수저를 들여다보는 사이 누가 그 식탁 의자를 뺐다.<br><br>이쪽 바로 옆에서. 앉는다. 얼굴을 보지 않았다. 냅킨 펴는 소리가 났다.<br>식당칸 끝까지 뒤를 보지 않고 걸었다. 걷는 내내 포크가 접시를 긁는 소리가 따라왔다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 식은 접시에서 먹을 만한 것을 가른다.', k:'heal', dc:20,
      ok:`식은 접시를 하나씩 맡았다. 대부분 상했다. 고기는 시고 생선은 비리다.<br><br>반찬 종지 하나에 꿀에 잰 무가 있다. 꿀은 상하지 않는다. 덜어 냈다.<br>식은 상도 다 버릴 것은 아니다. 가를 줄 알면.`,
      ng:`맡다가 상한 냄새를 한껏 들이마셨다.<br><br>속이 뒤집힌다. 입을 막고 참았다. 참는 소리가 컸다.<br>식당칸 끝에서 누가 헛구역질을 따라 했다. 한 박자 늦게. 일행 중 하나가 아니었다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'얼음 칸 — 녹지 않는 얼음',
  x:`2호차는 얼음 칸이다. 톱밥 덮은 얼음 덩이 사이에 나무 상자가 쌓였다.<br><br>
    식당칸으로 갈 재료다. 생선, 고기, 채소. 상자마다 역 이름 도장이 찍혔다.<br>
    얼음을 보면 언제 넣었는지 안다. 녹은 만큼이 지난 시간이다.<br><br>
    얼음은 하나도 안 녹았다. 몇 시간을 달렸는데.`,
  o:[
    { l:'① 생선 상자를 열어 오늘 것을 고른다.', k:'luck', dc:20,
      ok:`맨 위 상자 뚜껑을 들었다. 잉어 셋이 얼음에 누웠다.<br><br>눈이 맑다. 아가미가 붉다. 정말 오늘 잡은 것이다. 얼음이 안 녹은 까닭은 모른다. 생선은 거짓말을 안 한다.<br>하나를 신문지에 싸 품에 넣었다. 품이 차갑다.`,
      ng:`뚜껑을 들자 안에 생선이 없다.<br><br>얼음만 상자 가득. 얼음 속에 손목시계가 여러 개 박혀 있다. 다 같은 시각에 멈췄다. 네 시 사십사 분.<br>뚜껑을 닫는데 손가락이 얼음에 붙었다. 떼면서 살갗이 벗겨졌다.`,
      win:{ exp:16, dream:2, item:'민물고기' }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 고기 상자에서 쓸 만한 것을 바른다.', k:'heal', dc:21,
      ok:`고기 상자는 돼지 목살이다. 얼어서 돌 같다.<br><br>칼등으로 두드려 결을 틔우고 날을 넣었다. 두 덩이. 품에 넣으면 내릴 때쯤 녹는다.<br>나머지는 상자에 도로 넣고 톱밥을 덮었다. 누가 세면 맞게.`,
      ng:`두드리는 소리가 칸 안에서 울렸다.<br><br>얼음 덩이들 사이에서 무언가 몸을 일으킨다. 톱밥이 흘러내린다. 이쪽처럼 숨어 있던 사람인지는 모른다.<br>뛰쳐나오다 얼음에 미끄러져 옆구리를 찧었다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-26, mind:-10 } },
    { l:'③ 얼음 속살을 깎아 마실 물을 만든다.', k:'fix', dc:19,
      ok:`얼음 귀퉁이를 칼등으로 쳐서 떼어 냈다. 겉은 비린내를 먹었다. 겉을 깎고 속살만 수통에 넣었다.<br><br>품에 안고 녹였다. 맑다. 냄새도 없다.<br>얼음도 고기처럼 겉과 속이 다르다.`,
      ng:`떼어 낸 얼음 속에 무언가 비친다. 손톱만 한 것.<br><br>버렸다. 버리고 나서 그게 무엇이었는지 생각했다. 생각을 멈추지 못했다.<br>물은 못 챙겼다. 목이 오래 탔다.`,
      win:{ exp:15, dream:2, item:'맑은 물' }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B3', t:'우편칸 — 역마다 내릴 도시락',
  x:`우편칸 구석에 도시락 상자가 역별로 쌓였다. 서지 않는 역들에 내려야 했던 도시락이다.<br><br>
    상자마다 역 이름이 적혔다. 맨 아래 상자만 이름 칸이 비었다. 종착역 것이다.<br>
    도시락을 보면 누가 쌌는지 안다. 반찬 칸 나눈 모양, 밥 누른 세기.<br><br>
    다른 역 도시락은 공장 것이다. 종착역 도시락만 손으로 쌌다.`,
  o:[
    { l:'① 공장 도시락을 하나 뜯어 나눈다.', k:'heal', dc:19,
      ok:`공장 도시락 하나를 뜯었다. 밥, 장조림, 단무지. 장조림 고기가 넉넉하다.<br><br>밥은 다섯이 한 숟가락씩. 장조림 고기는 따로 싸 두었다. 다친 사람이 나오면 줄 것이다.<br>공장 밥은 맛이 없다. 그래도 정직하다. 아무도 무엇을 안 넣었다.`,
      ng:`뜯는 비닐 소리가 컸다.<br><br>우편 자루 더미 너머에서 자루 하나가 일어선다.<br>도시락을 놓고 물러났다. 자루가 도시락 쪽으로 기울었다. 그 틈에 빠져나왔다. 팔꿈치를 문틀에 찍었다.`,
      win:{ exp:15, dream:2, item:'짐승 고기' }, lose:{ hp:-22, mind:-12 } },
    { l:'② 손으로 싼 종착역 도시락을 연다.', k:'gaze', dc:21,
      ok:`뚜껑을 열었다. 밥 위에 반찬이 다섯 칸. 칸마다 작은 종이가 꽂혀 있다. 이쪽 일행 이름이다.<br><br>먹으라는 게 아니다. 자리를 정해 둔 것이다. 종착역에 내릴 다섯.<br>종이를 전부 뽑아 찢었다. 도시락은 맨 아래 상자 맨 아래에 도로 넣었다.<br><br>손으로 싼 밥에는 싼 사람의 마음이 든다. 이 마음은 먹지 않는다.`,
      ng:`여는데 밥 냄새가 확 난다. 갓 지은 밥이다. 손이 저절로 숟가락을 찾는다.<br><br>숟가락이 이미 꽂혀 있다. 다섯 개. 하나를 쥐었다. 손이 떨어지지 않는다.<br>일행이 손목을 비틀어 떼어 냈다. 손바닥이 데었다. 갓 지은 밥은 뜨겁다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-16 } }
  ] }

]);

// ── 치유사 (healer) · 마력 ──
kJob('healer', 'B', [

{ at:'B', t:'도망 중 — 멎지 않는 피',
  x:`뛰다가 동료가 넘어졌다. 허벅지 안쪽이 찢어졌다. 깨진 쇠붙이에.<br><br>
    피가 맥박에 맞춰 솟는다. 뒤에서는 발소리가 다가온다. 서두르지 않는 발소리다.<br>
    치유사는 피 색을 보면 어디가 터졌는지 안다. 검붉으면 기다려 주는 피고, 선홍이면 기다려 주지 않는 피다.<br><br>
    선홍이다.`,
  o:[
    { l:'① 동료를 부축해 뛰면서 손으로 누른다.', k:'heal', dc:20,
      ok:`동료 팔을 어깨에 걸고 다른 손 주먹을 상처에 박았다. 뛰었다.<br><br>주먹 밑에서 피가 맥을 친다. 누르는 힘을 한 번도 늦추지 않았다. 늦추면 그만큼 샌다.<br>모퉁이 셋을 돌아 숨었다. 주먹을 떼지 않은 채로 묶었다.<br><br>손목까지 붉다. 동료 얼굴은 하얗다. 하얀 얼굴이 아직 눈을 뜨고 있다.`,
      ng:`뛰는 동안 손이 미끄러졌다. 젖은 손은 피를 못 잡는다.<br><br>다시 누를 때마다 한 줌씩 샜다. 바닥에 점이 이어진다. 따라오는 발소리가 그 점을 밟는다.<br>숨은 자리 문틈 밑으로 피가 흘러 나갔다. 문 앞에서 발소리가 오래 머물렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 마력으로 터진 자리를 단숨에 닫는다.', k:'heal', dc:21, cost:{ mana:25 },
      ok:`상처에 손바닥을 덮고 마력을 한 점에 밀어 넣었다. 넓게 펴지 않았다. 터진 관 하나만.<br><br>손바닥 밑이 잠깐 희게 빛났다. 다른 손으로 그 빛을 가렸다. 어둠에서 빛은 부르는 소리다.<br>솟던 피가 멎었다. 살은 아직 벌어졌지만 관은 닫혔다.<br><br>동료를 일으켜 뛰었다. 뒤에서 발소리가 잠깐 멈췄다. 빛이 있던 자리를 찾는 것이다.`,
      ng:`마력이 손바닥에서 퍼졌다. 퍼진 마력은 빛이 된다.<br><br>희미한 빛이 골목 벽에 둥글게 번졌다. 상처는 반만 닫혔다.<br>빛을 보고 발소리가 빨라졌다. 처음으로. 동료를 끌다시피 해서 뛰었다. 이쪽 무릎이 깨졌다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 허리띠로 묶고 묶은 시각을 이마에 적는다.', k:'fix', dc:20, wake:1,
      ok:`허리띠를 풀어 상처 위 손 한 뼘에 감았다. 막대를 꽂아 돌렸다. 피가 멎을 때까지. 멎고 나서 반 바퀴 더.<br><br>시계를 봤다. 동료 이마에 숯으로 적었다. 묶은 시각. 이 띠는 오래 두면 다리를 죽인다. 몇 시에 묶었는지 아는 사람만 언제 풀지 안다.<br>둘이 동료를 업고 뛰었다. 이쪽이 쓰러져도 다음 손이 이마를 보면 된다.<br><br>상처에 시각을 붙였다. 피를 멈추는 손이 시간을 같이 쥐기 시작했다. 도망치는 동안에도 치료는 째깍거린다.`,
      ng:`막대가 부러졌다. 다시 꽂을 것을 찾는 사이 피가 다시 솟는다.<br><br>손으로 띠를 비틀어 쥐고 뛰었다. 손아귀가 풀릴 때마다 동료가 신음한다.<br>뒤를 돌아볼 겨를이 없었다. 발소리가 얼마나 가까웠는지 모른다. 숨은 뒤에야 손바닥 껍질이 다 벗겨진 걸 알았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'숨은 자리 — 참지 못하는 신음',
  x:`다 같이 좁은 틈에 숨었다. 밖에서 무언가 천천히 지나간다. 문을 하나씩 열어 보면서.<br><br>
    다친 동료가 신음한다. 이를 악물어도 새어 나온다. 부러진 팔이다.<br>
    아픔은 없앨 수 없어도 잠깐 미룰 수는 있다. 미룬 아픔은 나중에 한꺼번에 온다.<br><br>
    문 여는 소리가 하나 더 가까워졌다.`,
  o:[
    { l:'① 마력으로 팔의 아픔만 잠깐 끈다.', k:'heal', dc:20, cost:{ mana:22 },
      ok:`부러진 자리 위에 손가락 두 개를 얹었다. 마력을 아주 얇게. 뼈는 건드리지 않고 아픔이 올라가는 길만 덮었다.<br><br>신음이 멎었다. 동료가 눈을 크게 뜬다. 아픈 게 없어졌다고 입 모양으로 말한다.<br>문 여는 소리가 이쪽 문 앞에서 멈췄다. 한참. 지나갔다.<br><br>마력을 걷자 동료가 이쪽 소매를 문다. 미뤄 둔 아픔이 온 것이다. 그래도 그때는 밖에 아무것도 없었다.`,
      ng:`덮는데 마력이 뼈를 건드렸다.<br><br>동료 몸이 활처럼 휜다. 소리는 안 났다. 대신 발이 벽을 찼다. 쿵.<br>문 여는 소리가 멎었다. 그다음 이쪽 문고리가 돌았다. 모두가 동시에 숨을 멈췄다. 문은 반쯤 열렸다가 닫혔다. 왜 닫혔는지는 모른다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 손을 잡고 숨을 맞춰 준다.', k:'bond', dc:19,
      ok:`동료 손을 잡고 이마를 맞댔다. 숨을 아주 천천히 쉬었다. 따라 쉬라고.<br><br>들이쉬고, 참고, 내쉰다. 내쉴 때 신음을 같이 내보낸다. 소리 없이.<br>몇 번 만에 동료 숨이 이쪽 숨을 따라온다. 신음이 숨 속으로 들어갔다.<br><br>문 여는 소리가 지나갔다. 동료가 손을 놓지 않았다. 이쪽도 놓지 않았다.`,
      ng:`숨을 맞추는데 동료 숨이 자꾸 앞서간다. 겁먹은 숨이다.<br><br>참는 숨이 터졌다. 짧은 소리 하나. 밖의 소리가 멈췄다.<br>그 뒤로 아무 소리도 안 났다. 밖에 아직 서 있는지 떠났는지 몰라 새벽까지 움직이지 못했다. 다리가 굳었다.`,
      win:{ exp:15, dream:2, spirit:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'빗속의 낯선 사람 — 상처 없는 피',
  x:`빗속에서 남자가 비틀거리며 다가온다. 셔츠 앞이 피로 젖었다.<br><br>
    도와 달라고 한다. 찔렸다고. 쫓기고 있다고.<br>
    피 젖은 옷을 보면 피가 안에서 나왔는지 밖에서 묻었는지 안다. 안에서 나온 피는 옷 안쪽부터 번진다.<br><br>
    남자의 셔츠는 바깥이 진하다.`,
  o:[
    { l:'① 셔츠를 걷어 상처를 찾는다.', k:'heal', dc:21,
      doom:{ title:'걷은 셔츠', what:'낯선 남자에게 손목을 잡혔습니다', dc:17, sec:55,
        text:`셔츠를 걷었다. 배가 깨끗하다. 상처가 없다.<br><br>알아차린 순간 남자 손이 이쪽 손목을 잡았다. 맥 짚는 자리를 엄지로 누른다. 정확하게. 치료하는 사람의 잡는 법이다.<br>남자가 웃는다. 비가 입에 들어간다. 처음부터 다친 사람을 찾고 있던 게 아니다. 고치는 사람을 찾고 있었다.<br><br>골목 끝 승합차 문이 열린다. 끌려간다. 누가 저 엄지를 떼어 내야 한다.`,
        dieText:`치유사는 피를 보면 손부터 나간다.<br><br>그 손을 원하는 사람들이 있다. 오래 쓰려고.<br>골목 바닥의 핏물은 비에 다 씻겼다. 처음부터 남의 피였다.` },
      ok:`손을 뻗다 멈췄다. 피가 셔츠 바깥에 있다. 안이 아니라.<br><br>상처를 보여 달라고 했다. 남자가 셔츠 단추를 풀지 않는다. 대신 손을 내민다. 잡아 달라고.<br>손을 잡지 않았다. 뒤로 물러났다. 일행 쪽으로.<br><br>남자가 웃는다. 그리고 등을 돌려 빗속으로 걸어간다. 비틀거리지 않고.`,
      win:{ exp:18, dream:3 } },
    { l:'② 피가 마른 모양을 본다.', k:'gaze', dc:20,
      ok:`가까이 가지 않고 봤다. 빗물에 씻긴 데와 안 씻긴 데.<br><br>소매 끝은 말라서 갈색이다. 앞섶은 아직 붉다. 피가 두 번 묻었다. 한 번은 한참 전, 한 번은 방금.<br>방금 묻힌 피는 일부러 묻힌 피다.<br><br>도와주겠다고 하고 일행에게 눈짓했다. 남자가 앞장서는 길 말고 다른 길로 갔다. 남자는 따라오지 않았다. 따라올 필요가 없다는 듯이.`,
      ng:`보는 데 너무 오래 걸렸다.<br><br>남자가 그걸 알았다. 웃음이 사라졌다. 품에서 무언가를 꺼낸다.<br>뛰었다. 뒤에서 무엇이 날아와 등을 쳤다. 돌멩이였다. 등이 한동안 숨을 막았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'비 — 식어 가는 몸',
  x:`밤새 비를 맞았다. 숨을 곳은 찾았는데 불은 없다.<br><br>
    다들 떤다. 그중 하나는 떨지 않는다. 그게 더 나쁘다.<br>
    떨던 사람이 떨지 않으면 몸이 싸움을 그만둔 것이다. 그러면 말이 느려지고 졸리다고 한다.<br><br>
    그 사람이 졸리다고 한다.`,
  o:[
    { l:'① 마력으로 가슴 안쪽부터 데운다.', k:'heal', dc:20, cost:{ mana:24 },
      ok:`손바닥을 그 사람 가슴 한가운데 얹었다. 마력을 데워 안으로 밀었다. 팔다리가 아니라 심장 쪽부터.<br><br>겉을 먼저 데우면 찬 피가 한꺼번에 가슴으로 몰려온다. 그러면 멎는다. 안부터.<br>한참 뒤 그 사람이 다시 떨기 시작한다. 떠는 것을 보고 안심했다.<br><br>이쪽 손은 얼음처럼 식었다. 남을 데운 만큼 이쪽이 식는다.`,
      ng:`마력이 손바닥에서 겉으로만 돈다.<br><br>팔다리가 먼저 데워졌다. 찬 피가 가슴으로 밀려간다. 그 사람 숨이 턱 막힌다.<br>급히 손을 뗐다. 숨은 돌아왔다. 대신 이쪽 가슴이 오래 쿵쾅거렸다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 젖은 옷을 벗기고 다섯을 붙여 앉힌다.', k:'fix', dc:19,
      ok:`젖은 옷부터 벗겼다. 다들 싫어한다. 젖은 옷은 몸보다 빨리 열을 가져간다.<br><br>마른 것을 다 모아 깔고 덮었다. 졸린 사람을 가운데 앉히고 넷이 둘러쌌다.<br>졸지 말라고 계속 말을 시켰다. 이름, 사는 데, 좋아하는 음식.<br><br>새벽에 그 사람이 배고프다고 했다. 몸이 다시 싸우기 시작한 것이다.`,
      ng:`벗기는데 다들 손이 굳어 단추를 못 푼다.<br><br>하나씩 풀어 주는 사이 졸린 사람이 눈을 감았다. 흔들어도 대답이 늦다.<br>밤새 뺨을 두드리며 이름을 불렀다. 이쪽 목이 쉬었다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'시계 — 남은 마력, 남은 시간',
  x:`잠깐 숨을 돌렸다. 시계를 봤다. 끝까지 몇 시간 남았다.<br><br>
    다들 어딘가 다쳤다. 깊은 것 둘, 얕은 것 여럿.<br>
    제 마력이 얼마 남았는지는 손끝의 저림으로 안다. 지금은 많이 저리다.<br><br>
    마력은 하나다. 다친 사람은 다섯이다. 시간은 계속 간다.`,
  o:[
    { l:'① 남은 시간을 쪼개 마력도 쪼갠다.', k:'fix', dc:20, wake:1,
      ok:`남은 시간을 넷으로 나눴다. 쉬는 자리마다 한 번씩. 마력도 넷으로.<br><br>지금 다 쓰면 지금은 낫는다. 마지막 문 앞에서는 아무것도 없다. 마지막 문 앞이 제일 험하다.<br>지금은 깊은 둘의 피만 멈췄다. 얕은 것은 묶기만 했다.<br><br>마력을 손끝이 아니라 시계로 쟀다. 얼마나 남았는지가 아니라 언제까지 남겨야 하는지로. 손이 오늘이 아니라 끝까지를 고치기 시작했다.`,
      ng:`쪼개는 사이 얕은 상처 하나가 덧났다.<br><br>얕은 줄 알았던 것이 깊었다. 아껴 둔 마력을 거기 다 썼다.<br>셈이 무너졌다. 남은 시간에 남은 마력이 없다. 손끝이 더는 저리지도 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 가장 깊은 하나에게 몰아준다.', k:'heal', dc:21, cost:{ mana:28 },
      ok:`가장 깊은 상처 앞에 앉았다. 옆구리를 길게 그은 상처다. 남은 마력을 거의 다 부었다.<br><br>살이 안쪽부터 붙는다. 그 사람이 처음으로 똑바로 앉는다.<br>나머지 넷은 묶기만 했다. 넷 다 아무 말도 하지 않았다.<br><br>그 사람이 나중에 이쪽을 업었다. 이쪽이 쓰러졌을 때. 마력이 그렇게 돌아왔다.`,
      ng:`몰아붓는데 상처가 마력을 다 먹고도 닫히지 않는다.<br><br>깊은 상처는 마력으로 다 안 된다. 반쯤 닫히고 멈췄다.<br>마력은 바닥났다. 눈앞이 하얗게 비었다. 일어나다 넘어져 턱을 찧었다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B', t:'젖은 바닥 — 묽은 핏방울',
  x:`바닥에 핏방울이 이어진다. 젖은 바닥 위에서 번졌다.<br><br>
    빗물에 섞여 분홍이다. 같은 간격으로 앞으로 간다.<br>
    피는 물에 섞여도 얼마나 흘렸는지 말해 준다. 번진 둘레와 가운데 진한 점의 크기로.<br><br>
    이쪽 일행은 아무도 피를 흘리지 않는다. 지금은.`,
  o:[
    { l:'① 번진 둘레로 흘린 양을 잰다.', k:'gaze', dc:20,
      ok:`쪼그려 앉아 방울 셋을 봤다. 가운데 점이 처음엔 크고 갈수록 작다.<br><br>흘린 사람은 지금 거의 다 흘렸다. 그런데 간격은 그대로다. 걸음이 안 느려졌다.<br>그만큼 흘리고도 같은 걸음으로 걷는 것은 사람이 아니다. 아니면 흘린 게 걷는 쪽 피가 아니다. 들고 가는 쪽 피다.<br><br>핏자국 반대쪽으로 길을 잡았다.`,
      ng:`보는데 방울 하나가 눈앞에 떨어졌다. 새것이다.<br><br>위를 봤다. 아무것도 없다. 천장이 어둡다.<br>그 뒤로 일행 모두 천장만 보며 걸었다. 발밑을 못 봐서 둘이 넘어졌다. 이쪽은 손목을 접질렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 따라가서 다친 사람을 찾는다.', k:'sense', dc:21,
      doom:{ title:'핏자국 끝', what:'피를 흘리는 것에게 끌려갑니다', dc:17, sec:50,
        text:`따라갔다. 다친 사람이 있으면 가는 손이다.<br><br>핏자국이 막다른 벽에서 끝난다. 벽 앞에 누가 앉아 있다. 등을 보이고. 피는 거기서 떨어진다.<br>다가가 어깨에 손을 얹었다. 어깨가 차다. 그 사람이 손을 덮는다. 꽉.<br><br>앉은 자세 그대로 벽 쪽으로 미끄러진다. 이쪽을 끌고. 벽에 문이 있었다. 누가 이쪽 허리를 잡아야 한다.`,
        dieText:`피를 흘리는 사람이 있으면 치유사는 간다.<br><br>그걸 아는 것이 피를 흘려 두었다. 같은 간격으로, 같은 양으로.<br>다음 날 바닥에 핏자국이 새로 이어졌다. 조금 더 진하게.` },
      ok:`따라가다 셋째 모퉁이에서 멈췄다. 핏자국이 너무 고르다.<br><br>다친 사람은 고르게 못 흘린다. 비틀대면 몰리고 쉬면 고인다. 이건 고인 데가 한 군데도 없다.<br>누가 흘려 둔 것이다. 따라오라고.<br><br>되돌아 나왔다. 등 뒤에서 무언가 한숨 쉬는 소리가 났다. 놓친 것을 아쉬워하는 소리였다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'B', t:'잠긴 방 — 숨을 못 쉬는 동료',
  x:`문이 밖에서 잠겼다. 창이 없다. 다들 문을 두드리다 지쳤다.<br><br>
    동료 하나가 갑자기 숨을 못 쉰다. 가슴을 쥐어뜯는다. 숨이 모자라다고, 벽이 다가온다고 한다.<br>
    다친 곳 없는 사람이 숨을 못 쉬면 까닭은 하나다. 방에 공기는 있다. 그 사람 안에 공포가 찼다.<br><br>
    공포도 상처처럼 번진다. 벌써 둘째가 숨을 몰아쉰다.`,
  o:[
    { l:'① 손바닥을 가슴에 얹고 숨을 세어 준다.', k:'heal', dc:20, wake:1,
      ok:`동료 손을 가슴에서 떼고 이쪽 손바닥을 얹었다. 넷 세고 들이쉬라고. 넷 참고. 여섯 세고 내쉬라고.<br><br>처음엔 둘에서 끊긴다. 다시. 셋. 다시. 넷.<br>손바닥 밑 가슴이 느려진다. 둘째도 따라 센다. 방 안의 숨이 하나로 모였다.<br><br>상처가 안 보이는 데도 상처가 있다. 손이 그 자리를 처음으로 정확히 짚었다. 피 대신 숨을 멈추게 하는 상처를 다루는 법이 손에 들어왔다.`,
      ng:`세는데 동료가 이쪽 손을 뿌리친다. 만지지 말라고.<br><br>손을 거두자 더 몰아쉰다. 둘째, 셋째. 방 안이 숨소리로 찬다.<br>문밖에서 누가 그 소리를 듣고 웃었다. 낮게. 한참 듣다가 갔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 마력으로 잠재운다.', k:'steady', dc:19, cost:{ mana:22 },
      ok:`이마에 손을 얹고 마력을 아주 무겁게 내려놓았다. 잠은 무게로 온다.<br><br>동료가 스르르 기대 잠든다. 숨이 고르다.<br>문제는 잠든 사람은 못 뛴다는 것이다. 문이 열리면 업어야 한다.<br><br>문은 한 시간 뒤에 열렸다. 업었다. 무거웠다. 그래도 숨은 고르게 쉬는 무게였다.`,
      ng:`마력이 무겁게 내려앉다가 동료가 버둥거렸다. 잠드는 게 무섭다고.<br><br>잠과 공포가 같이 왔다. 반쯤 잠든 채로 비명을 지른다.<br>입을 막았다. 손바닥을 물렸다. 이빨 자국이 깊다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B', t:'마지막 쉼 — 자기 몫',
  x:`마지막 문 앞에서 쉬었다. 옷을 여미다 알았다.<br><br>
    갈비뼈 밑이 젖어 있다. 언제 다쳤는지 모른다. 계속 남의 상처만 봤다.<br>
    남의 상처는 다 세면서 자기 것은 못 센다. 고치는 사람은 다 그렇다.<br><br>
    마력이 조금 남았다. 딱 한 사람 몫이다.`,
  o:[
    { l:'① 남은 마력을 자기에게 쓴다.', k:'heal', dc:20, cost:{ mana:20 },
      ok:`손바닥을 자기 옆구리에 댔다. 남의 상처 보듯 봤다. 깊이, 방향, 걸린 시간.<br><br>마력을 밀었다. 남에게 밀 때보다 어렵다. 제 몸은 제 마력을 낯설어한다.<br>그래도 닫혔다. 나머지 길을 걸을 만큼은.<br><br>마지막 문 너머에서 누가 다쳐도 이쪽이 서 있어야 묶어 준다. 그래서 썼다. 변명은 아니다.`,
      ng:`손을 대는데 마력이 미끄러진다. 제 몸에 안 든다.<br><br>남은 마력이 다 흩어졌다. 상처는 그대로다.<br>천으로 꽉 묶었다. 걸음마다 숨이 걸린다.`,
      win:{ exp:16, hp:12 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 아무에게도 말하지 않고 동여맨다.', k:'steady', dc:19,
      ok:`천으로 꽉 동이고 말하지 않았다. 다들 마지막 문 앞에서 겁먹었다. 고치는 사람까지 다치면 더 겁먹는다.<br><br>남은 마력은 그대로 남겼다. 문 너머를 위해.<br>문 너머에서 동료 하나가 손을 베였다. 그 마력으로 닫았다.<br><br>그 뒤로 이쪽 옆구리는 계속 젖었다. 아무도 몰랐다.`,
      ng:`동여매다 피가 천을 뚫고 배어 나왔다.<br><br>동료가 봤다. 다들 얼굴이 하얘진다. 숨긴 것이 더 큰 겁이 됐다.<br>문 앞에서 다들 머뭇거렸다. 머뭇거린 만큼 시간이 갔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 동료에게 묶는 법을 가르친다.', k:'bond', dc:20, wake:1,
      ok:`옆의 동료를 불렀다. 천을 쥐여 주고 손을 잡고 같이 묶었다. 어디를 누르고 어느 쪽으로 감는지.<br><br>동료 손이 떨린다. 떨리면서도 맞게 감는다. 두 번째는 혼자 감았다. 세 번째는 이쪽이 말하기 전에 감았다.<br>남은 마력은 남겨 두었다. 이제 고치는 손이 둘이다.<br><br>제 손으로 다 하던 일을 남의 손에 나눠 주었다. 그러자 고칠 수 있는 범위가 넓어졌다. 손이 하나가 아니라는 걸 손이 배웠다.`,
      ng:`가르치는데 동료가 천을 너무 세게 감는다.<br><br>숨이 막힌다. 풀라고 하는데 목소리가 안 나온다. 손짓으로 겨우 풀게 했다.<br>다시 감을 시간이 없었다. 느슨한 채로 문을 열었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 하얀 손가락',
  x:`냉동 창고에 갇혔다가 겨우 나왔다. 동료 손가락이 하얗다. 밀랍 같다.<br><br>
    동료가 손을 비비려 한다. 다른 사람들은 입김을 불어 준다.<br>
    언 살은 비비면 얼음 결정이 살을 찢는다. 급히 데워도 찢는다.<br><br>
    창고 밖은 비다. 데울 불도 없다.`,
  o:[
    { l:'① 겨드랑이에 넣어 천천히 녹인다.', k:'heal', dc:20,
      ok:`비비는 손목을 잡아 내렸다. 이쪽 옷을 열고 겨드랑이에 동료 손을 넣었다.<br><br>차다. 얼음을 품은 것 같다. 이를 악물고 기다렸다. 오래.<br>손가락에 붉은 기가 돌더니 동료가 신음한다. 아프다고. 아프다는 건 피가 돌아온다는 뜻이다.<br><br>새끼손가락 끝 하나는 끝내 하얗다. 나머지는 살았다.`,
      ng:`넣었는데 동료가 손을 뺀다. 너무 아프다고.<br><br>빼서 비볐다. 말리기 전에. 살갗에 물집이 잡힌다.<br>억지로 다시 넣었다. 늦었다. 손가락 둘이 검게 변해 간다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 다들 손을 비비지 못하게 막는다.', k:'steady', dc:19,
      ok:`다들 손을 비비고 있다. 다섯 다. 하나씩 손목을 잡아 내렸다.<br><br>비비지 말라고, 주머니에 넣고 기다리라고. 다들 짜증을 낸다. 비비면 덜 아프니까.<br>덜 아픈 쪽이 다치는 쪽이다. 끝까지 막았다.<br><br>한 시간 뒤 다섯 손에 다 색이 돌았다. 짜증 낸 사람도 고맙다고는 안 했다. 대신 다음엔 안 비볐다.`,
      ng:`막는데 한 사람이 뿌리친다. 비벼야 산다고 우긴다.<br><br>실랑이가 커졌다. 목소리가 커졌다. 창고 쪽에서 문 열리는 소리가 났다.<br>다 같이 엎드렸다. 언 손으로 젖은 바닥을 짚었다. 손바닥이 쩍 들러붙었다 떨어졌다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 어깨에 박힌 낚싯바늘',
  x:`경매장 바닥을 기다가 동료가 걸렸다. 걸어 둔 줄낚시에.<br><br>
    큰 바늘이 어깨 살에 박혔다. 끝이 갈고리로 굽었다. 미늘이 있다.<br>
    미늘 있는 것은 온 길로 빼면 안 된다. 살을 같이 뜯어 온다.<br><br>
    동료가 바늘을 잡고 당기려 한다. 이층 사무실에 불이 켜져 있다.`,
  o:[
    { l:'① 바늘을 앞으로 밀어 미늘을 내보내고 끊는다.', k:'heal', dc:20, wake:1,
      ok:`당기는 손을 잡았다. 바늘 굽은 방향을 봤다. 온 길이 아니라 가던 길로 보내야 한다.<br><br>바늘 등을 눌러 앞으로 밀었다. 살을 뚫고 미늘이 밖으로 나온다. 동료가 소매를 문다.<br>나온 미늘을 경매장 칼로 쳐 끊었다. 그다음에야 바늘을 뒤로 뺐다. 미끄럽게.<br><br>빼는 길이 아니라 나가는 길을 보았다. 상처를 보던 눈이 상처 낸 것의 모양을 먼저 보기 시작했다.`,
      ng:`밀다가 바늘이 뼈에 닿았다. 더 안 나간다.<br><br>동료가 비명을 삼키다 수조를 걷어찼다. 물 쏟아지는 소리. 이층 창이 열린다.<br>바늘을 꽂은 채로 끌고 숨었다. 걸을 때마다 줄이 흔들려 살을 당긴다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 마력으로 살을 느슨하게 풀어 빼낸다.', k:'heal', dc:21, cost:{ mana:25 },
      ok:`바늘 둘레 살에 마력을 스미게 했다. 단단히 문 살이 풀린다. 미늘이 걸린 자리가 물러진다.<br><br>천천히 돌려 뺐다. 미늘에 살점 하나 안 묻었다.<br>마력을 걷자 살이 다시 오므라든다. 구멍만 남았다. 소금물로 씻고 묶었다.<br><br>바늘은 바닥에 버리지 않았다. 줄째 감아 챙겼다. 다음에 걸릴 사람이 없게.`,
      ng:`살을 풀었는데 너무 풀었다.<br><br>상처가 벌어진다. 피가 쏟아진다. 바늘은 빠졌지만 구멍이 손가락만 하다.<br>꽉 눌러도 한참 샜다. 경매장 바닥에 핏물이 생선 피와 섞였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 동료 입을 막고 단번에 잡아 뺀다.', k:'break', dc:20,
      ok:`동료 입에 천을 물리고 눈짓했다. 하나, 둘. 셋에 뺐다. 단번에.<br><br>살이 조금 따라 나왔다. 그래도 빨랐다. 빠른 아픔은 짧다.<br>상처를 눌러 묶었다. 이층 창은 열리지 않았다.`,
      ng:`셋에 당기는데 바늘이 안 나온다.<br><br>미늘이 걸렸다. 동료가 천을 뱉고 소리를 지른다. 짧고 날카롭게.<br>이층 창이 열렸다. 회색 비옷 하나가 내려다본다. 둘이 다 엎드렸다. 이쪽 손바닥에 바늘 끝이 박혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B1', t:'야적장 — 떨어진 사람',
  x:`크레인 사다리에서 사람이 떨어졌다. 이쪽 일행이 아니다. 먼저 와서 숨어 있던 사람이다.<br><br>
    컨테이너 사이 바닥에 등을 대고 누웠다. 눈은 떴다. 다리가 움직이지 않는다고 한다.<br>
    치유사는 떨어진 사람을 함부로 일으키지 않는다. 등뼈가 다쳤으면 일으키는 순간 끝난다.<br><br>
    탐조등이 돌고 있다. 다음 바퀴에 이 골목을 비춘다.`,
  o:[
    { l:'① 목을 받치고 판자에 묶어 다 같이 옮긴다.', k:'fix', dc:21,
      ok:`부서진 팔레트 판자를 끌어왔다. 목을 두 손으로 받친 채 넷에게 자리를 정해 줬다. 어깨, 허리, 무릎, 발목.<br><br>셋에 다 같이 굴려 판자에 올렸다. 통나무처럼. 등뼈가 한 번도 꺾이지 않게.<br>판자째 들고 컨테이너 그늘로 옮겼다. 탐조등이 방금 누웠던 자리를 비춘다.<br><br>그 사람이 고맙다고 한다. 그리고 말해 준다. 저 크레인 위에서 정문이 보인다고. 정문 경비가 다섯 시에 바뀐다고.`,
      ng:`셋에 굴리는데 한 사람이 늦었다.<br><br>허리가 꺾였다. 누운 사람이 짧게 숨을 들이켠다. 그 뒤로 다리 이야기를 안 한다.<br>탐조등이 골목을 비췄다. 판자를 놓고 흩어졌다. 그 사람은 판자 위에 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 손끝으로 등뼈를 더듬어 본다.', k:'gaze', dc:20,
      ok:`등 밑으로 손을 넣어 뼈마디를 하나씩 짚었다. 목부터 아래로.<br><br>허리 위 셋째 마디에서 그 사람이 움찔한다. 거기다. 그런데 발가락을 꼬집으니 오므린다. 끊어지진 않았다.<br>끊어지지 않은 건 업을 수 있다. 똑바로만 업으면.<br><br>등을 곧게 펴 업고 탐조등 반대쪽으로 갔다. 업힌 사람이 발가락을 계속 꼼지락거렸다. 살아 있다고 알려 주듯.`,
      ng:`짚는데 그 사람이 비명을 지른다. 짧게.<br><br>탐조등이 멈췄다. 그리고 이쪽으로 돈다.<br>손을 빼고 굴렀다. 컨테이너 밑으로. 빛이 그 사람만 비췄다. 그 사람이 빛 속에서 이쪽을 봤다. 오래 그 눈을 잊지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B1', t:'수로 — 물 먹은 동료',
  x:`방파제 수로 판자가 꺼졌다. 동료 하나가 물에 빠졌다.<br><br>
    검은 물이다. 기름이 떠서 무지갯빛이 돈다. 물살이 창살 쪽으로 빨려 간다.<br>
    물에 빠진 사람이 버티는 시간은 정해져 있다. 숨을 참는 시간과 숨을 놓는 시간.<br><br>
    동료가 한 번 떠올랐다가 다시 가라앉았다.`,
  o:[
    { l:'① 그대로 뛰어든다.', k:'bond', dc:21,
      doom:{ title:'검은 물', what:'수로 아래로 끌려 들어갑니다', dc:17, sec:50,
        text:`뛰어들었다. 물이 차다. 눈을 떠도 아무것도 안 보인다.<br><br>손을 휘젓다 옷자락을 잡았다. 당겼다. 동료가 딸려 온다. 같이 위로.<br>그런데 위로 안 간다. 물살이 둘을 창살 쪽으로 민다. 창살 밑은 더 깊다.<br><br>동료를 위로 밀어 올렸다. 그만큼 이쪽이 내려간다. 발목이 창살에 걸렸다. 누가 줄을 던져야 한다.`,
        dieText:`고치는 사람은 물에 빠진 사람을 보면 숨부터 생각한다. 제 숨은 나중이다.<br><br>동료는 판자 위로 끌려 올라왔다. 기침을 하며 살았다.<br>창살 너머로 기름 무지개가 한참 돌았다. 새벽 물때가 바뀔 때까지.` },
      ok:`뛰어들기 전에 밧줄 끝을 판자 기둥에 감았다. 반대쪽을 허리에 감고 뛰어들었다.<br><br>물살이 창살로 민다. 줄이 팽팽해진다. 버텼다. 옷자락을 잡아 끌어안았다.<br>위에서 일행이 줄을 당겼다. 둘이 같이 판자 위로 올라왔다.<br><br>동료가 숨을 안 쉰다. 눕히고 숨을 불어 넣었다. 네 번째에 물을 토했다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 다 같이 건져 올린 뒤 숨을 불어 넣는다.', k:'heal', dc:20,
      ok:`뛰어들려는 일행을 붙잡았다. 장대를 찾아 물에 넣었다. 다 같이 휘저어 걸었다.<br><br>옷이 걸렸다. 끌어 올렸다. 숨을 안 쉰다. 입술이 파랗다.<br>고개를 젖히고 숨을 불어 넣었다. 가슴을 눌렀다. 서른 번, 두 번, 서른 번.<br><br>세 바퀴째에 물을 토했다. 기름 섞인 물이다. 등을 두드려 다 뱉게 했다.`,
      ng:`장대를 찾는 사이 시간이 갔다.<br><br>건졌을 때는 이미 늦은 쪽에 가깝다. 숨을 불어 넣었다. 누르고, 불고. 오래.<br>숨이 돌아왔다. 한참 늦게. 눈을 뜬 동료가 이쪽 이름을 기억하지 못했다. 이쪽 손목이 누르느라 삐었다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'처치실 — 남이 놓은 주사',
  x:`처치실 침대에서 동료를 찾았다. 팔에 반창고가 붙었다. 누가 주사를 놓았다.<br><br>
    눈은 뜨고 있는데 이쪽을 못 알아본다. 동공이 바늘 끝만 하다. 숨이 느리다.<br>
    남이 놓은 약을 다 알 수는 없다. 다만 약이 몸에서 하는 일은 보인다. 지금 이 약은 숨을 줄이고 있다.<br><br>
    복도 시계가 정각 십 분 전이다.`,
  o:[
    { l:'① 일으켜 세워 걷게 하며 깨운다.', k:'steady', dc:20,
      ok:`동료를 일으켜 어깨에 걸었다. 걸렸다. 다리가 질질 끌린다. 그래도 걸게 했다.<br><br>걸으면 숨이 깊어진다. 깊어진 숨이 약을 밀어낸다. 처치실 안을 열 바퀴 돌았다.<br>열 바퀴째에 동료가 이쪽 이름을 불렀다. 틀린 이름이다. 그래도 사람 이름이다.<br><br>정각 일 분 전에 처치실을 나왔다.`,
      ng:`걷게 하는데 동료 무릎이 계속 꺾인다.<br><br>둘이 같이 쓰러졌다. 약품 선반이 흔들려 유리병이 떨어졌다. 깨지는 소리.<br>복도에서 딸깍 소리가 빨라진다. 동료를 끌고 침대 밑으로 들어갔다. 깨진 유리에 무릎이 베였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 마력으로 핏속의 낯선 것을 찾아 몬다.', k:'heal', dc:21, cost:{ mana:28 }, wake:1,
      ok:`반창고 자리에 손을 대고 마력을 핏줄을 따라 흘렸다. 낯선 것을 찾았다.<br><br>있다. 피와 섞이지 않고 흐르는 것. 마력에 닿으면 아주 조금 차다. 그 찬 것을 한 방향으로 몰았다. 주삿바늘 자리로.<br>반창고를 떼고 그 자리를 꾹 눌렀다. 투명한 방울이 하나 맺혔다. 닦아 냈다. 동공이 커진다.<br><br>상처가 없는 데서 병을 찾았다. 마력이 살을 닫는 일에서 피를 읽는 일로 한 걸음 넘어갔다.`,
      ng:`마력을 흘리는데 낯선 것이 마력을 탄다.<br><br>찬 기운이 이쪽 손으로 거슬러 올라온다. 팔꿈치까지. 손을 뗐다.<br>이쪽 손가락이 굳었다. 동료는 그대로다. 둘 다 정각을 처치실에서 맞았다. 숫자는 그 방에서 셌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'간호사실 — 이상하게 말린 붕대',
  x:`간호사실 선반에 붕대가 가득하다. 하얗고 새것이다.<br><br>
    소독약, 거즈, 반창고. 처치 상자도 있다. 다 정리가 잘 되어 있다.<br>
    붕대 말린 모양을 보면 무엇에 쓰려고 말았는지 안다. 상처에 쓸 붕대는 느슨하게, 끝을 안으로 접어 만다.<br><br>
    여기 붕대는 전부 팽팽하게 말렸다. 끝이 고리로 묶였다.`,
  o:[
    { l:'① 붕대를 하나 풀어 본다.', k:'gaze', dc:20,
      ok:`하나를 풀었다. 길다. 상처에 쓰기엔 너무 길다. 그리고 두껍다.<br><br>끝의 고리는 손목 굵기다. 다른 쪽 끝에도 고리가 있다. 침대 난간 굵기.<br>붕대가 아니다. 묶는 끈이다. 하얗게 만들어 붕대처럼 둔 것이다.<br><br>처치 상자를 열어 봤다. 거즈는 없다. 고리 묶인 붕대만 가득하다. 이 병동에서 치료라는 말은 묶는다는 말이다.`,
      ng:`푸는데 붕대가 손목에 감긴다. 저절로 감긴 건 아니다. 너무 팽팽하게 말려 있어서 튕겼다.<br><br>고리가 손목을 조인다. 빼는 데 한참 걸렸다. 손목에 하얀 자국이 남았다.<br>그사이 간호사실 문이 열렸다. 흰 모자가 이쪽 손목의 자국을 봤다. 숫자를 하나 적었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 쓸 만한 것을 골라 챙긴다.', k:'luck', dc:19,
      ok:`선반 맨 아래 칸에 상자 하나가 다르다. 먼지가 앉았다. 오래 아무도 안 열었다.<br><br>열었다. 진짜 거즈, 진짜 소독약. 유통 기한이 몇 해 지났다. 소독약은 아직 코를 찌른다.<br>여기에도 한때 진짜 간호사가 있었다. 마지막으로 이 상자를 채운 사람.<br><br>상자째 챙겼다.`,
      ng:`맨 아래 칸에 손을 넣는데 무언가 손가락을 문다.<br><br>쥐덫이다. 누가 거기 놓았다. 손을 넣을 사람을 알고.<br>손가락 둘이 부어올랐다. 덫이 철컥한 소리에 복도 딸깍 소리가 멈췄다.`,
      win:{ exp:15, dream:2, hp:8 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B2', t:'병실 — 묶인 사람의 손목',
  x:`안쪽 병실 침대에 사람이 묶여 있다. 손목과 발목. 하얀 끈으로.<br><br>
    손목이 짓물렀다. 오래 묶였다. 끈 밑 살이 검붉다.<br>
    끈 자국을 보면 얼마나 묶여 있었는지 안다. 이건 몇 주다.<br><br>
    그 사람이 눈을 뜬다. 이쪽을 보고 입술을 움직인다. 소리는 안 난다.`,
  o:[
    { l:'① 끈은 두고 짓무른 자리만 돌본다.', k:'heal', dc:20,
      ok:`끈을 풀지 않았다. 풀면 다음 정각에 빈 침대가 된다. 빈 침대는 센다.<br><br>끈과 살 사이에 깨끗한 천을 끼웠다. 짓무른 자리를 물로 씻고 꿀을 얇게 발랐다. 끈을 반 칸만 느슨하게.<br>그 사람이 입술로 말한다. 이번엔 알아들었다. 『세탁실. 지하. 슈트.』<br><br>세탁물 내리는 통로다. 사람이 들어갈 만한.`,
      ng:`천을 끼우는데 그 사람이 아파서 몸을 비튼다.<br><br>침대가 삐걱인다. 난간이 벽을 친다. 쿵, 쿵.<br>복도 딸깍 소리가 이쪽으로 꺾인다. 침대 밑에 숨었다. 침대 위 사람이 이쪽 대신 대답했다. 정각 점검에. 아주 순하게. 그 목소리가 오래 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 끈을 풀어 준다.', k:'fix', dc:21,
      ok:`매듭을 하나씩 풀었다. 병원 매듭은 풀라고 묶은 게 아니다. 오래 걸렸다.<br><br>풀린 손목을 그 사람이 한참 쳐다본다. 그리고 이쪽 손에 무언가를 쥐여 준다. 열쇠다. 작은 것. 약장 열쇠라고 한다.<br>그 사람은 침대에서 내려오지 않았다. 다시 누워 끈을 손목에 느슨하게 감았다. 숫자를 맞추려고.<br><br>풀어 준 손으로 스스로 다시 묶었다. 그게 이 병동의 정답이었다.`,
      ng:`매듭이 안 풀린다. 당길수록 조인다.<br><br>그 사람이 신음한다. 끈이 짓무른 데를 판다.<br>손을 뗐을 때 처음보다 더 조여 있었다. 풀려던 손이 더 묶었다. 그 사람이 눈을 감았다. 이쪽을 다시 보지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B2', t:'정각 전 — 열이 오르는 동료',
  x:`동료 이마가 뜨겁다. 처치실에서 맞은 무언가 때문이다. 열이 오른다.<br><br>
    복도 끝 화이트보드에 적혀 있다. 『발열 환자는 정각 점검 시 처치실로.』<br>
    열을 내리는 법은 안다. 시간이 있으면.<br><br>
    정각까지 이십 분. 간호사는 점검 때 이마에 손을 댄다.`,
  o:[
    { l:'① 젖은 천으로 목과 겨드랑이를 식힌다.', k:'heal', dc:20, wake:1,
      ok:`세면대 물에 천을 적셔 목 옆, 겨드랑이, 사타구니에 댔다. 큰 핏줄이 지나는 자리다. 이마는 나중이다.<br><br>천이 미지근해지면 바꿨다. 이십 분 동안 열네 번.<br>정각 일 분 전에 마지막으로 이마를 닦았다. 손등을 대 보니 미지근하다. 간호사의 손은 차다. 찬 손에는 미지근한 이마가 정상이다.<br><br>점검이 지나갔다. 딸깍. 열을 내린 게 아니라 정각에 맞췄다. 치료가 시계와 맞물리는 걸 손이 알았다.`,
      ng:`천을 바꾸는데 물이 미지근하다. 세면대 물이 데워져 나온다.<br><br>찬물이 안 나온다. 누가 그렇게 해 두었다.<br>정각에 간호사 손이 동료 이마에 닿았다. 멈췄다. 계수기 대신 펜을 꺼낸다. 동료 이름 옆에 무언가를 적었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 마력으로 열을 손바닥으로 끌어낸다.', k:'heal', dc:21, cost:{ mana:24 },
      ok:`이마에 손을 얹고 마력을 거꾸로 돌렸다. 주는 게 아니라 받는 쪽으로.<br><br>열이 이쪽 손바닥으로 넘어온다. 손이 뜨거워진다. 팔이, 어깨가.<br>동료 이마가 식었다. 이쪽 이마가 뜨겁다.<br><br>정각에 간호사가 동료 이마를 짚고 지나갔다. 이쪽 이마는 짚지 않았다. 이쪽은 침대에 누운 사람이 아니라 보호자 의자에 앉은 사람이었다.`,
      ng:`끌어내는데 열이 이쪽으로 안 넘어온다. 대신 마력이 저쪽으로 빨려 간다.<br><br>손을 뗐다. 동료 이마는 더 뜨겁다. 마력이 열에 기름을 부었다.<br>정각이 왔다. 간호사가 동료를 데려갔다. 다음 점검 전에 찾으러 가야 한다. 그 일이 하나 늘었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B3', t:'침대칸 — 커튼 너머 신음',
  x:`8호차 침대칸 통로를 지났다. 커튼이 다 쳐졌다.<br><br>
    한 칸에서 신음이 난다. 낮고 길게. 다친 사람 소리다.<br>
    치유사는 신음을 들으면 어디가 아픈지 반은 안다. 배를 다친 사람은 숨을 짧게 끊는다. 머리를 다친 사람은 같은 말을 되풀이한다.<br><br>
    이 신음은 둘 다 아니다. 처음부터 끝까지 높낮이가 똑같다.`,
  o:[
    { l:'① 커튼을 젖히고 들여다본다.', k:'heal', dc:21,
      doom:{ title:'젖힌 커튼', what:'커튼 안으로 끌려 들어갑니다', dc:17, sec:55,
        text:`커튼을 젖혔다. 침대에 사람이 누워 있다. 이불을 머리까지 덮었다.<br><br>이불을 걷으려는데 신음이 멈췄다. 이불 밑에서 손이 나와 이쪽 손목을 잡는다. 맥 짚는 자리를.<br>잡힌 채 침대 안으로 당겨진다. 커튼이 등 뒤에서 닫힌다. 레일 고리가 촤르륵 미끄러진다.<br><br>커튼 너머에서 다시 신음이 시작된다. 이번엔 이쪽 목소리로. 누가 커튼을 찢어야 한다.`,
        dieText:`다친 사람 소리가 나면 커튼을 젖히는 손이 있다.<br><br>그 칸은 그 소리를 낼 줄 알았다. 오래 연습했다.<br>8호차 통로에 신음이 하나 늘었다. 높낮이가 똑같은.` },
      ok:`커튼 손잡이를 잡았다가 놓았다. 신음이 너무 고르다.<br><br>아픈 사람은 숨이 차면 신음이 끊긴다. 이건 끊기지 않는다. 숨을 안 쉬고 내는 소리다.<br>커튼 앞을 지나갔다. 발소리를 죽이고.<br><br>지나고 나서 신음이 멈췄다. 커튼 밑으로 맨발 하나가 나와 바닥을 더듬었다. 놓친 것을 찾듯이.`,
      win:{ exp:18, dream:3 } },
    { l:'② 커튼 너머로 어디가 아프냐고 묻는다.', k:'sense', dc:20,
      ok:`커튼에서 한 걸음 떨어져서 물었다. 어디가 아프냐고.<br><br>신음이 멈췄다. 한참 있다 대답한다. 『여기.』 어디인지 말하지 않는다. 다친 사람은 어디가 아픈지 먼저 말한다. 손으로 짚으며.<br>다시 물었다. 『어디요.』 대답이 똑같다. 『여기.』 같은 높이로.<br><br>통로를 빠르게 지나갔다. 등 뒤에서 『여기』가 몇 번 더 들렸다. 조금씩 가까워지며.`,
      ng:`묻자 신음이 멈추고 커튼이 조금 벌어진다.<br><br>벌어진 틈으로 눈이 하나 보인다. 이쪽 눈 높이에. 깜박이지 않는다.<br>뒷걸음질 치다 맞은편 침대 사다리에 등을 찧었다. 숨이 한동안 안 쉬어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B3', t:'특실 복도 — 꿰맨 자리',
  x:`특실 복도에서 일행이 흩어졌다가 다시 모였다. 다섯이다. 맞다.<br><br>
    그런데 한 사람 얼굴이 이상하다. 아니다. 얼굴은 똑같다. 이상한 건 이쪽 손끝이다. 만지기 싫다.<br>
    오늘 치료한 상처는 다 기억한다. 누구의 어디를 몇 바늘 꿰맸는지.<br><br>
    저 사람 왼손 손등. 아까 세 바늘 꿰맸다.`,
  o:[
    { l:'① 다친 손을 다시 보자며 왼손을 잡는다.', k:'gaze', dc:20, wake:1,
      ok:`손등 실밥 좀 보자고 했다. 그 사람이 손을 내민다. 오른손을.<br><br>왼손이라고 했다. 왼손을 내민다. 손등이 매끈하다. 실밥도, 자국도 없다. 얼굴은 베낄 수 있다. 오늘 생긴 상처까지는 못 베낀다.<br>손을 놓고 웃었다. 실밥이 잘 아물었다고. 그 사람도 웃었다.<br><br>나머지 넷에게 손등 이야기를 몰래 전했다. 상처를 고치던 기억이 사람을 가려내는 표가 됐다. 꿰맨 자리 하나하나가 이름표처럼 손에 남았다.`,
      ng:`잡자고 했는데 그 사람이 먼저 이쪽 손을 잡았다.<br><br>세게. 아까 꿰맨 자리 그대로다. 실밥도 있다. 맞는 사람이다. 의심한 게 미안해졌다.<br>미안해하는 사이 그 사람 엄지가 실밥을 하나 뜯었다. 천천히. 웃으면서. 상처는 베낄 수 있다. 시간이 있으면.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 마력을 얇게 흘려 상처 자리를 더듬는다.', k:'sense', dc:21, cost:{ mana:22 },
      ok:`어깨를 두드리는 척 손을 얹고 마력을 아주 얇게 흘렸다. 내 마력이 닿은 자리는 내 마력을 안다.<br><br>네 사람은 마력이 스미는 자리가 있다. 오늘 이쪽이 닫은 자리. 한 사람은 아무 데도 스미지 않는다. 처음 보는 몸이다.<br>그 사람이 어깨에 얹힌 손을 본다. 웃는다. 눈은 안 웃는다.<br><br>다음 칸 문을 열 때 그 사람을 맨 뒤에 세웠다. 문을 닫을 때 그 사람은 문 너머에 있었다.`,
      ng:`마력을 흘리는 순간 그 사람이 돌아섰다.<br><br>어깨에 얹힌 손을 잡아 비튼다. 마력이 거꾸로 꺾인다. 팔꿈치에서 무언가 뚝 소리가 났다.<br>다른 일행이 떼어 냈다. 그 사람은 복도 끝으로 걸어갔다. 걸으면서 얼굴을 손바닥으로 한 번 쓸었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 넷에게 차례로 아픈 데를 묻는다.', k:'bond', dc:19,
      ok:`쉬는 척하며 하나씩 물었다. 아까 다친 데 어떠냐고.<br><br>넷은 바로 답한다. 무릎, 손바닥, 어깨, 발목. 맞다.<br>그 사람은 잠깐 늦게 답한다. 손등. 맞는 답이다. 그런데 손등을 짚는 손이 오른손이다. 꿰맨 손으로 꿰맨 손을 짚을 수는 없다.<br><br>그 뒤로 그 사람과 이쪽 사이에 늘 누가 하나 끼어 걸었다.`,
      ng:`묻는데 그 사람이 먼저 묻는다. 이쪽은 어디 다쳤냐고.<br><br>대답을 못 했다. 다친 데가 없다. 그 사람이 웃는다. 고치는 사람은 자기 상처를 모른다고.<br>그 말이 맞았다. 옆구리가 언제부터인지 젖어 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'연결 통로 — 문틈에 낀 손',
  x:`객차 사이 연결 통로다. 바닥 철판이 덜컹거린다. 바람이 들이친다.<br><br>
    미닫이문이 갑자기 닫혔다. 동료 손이 문틈에 끼었다. 문이 계속 닫히려 한다.<br>
    눌린 손은 빼는 것보다 빼고 나서가 더 위험하다. 눌린 피가 한꺼번에 돌면 손이 붓다 터진다.<br><br>
    둘이 문을 벌리고 있다. 오래는 못 버틴다.`,
  o:[
    { l:'① 문이 벌어진 순간 손을 감싸 쥐고 뺀다.', k:'heal', dc:20,
      ok:`문이 한 뼘 벌어지자 동료 손을 두 손으로 감싸 뺐다. 손이 하얗다.<br><br>바로 쥐었다. 세게. 피가 한꺼번에 돌지 않게. 조금씩 놓았다. 숨 열 번에 한 번.<br>손이 붉어지고, 붓고, 거기서 멈췄다. 손가락이 움직인다.<br><br>뒤에서 문이 쾅 닫혔다. 빈 문틈을 물었다.`,
      ng:`뺐는데 손이 순식간에 부풀었다.<br><br>쥐어 줄 틈이 없었다. 손가락이 터질 듯이 팽팽하다. 동료가 비명을 지른다.<br>열차 바람이 그 소리를 뒤 칸으로 날렸다. 뒤 칸 불이 켜졌다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 빼낸 뒤 어긋난 손가락 마디를 맞춘다.', k:'fix', dc:21,
      ok:`빼고 보니 가운뎃손가락 둘째 마디가 옆으로 꺾였다.<br><br>당기면서 돌렸다. 딸깍. 동료가 이를 문다. 옆 손가락에 붙여 묶었다.<br>철판이 덜컹일 때마다 맞춘 마디가 흔들린다. 손을 동료 가슴에 붙여 묶었다.<br><br>문이 다시 열렸다. 안에서 아무도 나오지 않았다. 문이 혼자 열고 닫힌다.`,
      ng:`맞추는데 열차가 크게 흔들렸다.<br><br>손이 미끄러져 마디가 반대로 꺾였다. 동료가 쓰러진다.<br>다시 맞추는 데 셋이 붙어야 했다. 그사이 문이 이쪽 발목을 물었다. 발목이 시퍼레졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B3', t:'탄수차 — 증기에 덴 팔',
  x:`기관실 앞 탄수차다. 석탄이 젖었다. 보일러 틈에서 증기가 샌다.<br><br>
    동료가 증기를 맞았다. 팔뚝이 순식간에 빨갛게 익는다. 소매가 살에 붙었다.<br>
    덴 살은 처음 몇 분에 다 정해진다. 식히는 시간만큼 살이 산다.<br><br>
    탄수차에 물탱크가 있다. 기관실 문까지는 얼마 안 남았다. 종착 시각까지도.`,
  o:[
    { l:'① 물탱크 물로 오래 식힌다.', k:'heal', dc:20,
      ok:`물탱크 꼭지를 열고 팔을 그 밑에 댔다. 소매는 떼지 않았다. 붙은 것을 떼면 살이 같이 온다.<br><br>오래 흘렸다. 동료가 이제 됐다고 한다. 더 흘렸다. 아프지 않다는 건 아직 덜 식었다는 뜻이다.<br>팔이 붉은 채로 멈췄다. 하얗게 되지 않았다.<br><br>시계를 봤다. 그 몇 분이 아깝지 않았다.`,
      ng:`꼭지를 여는데 물이 뜨겁다. 보일러 옆 탱크다.<br><br>찬물인 줄 알고 댄 팔이 한 번 더 익었다. 동료가 펄쩍 뛴다.<br>급히 석탄 위 빗물을 끼얹었다. 검은 물이 상처에 들어갔다. 씻어 낼 물이 없다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 물집은 두고 젖은 천으로 느슨하게 싼다.', k:'fix', dc:19,
      ok:`물집이 부풀어 오른다. 동료가 터뜨리려 한다. 손을 막았다.<br><br>물집은 살이 스스로 만든 붕대다. 터뜨리면 그 붕대를 벗기는 것이다.<br>젖은 천을 느슨하게 감고 팔을 가슴 높이로 들게 했다.<br><br>기관실 문까지 걸었다. 동료가 팔을 들고 걷는다. 항복하는 사람 같다. 둘 다 웃지 않았다.`,
      ng:`싸는데 석탄 가루가 천에 묻었다.<br><br>검은 천이 물집을 문지른다. 하나가 터졌다. 또 하나.<br>동료가 이를 악문다. 다시 쌀 깨끗한 천이 없다. 그대로 걸었다. 걸음마다 팔이 탄다고 한다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'③ 마력으로 살 속에 남은 열을 뽑는다.', k:'heal', dc:21, cost:{ mana:26 },
      ok:`팔 위로 손바닥을 띄우고 마력을 내렸다. 살에 닿지 않게. 열만 건졌다.<br><br>덴 살은 겉이 식어도 속에서 계속 익는다. 그 속 열을 손바닥으로 끌어 올렸다. 손바닥이 뜨겁다.<br>붉은 기가 가라앉는다. 물집이 덜 부푼다.<br><br>손바닥을 탄수차 철판에 대어 식혔다. 쇠가 치익 하고 울었다.`,
      ng:`마력을 내리는 순간 보일러 증기가 한 번 더 뿜었다.<br><br>이쪽 손등에. 마력을 쓰던 손이 그대로 익었다.<br>두 사람이 나란히 팔을 들고 기관실 앞에 섰다. 문은 아직 잠겨 있다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] }

]);

// ── 약사 (pharma) · 자원 없음 ──
kJob('pharma', 'B', [

{ at:'B', t:'도망 중 — 풀리는 다리',
  x:`한 시간째 뛰고 숨고 다시 뛴다. 쫓는 쪽은 지치지 않는다.<br><br>
    동료 하나가 무릎이 풀린다. 넘어지고 일어나는 데 점점 오래 걸린다. 눈꺼풀이 내려온다.<br>
    약사는 지친 몸에 무엇을 넣으면 한 시간을 더 버티는지 안다. 그리고 그 한 시간 뒤에 무엇이 오는지도 안다.<br><br>
    주머니에 쓴 뿌리 조금과 각성 알약 한 알이 있다. 한 알이 마지막이다.`,
  o:[
    { l:'① 쓴 뿌리를 씹게 한다.', k:'heal', dc:20,
      ok:`쓴 뿌리를 손톱만큼 잘라 어금니에 물렸다. 씹으라고. 삼키지 말고 즙만.<br><br>동료 얼굴이 찌그러진다. 쓰다. 쓴 것은 잠을 쫓는다. 몸이 쓴맛을 독으로 알고 깨어나기 때문이다.<br>눈이 다시 떠진다. 다리가 다시 선다.<br><br>알약은 그대로 주머니에 남았다. 더 나쁜 때가 온다.`,
      ng:`씹게 했는데 동료가 뱉어 버린다. 너무 쓰다고.<br><br>다시 물릴 틈이 없었다. 발소리가 가까워졌다. 동료를 끌고 뛰었다.<br>모퉁이에서 둘이 같이 넘어졌다. 이쪽 손바닥이 아스팔트에 갈렸다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 마지막 알약을 쪼개 반만 먹인다.', k:'fix', dc:21, wake:1,
      ok:`알약을 손톱으로 반 갈랐다. 반은 동료 혀 밑에, 반은 종이에 싸서 주머니에.<br><br>한 알은 한 시간을 주고 뒤에 두 시간을 빼앗는다. 반 알은 반 시간을 주고 한 시간을 빼앗는다. 끝까지 남은 시간이 한 시간 반이면 반 알이 맞다.<br>동료가 다시 뛴다. 반 시간 뒤에 나머지 반을 줬다.<br><br>약을 양으로 셈하던 손이 시간으로 셈하기 시작했다. 한 알을 언제 어떻게 쪼개느냐가 약보다 큰 약이다.`,
      ng:`쪼개는데 알약이 부서졌다. 가루가 빗물에 녹는다.<br><br>손가락에 묻은 걸 핥게 했다. 양을 모른다. 동료가 이상하게 웃는다. 너무 들어갔다.<br>심장이 빠르다고 가슴을 친다. 그 손을 잡고 숨은 자리까지 끌었다. 둘 다 쓰러지듯 앉았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B', t:'숨은 자리 — 피 냄새',
  x:`다 같이 숨었다. 일행 하나가 손을 베였다. 피는 멎었는데 냄새가 남았다.<br><br>
    밖에서 무언가 킁킁거린다. 문틈을 따라 천천히 움직인다.<br>
    냄새는 지울 수도 있고 덮을 수도 있다. 지우는 건 오래 걸리고 덮는 건 금방이다.<br><br>
    주머니에 말린 쑥, 숯 조각, 피 묻은 천이 있다.`,
  o:[
    { l:'① 쑥과 숯가루를 비벼 손과 옷에 바른다.', k:'hide', dc:20,
      ok:`숯을 손바닥에서 빻고 쑥을 비벼 섞었다. 베인 손과 피 묻은 소매에 문질렀다.<br><br>숯은 냄새를 먹고 쑥은 냄새를 덮는다. 둘이 같이 있으면 피는 그 밑으로 숨는다.<br>킁킁거리던 소리가 문 앞에서 멈췄다. 한참. 그리고 지나갔다.<br><br>남은 가루를 일행 다섯 손에 다 발라 두었다.`,
      ng:`비비는데 숯이 너무 굵다. 소리가 난다. 사각사각.<br><br>킁킁거리던 소리가 멈췄다. 이번엔 냄새가 아니라 소리를 듣는다.<br>문틈으로 무언가 들어왔다. 길고 젖은 것. 손등을 훑고 나갔다. 손등이 화끈하게 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-14 } },
    { l:'② 피 묻은 천을 반대쪽 통로로 던진다.', k:'luck', dc:21,
      ok:`천을 뭉쳐 문 위 환기창으로 던졌다. 반대쪽 통로로 떨어지는 소리가 났다.<br><br>킁킁 소리가 그쪽으로 꺾인다. 빨라진다. 피 냄새는 진한 쪽으로 간다.<br>멀어진 틈에 반대쪽으로 빠졌다.<br><br>천은 두고 왔다. 아깝지 않았다. 피 묻은 천은 이제 미끼 말고는 쓸 데가 없다.`,
      ng:`던진 천이 환기창 창살에 걸렸다.<br><br>바로 문 위에. 피 냄새가 이 방 문 위에서 흔들린다.<br>킁킁 소리가 문 바로 앞에 섰다. 문이 긁힌다. 위에서 아래로. 아주 오래. 그 소리가 끝날 때까지 다들 귀를 막았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'건네받은 알약',
  x:`같이 갇혀 있던 사람이 손바닥을 편다. 알약 두 알이다.<br><br>
    진통제라고 한다. 다친 동료에게 주라고. 자기도 먹었다고.<br>
    약사는 남이 주는 약을 받으면 먼저 그 사람 눈을 본다. 그다음 약을 본다.<br><br>
    그 사람 눈은 맑다. 진통제를 먹은 눈은 조금 풀려야 한다.`,
  o:[
    { l:'① 혀 밑에 넣어 맛으로 가린다.', k:'sense', dc:21,
      doom:{ title:'혀 밑의 알약', what:'혀가 굳고 몸이 늘어지기 시작했습니다', dc:17, sec:55,
        text:`한 알을 혀 밑에 넣었다. 맛으로 아는 약이 있다. 쓴맛의 순서로.<br><br>처음은 달다. 겉에 설탕을 입혔다. 그다음 쓴맛이 아니라 아무 맛도 없다. 혀가 없어진다.<br>뱉으려는데 입술이 안 움직인다. 고개가 옆으로 떨어진다.<br><br>알약을 준 사람이 이쪽을 내려다본다. 처음으로 눈이 풀린다. 웃느라고. 누가 이쪽 입에서 알약을 긁어내야 한다.`,
        dieText:`약은 혀로도 안다. 약을 오래 다룬 사람은 그렇게 배운다.<br><br>그 사람도 그걸 알았다. 그래서 겉에 단맛을 입혔다.<br>그 사람 손바닥에는 다음 날에도 알약 두 알이 있었다. 다음 사람을 위해.` },
      ok:`혀 밑에 넣으려다 입술에서 멈췄다. 알약 겉이 반짝인다. 설탕을 입혔다.<br><br>진통제에 설탕을 입힐 까닭이 없다. 쓴맛을 숨길 까닭이 있는 약에만 입힌다.<br>고맙다고 받아 주머니에 넣었다. 동료에게는 주지 않았다.<br><br>그 사람이 주머니를 오래 봤다. 그 뒤로 그 사람은 늘 이쪽 등 뒤에 있었다. 등 뒤를 내주지 않았다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 손톱으로 쪼개 속을 본다.', k:'gaze', dc:20,
      ok:`받아서 그 자리에서 쪼갰다. 그 사람 얼굴이 굳는다.<br><br>속이 두 겹이다. 겉은 흰 가루, 안은 잿빛 알갱이. 하나를 다른 하나로 감쌌다.<br>진통제는 그렇게 만들지 않는다. 늦게 듣게 하려는 약이 그렇게 생긴다. 먹고 나서 한참 뒤에, 아무도 모를 때.<br><br>쪼갠 알약을 그 사람 손에 도로 얹었다. 그 사람은 아무 말도 못 했다.`,
      ng:`쪼개려는데 그 사람이 손을 덮는다. 의심하는 거냐고.<br><br>목소리가 크다. 다들 이쪽을 본다. 의심한 사람이 나쁜 사람이 됐다.<br>그 사람이 다친 동료에게 직접 알약을 쥐여 줬다. 동료가 삼켰다. 한 시간 뒤 동료가 일어나지 못했다. 깨우느라 밤을 다 썼다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'비 — 젖은 약 주머니',
  x:`비를 너무 맞았다. 약 주머니가 속까지 젖었다.<br><br>
    봉지마다 가루가 엉겨 덩어리졌다. 이름표 글씨가 번졌다. 무엇이 무엇인지 겉으로는 모른다.<br>
    젖은 약이 상하는 길은 정해져 있다. 가루는 곰팡이로 가고 뿌리는 썩음으로 간다. 한 시간 안에 손쓰면 반은 산다.<br><br>
    시간은 한 시간이 안 된다.`,
  o:[
    { l:'① 품에 넣어 체온으로 말린다.', k:'steady', dc:19,
      ok:`봉지를 펼쳐 겉옷 안쪽에 붙였다. 배와 가슴. 체온이 제일 높은 데.<br><br>걷는 내내 젖은 약을 품고 걸었다. 차갑다. 몸이 데워 주는 만큼 약이 마른다.<br>다음 쉬는 자리에서 꺼냈다. 반은 말랐다. 냄새를 맡아 가르니 쓸 것이 셋이다.<br><br>셋이면 된다. 셋을 쓸 줄 아는 사람에게는.`,
      ng:`품에 넣었는데 비가 옷을 뚫는다.<br><br>약이 더 젖었다. 가루가 피부에 들러붙는다. 무엇인지 모르는 가루가.<br>살갗이 따끔하다. 벌겋게 일어난다. 뭐가 묻었는지도 모르는 채 긁었다.`,
      win:{ exp:15, dream:2, item:'약초 뭉치' }, lose:{ hp:-20, mind:-12 } },
    { l:'② 엉긴 가루끼리 맞춰 섞어 새로 빚는다.', k:'heal', dc:21, wake:1,
      ok:`엉긴 덩어리를 하나씩 맡았다. 이름표는 못 믿는다. 코는 믿는다.<br><br>상처 약 둘, 열 내리는 약 하나, 잠 오는 약 하나. 상처 약 둘은 섞어도 서로 다치지 않는다. 손바닥에서 다시 빚었다. 열 내리는 약은 상처 약을 거든다. 그것도 조금 넣었다.<br>잠 오는 약은 따로 쌌다. 섞으면 다 잠 오는 약이 된다.<br><br>망가진 약을 버리지 않고 새 약을 지었다. 무엇과 무엇이 서로를 거드는지 코가 먼저 알았다. 손이 그걸 받아 적었다.`,
      ng:`맡다가 두 덩이를 헷갈렸다. 냄새가 비에 섞였다.<br><br>섞어 빚은 것을 동료 상처에 발랐다. 상처가 하얗게 질린다. 잠 오는 쪽이 들어갔다.<br>상처가 마비되고 동료가 꾸벅거린다. 깨워 가며 걸었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 젖은 약초를 빗물에 우려 그대로 마신다.', k:'heal', dc:20,
      ok:`버리느니 우렸다. 젖은 약초를 수통에 넣고 빗물을 채워 흔들었다.<br><br>찬물에도 약은 우러난다. 느리고 약하게. 대신 아무것도 날아가지 않는다.<br>한 모금씩 돌렸다. 쓰다. 다들 몸이 조금 데워진다.`,
      ng:`우리는 사이 수통 안에서 약이 엉켜 시큼해졌다.<br><br>이미 상하기 시작한 것이다. 마신 둘이 배를 움켜쥔다.<br>쉬는 자리마다 둘이 구석에 쭈그렸다. 걸음이 그만큼 늦었다.`,
      win:{ exp:15, hp:8 }, lose:{ hp:-22, mind:-10 } }
  ] },

{ at:'B', t:'시계 — 약이 도는 시간',
  x:`동료 하나가 잡혀 있다 돌아왔다. 무언가를 맞고 왔다. 지금은 반쯤 잠들어 있다.<br><br>
    나갈 시각은 정해져 있다. 그 전에 동료가 걸어야 한다.<br>
    약은 몸에서 오르고 내리는 모양이 있다. 언제 제일 깊고 언제 풀리는지.<br><br>
    동료 숨, 동공, 손끝 떨림. 그리고 맞은 자리 멍 색.`,
  o:[
    { l:'① 약이 풀리는 시각을 셈해 거기에 맞춘다.', k:'fix', dc:20, wake:1,
      ok:`멍 색이 노랗게 번지기 시작했다. 맞은 지 한 시간 반. 동공은 아직 작다. 깊은 데서 막 올라오는 중이다.<br><br>이런 약은 두 시간째에 한 번 풀렸다가 다시 깊어진다. 풀리는 그 짧은 틈에 걸어야 한다.<br>시계를 보며 기다렸다. 두 시간째 동료 눈이 이쪽을 알아본다. 그때 일으켜 세웠다. 걸었다.<br><br>약을 아는 것과 약이 지나가는 길을 아는 것은 다르다. 몸속 시계를 읽는 눈이 생겼다.`,
      ng:`셈이 틀렸다. 풀리는 틈이 생각보다 빨리 왔다.<br><br>기다리는 사이 이미 지나갔다. 동료가 다시 깊이 잠든다.<br>업었다. 나갈 시각까지 업고 갔다. 허리가 끊어질 듯하다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 쓴 차를 진하게 우려 억지로 깨운다.', k:'heal', dc:21,
      ok:`쓴 잎을 한 줌 넣어 진하게 우렸다. 동료 입을 벌려 조금씩 흘려 넣었다.<br><br>쓴맛에 동료가 얼굴을 찡그린다. 찡그리는 근육이 깨어난다. 다시 흘려 넣었다.<br>눈을 뜬다. 쓰다고 욕을 한다. 욕이 나오면 걸을 수 있다.`,
      ng:`흘려 넣는데 동료가 사레가 들렸다.<br><br>잠든 목은 삼키는 걸 잊는다. 차가 기도로 들어갔다. 기침이 터진다.<br>등을 두드려 뱉게 했다. 그 소리를 듣고 무언가 이쪽으로 걸어오기 시작했다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'벽의 구급함 — 바뀐 이름표',
  x:`벽에 구급함이 걸려 있다. 빨간 십자가. 잠겨 있지 않다.<br><br>
    병이 여섯 줄로 섰다. 이름표가 반듯하다. 소독약, 진통제, 해열제.<br>
    병 속 색과 이름표가 맞는지부터 본다. 오래된 버릇이다.<br><br>
    소독약 병에 든 것이 소독약 색이 아니다. 너무 맑다.`,
  o:[
    { l:'① 하나씩 냄새로 가려낸다.', k:'sense', dc:20,
      ok:`마개를 손끝만큼 열고 코를 멀리 대 손으로 냄새를 끌어왔다. 하나씩.<br><br>소독약 병에는 물. 진통제 병에는 잠 오는 약. 해열제 병에는 진짜 해열제. 이름표가 셋씩 엇갈리게 바뀌었다.<br>누가 다친 사람이 여기 손을 댈 줄 알고 바꿔 두었다.<br><br>진짜 해열제와 맨 아래 칸의 말린 약초를 챙겼다. 나머지 이름표는 맞게 고쳐 붙였다. 다음 손을 위해.`,
      ng:`마개를 열다 김을 정면으로 맡았다.<br><br>눈이 맵고 목이 탄다. 소독약 병 옆 병이 진짜 소독약이었다. 아주 진한.<br>한참 기침했다. 눈물이 그치지 않았다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-22, mind:-12 } },
    { l:'② 구급함째 떼어 챙긴다.', k:'luck', dc:21,
      ok:`구급함을 벽에서 들어냈다. 생각보다 가볍다.<br><br>뒤판 틈에 종이가 끼어 있다. 먼저 이 구급함을 연 사람이 남겼다. 『병 바뀜. 맨 아래 것만 진짜.』<br>맨 아래 칸에서 꿀 단지가 나왔다. 상처에 바르는 꿀이다.<br><br>먼저 지나간 누군가도 약을 아는 사람이었다.`,
      ng:`들어내자 뒤에서 줄이 팽팽해진다. 구급함 뒤에 줄이 묶여 있었다.<br><br>복도 저편에서 종이 울렸다. 딸랑.<br>구급함을 내팽개치고 뛰었다. 종소리 쪽에서 발소리가 났다. 뛰다 계단을 헛디뎌 발목을 접질렸다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'잠긴 문 — 녹슨 경첩',
  x:`문은 잠기지 않았다. 녹이 잠갔다. 경첩이 녹슬어 꿈쩍 않는다.<br><br>
    힘으로 밀면 열린다. 대신 쇠가 비명을 지른다. 이 근처 모두가 들을 것이다.<br>
    약은 사람에게만 듣는 게 아니다. 쇠에도 듣는 약이 있다.<br><br>
    주머니에 식초 한 병과 소금이 있다.`,
  o:[
    { l:'① 식초에 소금을 녹여 경첩에 먹인다.', k:'fix', dc:20,
      ok:`식초에 소금을 녹였다. 천에 적셔 경첩마다 감았다. 기다렸다.<br><br>쇠가 거품을 문다. 작게 지글거린다. 녹이 풀리는 소리다.<br>한참 뒤 문을 손가락으로 밀었다. 소리 없이 열린다.<br><br>상처 씻는 식초로 문을 씻었다. 쓸 데가 다를 뿐 같은 약이다.`,
      ng:`기다리는 동안 식초 냄새가 퍼진다. 시큼하게.<br><br>복도 끝에서 무언가 코를 킁킁거린다. 다가온다.<br>덜 풀린 문을 억지로 밀었다. 쇠가 운다. 길게. 문은 열렸고 모두가 들었다. 뛰다 문틀에 어깨를 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 경첩 핀을 쳐서 뽑아낸다.', k:'break', dc:21,
      ok:`경첩 핀 밑에 못을 대고 신발 굽으로 두드렸다. 소리를 천으로 감쌌다.<br><br>핀이 조금씩 올라온다. 셋 다 뽑았다. 문을 경첩 쪽으로 들어서 뗐다.<br>잠긴 쪽은 잠긴 채로 두고 반대쪽으로 나갔다.`,
      ng:`두드리는데 핀이 안 올라온다. 녹이 핀까지 먹었다.<br><br>두드리는 소리만 쌓였다. 천으로 감싸도 쇠는 쇠다.<br>문 너머에서 누가 똑같이 두드린다. 이쪽 박자로. 손을 멈추자 저쪽도 멈췄다. 손등이 못에 찍혀 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 쉼 — 한 봉지',
  x:`마지막 문 앞에서 약을 다 꺼냈다.<br><br>
    진통 가루 조금, 잠 쫓는 뿌리 조금, 상처 약 조금. 다 조금씩이다.<br>
    조금씩인 약은 쓰는 법이 따로 있다. 따로 주면 다 모자라다.<br><br>
    문 너머에서 시계 소리가 난다. 문을 지나면 뛰어야 한다. 아픈 몸으로도.`,
  o:[
    { l:'① 진통과 잠 쫓는 것을 한 봉지에 맞춘다.', k:'heal', dc:21, wake:1,
      ok:`진통 가루는 잠을 부른다. 잠 쫓는 뿌리는 아픔을 키운다. 따로 쓰면 서로를 깎는다. 같이 쓰면 서로를 막는다.<br><br>비율을 맞췄다. 진통 둘에 뿌리 하나. 손바닥 위에서 섞고 다섯으로 나눴다.<br>다들 먹었다. 아프지 않고 졸리지 않다. 문을 지나 뛰었다.<br><br>모자란 둘을 합쳐 넉넉한 하나를 만들었다. 서로 다투는 약을 한 봉지 안에서 화해시키는 법을 손이 알았다.`,
      ng:`비율이 틀렸다. 뿌리가 많았다.<br><br>먹은 다섯이 다 눈이 말똥하다. 그리고 아프다. 아픈 데가 다 두 배로.<br>문을 지나 뛰는데 다섯 다 이를 악물었다. 이쪽은 발목이 다시 접혔다.`,
      win:{ exp:24, dream:3, hp:10 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 독이 될 만한 것을 다 버린다.', k:'steady', dc:19,
      ok:`주워 모은 약 중에 모르는 것을 다 골라 버렸다. 아까워도.<br><br>모르는 약은 마지막에 손이 간다. 급할 때. 급할 때 모르는 약을 먹으면 끝이다.<br>남은 건 아는 약뿐이다. 적다. 적어도 정직하다.`,
      ng:`버리는 걸 일행이 말린다. 혹시 모른다고.<br><br>실랑이하다 하나가 모르는 봉지를 몰래 챙겼다. 문 너머에서 그 사람이 그걸 먹었다.<br>한참 토했다. 그사이 다들 멈춰 서야 했다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 가장 다친 사람에게 다 준다.', k:'bond', dc:20,
      ok:`다섯 중 제일 많이 다친 사람을 봤다. 그 사람이 쓰러지면 다섯이 다 멈춘다.<br><br>약을 다 그 사람 몫으로 쌌다. 나머지 넷은 아무것도 없다. 넷이 고개를 끄덕였다.<br>그 사람이 끝까지 뛰었다. 다섯이 다 같이 뛰었다.`,
      ng:`다 주려는데 다른 하나가 자기도 아프다고 한다.<br><br>정말 아프다. 둘로 나눴다. 둘 다 모자란다.<br>문 너머에서 둘이 같이 주저앉았다. 둘을 일으키느라 이쪽 손목이 꺾였다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 건어물 상자 속 봉지',
  x:`3번 창고에 건어물 상자가 산처럼 쌓였다. 마른 오징어, 미역, 멸치.<br><br>
    상자 하나가 터져서 안이 보인다. 미역 다발 사이에 비닐 봉지가 박혀 있다.<br>
    가루는 보면 대충 무엇인지 안다. 색, 결, 뭉치는 모양.<br><br>
    흰 가루다. 결이 너무 곱다. 미역 상자에 들어갈 물건이 아니다.`,
  o:[
    { l:'① 봉지 냄새로 무엇인지 가린다.', k:'sense', dc:21,
      ok:`봉지를 열지 않고 매듭 틈에 코를 댔다.<br><br>냄새가 거의 없다. 아주 끝에 시든 꽃 냄새. 아픔을 없애는 쪽 약이다. 많이 쓰면 숨까지 없애는.<br>이 창고에서 실어 나르는 건 미역이 아니다. 그리고 이 약은 오늘 밤 다른 데도 쓰였을 것이다. 칠판의 숫자를 맞추는 데.<br><br>봉지를 상자 깊숙이 도로 넣었다. 손에 묻은 가루를 빗물에 씻어 냈다.`,
      ng:`코를 대는데 봉지가 터졌다. 매듭이 헐거웠다.<br><br>가루가 얼굴에 날렸다. 숨을 참았다. 늦었다. 혀끝이 저리다.<br>한참 상자에 기대 앉아 있었다. 손가락이 남의 것 같았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 아무것도 안 본 척 상자를 도로 덮는다.', k:'hide', dc:20,
      ok:`터진 상자 뚜껑을 덮고 미역 다발로 틈을 막았다.<br><br>본 것은 모르는 것보다 위험하다. 창고 사람들은 누가 무엇을 봤는지 센다.<br>상자 겉에 손자국이 남지 않게 소매로 닦았다.<br><br>닦고 나서 보니 상자 옆면에 분필로 적혀 있다. 『확인 05:00.』 그 시각까지 이 상자를 아무도 안 열었어야 한다.`,
      ng:`덮는데 미역 다발이 무너졌다.<br><br>봉지 셋이 바닥에 굴렀다. 줍는 사이 창고 끝에서 손전등이 켜졌다.<br>봉지를 발로 상자 밑에 밀어 넣고 엎드렸다. 빛이 이쪽 손등에서 멈췄다. 한참. 꺼졌다. 손등이 떨리는 걸 멈추지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B1', t:'경매장 이층 — 밀수 약병',
  x:`경매장 이층 사무실 금고 옆에 나무 궤짝이 있다. 톱밥 속에 갈색 유리병이 줄지어 꽂혔다.<br><br>
    이름표가 외국 글자다. 읽을 수 없다. 병 바닥에 침전물이 가라앉았다.<br>
    약사는 이름표를 못 읽어도 병은 읽는다. 갈색 병은 빛에 상하는 약이다. 침전물은 오래된 약이다.<br><br>
    마개 둘레에 밀랍을 두 번 둘렀다. 한 번은 공장에서, 한 번은 누가 나중에.`,
  o:[
    { l:'① 마개를 따서 냄새를 맡는다.', k:'sense', dc:21,
      doom:{ title:'두 번 봉한 병', what:'병에서 오른 김에 숨이 막힙니다', dc:17, sec:55,
        text:`밀랍을 칼끝으로 둘러 땄다. 마개가 퐁 하고 튄다. 안에서 밀어 올린 것이다.<br><br>김이 오른다. 투명한데 눈이 따갑다. 냄새가 없다. 냄새 없는 김이 제일 무섭다.<br>숨을 참았다. 늦었다. 가슴이 안에서부터 조인다. 무릎이 접힌다.<br><br>사무실 창으로 빗소리가 들린다. 창을 열어야 한다. 누가 이쪽을 바깥 공기로 끌어내야 한다.`,
        dieText:`두 번 봉한 데는 까닭이 있다.<br><br>나중에 봉한 사람은 이 병을 열 사람을 알았다. 병을 읽을 줄 아는 사람. 그래서 냄새를 빼고 넣었다.<br>궤짝에는 병이 하나 비었다. 톱밥이 그 자리를 덮었다.` },
      ok:`칼끝을 밀랍에 댔다가 거뒀다. 두 번째 밀랍이 너무 새것이다.<br><br>공장에서 봉한 약에 누가 무엇을 더 넣고 다시 봉했다. 다시 봉한 병은 다시 열 사람을 위한 병이다.<br>병을 톱밥에 도로 꽂았다. 이름표가 앞을 보게. 있던 그대로.<br><br>사무실을 나오며 보니 문 안쪽에 방독면이 걸려 있다. 하나뿐이다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 병을 기울여 침전물이 흐르는 모양을 본다.', k:'gaze', dc:20,
      ok:`병을 들어 창빛에 기울였다. 침전물이 천천히 흐른다. 꿀처럼.<br><br>꿀처럼 흐르는 침전은 오래 녹아 있던 것이다. 약이 반쯤 죽었다. 이 궤짝은 약을 팔려는 게 아니다. 병을 팔려는 것이다. 다른 걸 담아서.<br>병 하나를 돌려 보니 바닥에 바늘구멍이 있다. 다시 메웠다. 무엇을 넣었다.<br><br>궤짝 바닥 톱밥 속에서 진짜 약재 꾸러미 하나를 찾았다. 그것만 챙겼다.`,
      ng:`기울이는데 병이 손에서 미끄러졌다.<br><br>궤짝 모서리에 부딪혀 금이 갔다. 냄새 없는 김이 가늘게 샌다.<br>숨을 참고 창을 열었다. 빗물이 들이친다. 창가에서 한참 숨을 몰아쉬었다. 가슴이 오래 쓰렸다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 금고 위 장부를 펼친다.', k:'luck', dc:21,
      ok:`장부는 숫자뿐이다. 날짜, 병 수, 그리고 줄 하나에 이름 대신 동그라미.<br><br>동그라미 옆 숫자가 오늘 밤 날짜에 다섯이다. 다섯 병. 다섯 동그라미.<br>병 하나에 사람 하나다.<br><br>장부를 덮고 궤짝에서 병 다섯을 빼 빗물 홈통에 쏟았다. 숫자가 안 맞으면 누가 다시 센다. 세는 동안 시간이 간다.`,
      ng:`펼치는데 장부 사이에서 사진이 떨어졌다.<br><br>이쪽 일행 사진이다. 오늘 밤 창고 앞에서 찍혔다. 셔터가 내려오기 전.<br>사진을 줍는 손이 떨렸다. 이층 계단에서 발소리가 올라온다. 사진을 들고 창으로 뛰었다. 창틀에 무릎이 찢어졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'B1', t:'냉동 창고 — 쇠에 붙은 손바닥',
  x:`냉동 창고 쇠문 손잡이를 맨손으로 잡았다. 동료가.<br><br>
    손바닥이 쇠에 붙었다. 떨어지지 않는다. 억지로 떼면 살갗이 남는다.<br>
    언 쇠에 붙은 살을 떼는 약이 있다. 대단한 약은 아니다. 어느 부엌에나 있다.<br><br>
    창고 바깥에서 고무장화 소리가 다가온다. 한 걸음씩.`,
  o:[
    { l:'① 소금을 뿌려 얼음을 녹여 뗀다.', k:'fix', dc:20, wake:1,
      ok:`주머니에서 소금을 꺼내 손바닥과 쇠 사이 틈에 뿌렸다. 입김을 불었다.<br><br>소금은 얼음을 녹인다. 녹는 점을 낮춰서. 손바닥 가장자리부터 살이 쇠에서 풀린다. 한 줄씩.<br>마지막에 손가락 끝이 떨어졌다. 살갗은 다 붙어 있다.<br><br>고무장화 소리가 문 앞에 닿기 전에 물러났다. 사람에게 쓰는 약이 쇠에도 듣고, 쇠에 쓰는 약이 사람을 살린다. 약장의 경계가 손안에서 지워졌다.`,
      ng:`소금을 뿌리는데 손이 떨려 반이 바닥에 쏟아졌다.<br><br>모자란 소금으로 반만 풀렸다. 고무장화 소리가 문 앞이다.<br>남은 반을 억지로 뗐다. 동료 손바닥 살갗이 쇠에 남았다. 하얗게. 그걸 보고 고무장화가 멈췄다. 한참 그 자리를 보았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 } },
    { l:'② 빨리 떼고 꿀을 발라 싼다.', k:'heal', dc:21,
      ok:`시간이 없다. 동료 손목을 잡고 한 번에 뗐다. 동료가 소리를 삼킨다.<br><br>벗겨진 손바닥에 꿀을 얇게 바르고 깨끗한 천을 감았다. 꿀은 벗겨진 살을 덮는 가장 좋은 껍질이다.<br>고무장화 소리가 문 앞에 닿을 때 이미 다른 통로였다.`,
      ng:`떼는데 동료가 비명을 지른다. 참지 못했다.<br><br>고무장화 소리가 빨라진다. 처음으로.<br>꿀을 바를 틈도 없이 뛰었다. 벗겨진 손에 빗물과 소금기가 스민다. 동료가 이를 갈며 뛰었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'방파제 — 기름 먹은 상처',
  x:`방파제 아래를 기어 지났다. 바닷물에 기름이 떠 있었다.<br><br>
    동료 정강이에 벌어진 상처가 있다. 아까 쇠붙이에 긁힌 것이다. 거기 기름 섞인 바닷물이 잔뜩 들어갔다.<br>
    기름 든 상처는 겉과 속이 따로 간다. 겉은 아물고 속은 썩는다.<br><br>
    배가 뜨기까지 한 시간이 남았다.`,
  o:[
    { l:'① 맑은 물로 씻어 내고 꿀로 덮는다.', k:'heal', dc:20,
      ok:`수통 물을 아끼지 않았다. 상처를 벌려 가며 씻었다. 기름이 무지갯빛으로 흘러나온다.<br><br>더는 무지개가 안 나올 때까지. 동료가 이를 문다.<br>꿀을 덮고 묶었다. 꿀은 기름이 남긴 것을 끌어낸다. 천천히.<br><br>수통이 비었다. 목마른 건 배에 오른 다음 생각하기로 했다.`,
      ng:`씻는데 물이 모자란다. 기름이 반만 빠졌다.<br><br>꿀을 덮었는데 꿀이 기름 위에서 미끄러진다. 안 붙는다.<br>그냥 묶었다. 동료 다리가 걸음마다 무거워진다. 열이 오르기 시작했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 방파제 돌 틈 해초를 찧어 덮는다.', k:'sense', dc:21,
      ok:`돌 틈에 해초가 붙어 있다. 미끈한 갈색. 끈적한 즙이 나오는 종류다.<br><br>그 즙은 기름을 붙잡는다. 찧어서 상처에 두껍게 덮고 한참 뒤에 걷었다. 해초에 기름이 엉겨 나왔다.<br>두 번 했다. 상처가 깨끗해졌다.<br><br>바다에서 생긴 상처에는 바다의 약이 있다.`,
      ng:`해초를 뜯다가 돌이 미끄러졌다.<br><br>물에 반쯤 빠졌다. 기름 바닷물이 입에 들어갔다.<br>뱉고 또 뱉었다. 해초는 다른 종류였다. 즙이 없다. 상처에 덮었더니 따끔거리기만 했다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B2', t:'투약 카트 — 이름 붙은 약봉투',
  x:`복도에 투약 카트가 서 있다. 서랍마다 침대 번호. 칸마다 약봉투.<br><br>
    봉투에 이름이 적혔다. 일행 다섯의 침대 명패 이름도 있다. 오늘 밤 처음 생긴 이름들이다.<br>
    알약은 모양을 보면 대개 무엇인지 안다. 색, 크기, 가운데 금.<br><br>
    다섯 봉투에 같은 알약이 들었다. 다른 침대 봉투에는 없는 알약이다. 정각 투약까지 십오 분.`,
  o:[
    { l:'① 같은 모양의 순한 알약으로 바꿔 넣는다.', k:'fix', dc:21, wake:1,
      ok:`다른 서랍을 뒤졌다. 같은 크기, 같은 흰색, 가운데 금까지 같은 알약을 찾았다. 위장약이다. 먹어도 아무 일 없는.<br><br>다섯 봉투에서 하나씩 빼고 하나씩 넣었다. 수는 맞다. 모양도 맞다. 세는 사람은 수와 모양을 센다. 속은 안 센다.<br>뺀 알약 다섯은 종이에 싸 챙겼다. 나중에 쓸 데가 있다.<br><br>정각에 간호사가 봉투를 나눠 줬다. 다섯이 삼켰다. 아무도 잠들지 않았다. 약을 고르던 손이 약을 바꾸는 손이 됐다. 같은 겉 다른 속을 만드는 법을 손이 알았다.`,
      ng:`바꿔 넣는데 알약 하나가 카트 밑으로 굴렀다.<br><br>주우려 엎드린 사이 딸깍 소리가 가까워졌다. 봉투 하나는 한 알이 모자란 채로 닫혔다.<br>정각에 간호사가 그 봉투를 집었다. 무게를 손바닥에 달아 본다. 멈춘다. 봉투 주인 이름을 다시 부른다. 두 번.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 봉투를 읽어 누가 무엇을 먹는지 안다.', k:'gaze', dc:20,
      ok:`봉투를 넘기며 읽었다. 이름, 알약, 시각.<br><br>대부분 같은 약을 같은 시각에 먹는다. 한 침대만 다르다. 그 침대 봉투는 비었다. 몇 주째. 약을 안 먹는 사람이 하나 있다.<br>그 침대 번호를 외웠다. 깨어 있는 사람이 하나 있다는 뜻이다.<br><br>나중에 그 침대를 찾아갔다. 침대 위 사람이 이쪽을 보고 손가락으로 계단 쪽을 가리켰다.`,
      ng:`넘기다 봉투 하나가 찢어졌다.<br><br>찢어진 봉투는 숨길 수 없다. 테이프도 없다.<br>그 봉투를 주머니에 넣었다. 정각에 간호사가 빈 칸을 보고 섰다. 계수기를 누르지 않았다. 대신 복도의 다섯 침대를 하나씩 보았다. 이쪽 침대에서 오래 머물렀다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-14, spirit:-16 } },
    { l:'③ 일행 봉투에서 알약만 빼고 봉투는 둔다.', k:'hide', dc:19,
      ok:`다섯 봉투를 열어 알약만 빼고 다시 접었다. 빈 봉투를 칸에 꽂았다.<br><br>정각에 받은 봉투는 비어 있다. 다들 받아서 입에 터는 척했다. 간호사는 손을 보지 입을 보지 않는다.<br>계수기가 다섯 번 딸깍했다.`,
      ng:`빈 봉투가 너무 가볍다. 간호사가 집자마자 알았다.<br><br>봉투를 흔든다. 소리가 없다. 이쪽 얼굴을 본다. 마스크 위 눈이 휘어진다.<br>다음 정각에는 봉투가 아니라 주사기가 왔다. 팔에 바늘 자국이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B2', t:'한방 처치실 — 끓는 탕약',
  x:`한방 처치실 약탕기가 끓는다. 아무도 지키지 않는다.<br><br>
    벽에 처방전이 붙었다. 이름 칸은 비었다. 약재 이름만 열둘.<br>
    처방전을 보면 무엇을 고치려는 약인지 안다. 약재마다 맡은 일이 있다.<br><br>
    열두 가지 중에 고치는 약재는 넷이다. 나머지 여덟은 사람을 무겁게 하는 것들이다.`,
  o:[
    { l:'① 한 숟가락 떠서 맛을 본다.', k:'sense', dc:21,
      doom:{ title:'한 숟가락의 탕약', what:'몸이 무거워져 바닥으로 가라앉습니다', dc:17, sec:55,
        text:`처방전과 맞는지 보려고 한 숟가락 떠서 혀에 굴렸다. 약은 혀로 확인한다. 오래 해 온 일이다.<br><br>쓰다. 그다음 달다. 그다음 무겁다. 혀가 아니라 몸이.<br>숟가락이 손에서 떨어진다. 무릎이 바닥으로 간다. 바닥이 가깝다. 바닥이 따뜻하다.<br><br>복도 끝에서 딸깍 소리가 다가온다. 정각이다. 누가 이쪽 입을 벌려 뱉게 해야 한다.`,
        dieText:`약은 혀로 확인한다. 그 버릇이 오래 살려 주었다.<br><br>이 탕약은 그 버릇을 위해 달였다. 맛을 보는 사람에게 먼저 듣도록.<br>정각 점검에 숫자가 맞았다. 처치실 침대에 하나가 더 누웠다. 아주 무겁게.` },
      ok:`숟가락을 들었다가 내려놓았다. 처방전이 이미 말했다. 맛을 볼 필요가 없다.<br><br>여덟 가지가 무게를 만든다. 그 여덟을 어떤 순서로 넣었는지 약탕기 옆 찌꺼기가 말해 준다. 이 약은 고치는 약이 아니라 눕히는 약이다.<br>약탕기 불을 줄였다. 끓는 소리가 바뀌면 누가 온다. 줄이기만 했다.<br><br>덜 졸여진 탕약은 무게를 덜 만든다. 오늘 밤 이 약을 먹는 사람들은 조금 덜 무거울 것이다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 약재 찌꺼기를 뒤져 고치는 넷만 챙긴다.', k:'gaze', dc:20,
      ok:`약탕기 옆 바구니에 썰어 둔 약재가 있다. 열두 무더기.<br><br>고치는 넷만 골라 한 줌씩 쌌다. 상처를 아물리는 것, 열을 내리는 것, 숨을 트는 것, 피를 맑히는 것.<br>나쁜 여덟 무더기는 손대지 않았다. 손댄 흔적도 세어진다.<br><br>이 병동에도 고치는 약이 있다. 다만 무게 밑에 묻어 쓴다.`,
      ng:`고르다 무더기가 섞였다.<br><br>고치는 것과 무겁게 하는 것이 같은 바구니에서 뒤엉켰다. 다시 가르는 사이 시간이 갔다.<br>딸깍 소리가 처치실 문 앞이다. 약재를 한 움큼 쥐고 커튼 뒤로 숨었다. 쥔 것의 반은 나쁜 쪽이었다. 손바닥이 저려 왔다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'휴게실 — 약 봉투로 접은 학',
  x:`휴게실 탁자에 종이학이 쌓였다. 수백 마리. 노인이 하나를 더 접고 있다.<br><br>
    종이가 다 약봉투다. 흰 바탕에 파란 글씨가 비친다.<br>
    약사는 약봉투를 보면 버릇처럼 읽는다. 이름, 약, 날짜, 시각.<br><br>
    노인은 봉투를 받을 때마다 약은 버리고 봉투로 학을 접었다. 몇 해를.`,
  o:[
    { l:'① 학을 하나씩 펴서 날짜를 읽는다.', k:'gaze', dc:21, wake:1,
      ok:`노인에게 학 몇 마리를 펴 봐도 되냐고 물었다. 노인이 고개를 끄덕인다.<br><br>폈다. 날짜순으로 늘어놓았다. 이 병동의 약이 해마다 바뀐다. 처음엔 순한 약, 그다음 센 약, 그다음 더 센 약. 같은 이름 칸에.<br>그리고 한 달에 한 번씩 봉투가 빈다. 매달 같은 날. 그날은 점검이 없는 날이다. 약을 안 줘도 되는 날.<br><br>그 날짜를 셈하니 오늘이다. 봉투 수백 장이 한 장의 지도가 됐다. 약이 지나간 자리를 읽어 사람이 지나갈 자리를 찾았다.`,
      ng:`펴는데 노인이 갑자기 손을 덮친다. 펴지 말라고.<br><br>학이 찢어졌다. 노인이 운다. 찢어진 학을 끌어안고 다시 접으려 한다. 손이 떨려서 안 접힌다.<br>울음소리에 간호사실 문이 열렸다. 휴게실을 나왔다. 등 뒤에서 노인이 계속 접었다. 찢어진 학을.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 노인에게 약을 왜 안 먹었는지 묻는다.', k:'bond', dc:20,
      ok:`옆에 앉아 학을 하나 같이 접었다. 접으면서 물었다.<br><br>노인이 처음에는 대답을 안 한다. 학 셋을 같이 접고 나서야 말한다. 약을 먹으면 숫자가 된다고. 안 먹으면 이름이 남는다고.<br>노인이 이쪽 손에 학 하나를 쥐여 준다. 펴 보면 안다고.<br><br>나중에 폈다. 봉투 안쪽에 연필로 계단 그림이 그려져 있다. 비상계단. 칠층에서 지하까지. 문 하나에 동그라미.`,
      ng:`묻자 노인이 학 접던 손을 멈춘다.<br><br>그리고 이쪽을 본다. 숫자를 세는 눈으로. 오래 약을 안 먹은 사람의 눈이 아니다.<br>노인이 계수기를 꺼냈다. 딸깍. 휴게실을 뛰쳐나왔다. 문턱에 발가락을 찧었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B2', t:'약제실 — 유리 약장',
  x:`약제실 문이 열려 있다. 유리 약장이 벽을 다 덮었다. 잠겼다.<br><br>
    병, 상자, 서랍. 한쪽 칸은 한방 약재 서랍이다. 이름표가 붙은 작은 서랍 마흔.<br>
    약장을 보면 이 병원이 무엇을 많이 쓰는지 안다. 많이 쓰는 칸이 손에 닿는 높이에 있다.<br><br>
    손 닿는 칸은 전부 잠 오는 약이다. 고치는 약은 맨 위 칸에 먼지를 썼다.`,
  o:[
    { l:'① 유리를 깨지 않고 약장을 연다.', k:'fix', dc:21,
      ok:`약장 자물쇠는 작다. 머리핀을 펴서 넣었다. 약장 자물쇠는 사람 막으려고 단 게 아니다. 순서 지키려고 단 것이다.<br><br>세 번 만에 돌았다. 맨 위 칸에 손을 뻗었다. 상처 약 상자, 그리고 한방 서랍에서 말린 약초 한 뭉치.<br>문을 다시 잠갔다. 핀 자국은 소매로 닦았다.`,
      ng:`핀이 자물쇠 안에서 부러졌다.<br><br>빼려고 할수록 더 들어간다. 자물쇠가 망가졌다. 이제 아무도 못 연다. 내일 아침 누가 이걸 본다.<br>부러진 핀 끝에 손가락을 찔렸다. 피가 유리에 묻었다. 소매로 닦아도 번지기만 했다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 유리 너머로 병을 읽어 둔다.', k:'sense', dc:20,
      ok:`열지 않았다. 유리에 이마를 대고 병마다 읽었다. 이름, 양, 개봉 날짜.<br><br>잠 오는 약 병들이 거의 비었다. 고치는 약 병은 하나도 안 열었다. 그리고 해독제 병 하나. 반쯤 비었다. 잠 오는 약을 깨는 해독제다. 누가 몰래 쓰고 있다.<br>누가 쓰는지는 병 밑 먼지가 말해 준다. 손가락 자국이 작다. 아이 손 같다.<br><br>이 병동 어딘가에 깨어 있으려고 애쓰는 작은 손이 있다.`,
      ng:`읽는 사이 유리에 비친 복도로 흰 모자가 지나간다.<br><br>멈춘다. 유리 속에서 이쪽과 눈이 맞았다. 돌아보지 않았다. 유리 속의 눈이 계속 이쪽을 본다.<br>약제실 불이 꺼졌다. 어둠 속에서 한참 서 있었다. 숨 쉬는 소리가 둘이었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'식당칸 바 — 잔 테두리',
  x:`식당칸 끝 바 카운터에 바텐더가 있다. 잔을 닦는다. 손님이 없는데.<br><br>
    다섯 잔을 따라 카운터에 올린다. 서비스라고 한다. 추운 밤이라고.<br>
    술에 무엇을 타면 어떻게 되는지는 잘 안다. 술은 많은 것을 녹이고 많은 것을 숨긴다.<br><br>
    다섯 잔 중 하나만 테두리가 뿌옇다.`,
  o:[
    { l:'① 잔 테두리를 손끝으로 훑어 본다.', k:'gaze', dc:21,
      ok:`잔을 집는 척 테두리를 엄지로 훑었다. 뿌연 잔.<br><br>까끌하다. 가루가 테두리에 발렸다. 술에 탄 게 아니라 입술 닿는 데 발랐다. 술을 의심하는 사람은 술만 본다.<br>나머지 넷 테두리도 훑었다. 넷 다 맨질맨질하다. 그런데 넷 다 술 색이 같고 뿌연 잔만 조금 연하다.<br><br>뿌연 잔이 미끼다. 넷이 진짜다. 다섯 잔 다 카운터에 그대로 두고 나왔다. 바텐더가 계속 잔을 닦았다.`,
      ng:`훑는데 바텐더가 이쪽 손을 본다.<br><br>닦던 잔을 내려놓는다. 다섯 잔을 도로 거둔다. 말없이. 그리고 여섯 번째 잔을 꺼내 따른다. 이쪽 앞에만.<br>마시지 않았다. 바텐더가 웃으며 그 잔을 쏟았다. 이쪽 손등에. 손등이 화끈하다. 술이 아니었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 마시는 척 소매에 흘린다.', k:'hide', dc:20,
      ok:`잔을 들고 고개를 젖히며 소매 안쪽에 흘렸다. 다섯이 다 따라 했다. 미리 눈짓해 두었다.<br><br>바텐더가 빈 잔을 거둔다. 시계를 본다. 기다린다. 다섯이 잠들기를.<br>다섯이 하품을 했다. 하나씩 고개를 떨궜다. 바텐더가 카운터 뒤로 갔다. 무언가를 가지러.<br><br>그 틈에 다섯이 동시에 일어나 다음 칸으로 갔다. 소매가 축축하고 시큼했다.`,
      ng:`흘리는데 한 사람이 진짜로 한 모금 넘겼다.<br><br>추워서 그랬다고 한다. 곧 눈이 감긴다.<br>나머지 넷이 그 사람을 끌고 일어섰다. 바텐더가 길을 막지 않았다. 대신 웃으며 셌다. 넷 하고 반이라고. 끌고 가는 내내 팔이 빠질 듯했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B3', t:'우편칸 — 등기 약 소포',
  x:`3호차 우편칸 선반에 등기 소포가 줄지어 있다. 끈으로 단단히 묶었다.<br><br>
    소포 하나에 약국 상표가 찍혔다. 받는 곳은 종착역 약국. 보낸 곳 칸은 비었다.<br>
    약 소포는 들어 보면 무엇이 들었는지 대충 안다. 무게, 흔들리는 소리, 상자 모서리 젖은 모양.<br><br>
    흔들면 유리병이 아니라 마른 것이 사각거린다.`,
  o:[
    { l:'① 끈을 풀어 열어 본다.', k:'luck', dc:20,
      ok:`매듭을 하나씩 풀었다. 다시 묶을 수 있게.<br><br>안에 마른 약초가 꾹꾹 들었다. 상처에 쓰는 것, 열에 쓰는 것. 좋은 것이다. 종착역 약국은 진짜 약을 받는다.<br>한 뭉치만 빼고 다시 묶었다. 매듭 모양까지 똑같이.<br><br>상자 바닥에 영수증이 있다. 받는 사람 서명란에 이미 서명이 됐다. 아직 도착도 안 했는데.`,
      ng:`끈을 푸는데 소포가 꿈틀했다.<br><br>마른 것이 아니다. 사각거린 건 다리다. 수십 개.<br>상자를 떨어뜨렸다. 쏟아져 나온 것들이 선반 밑으로 흩어진다. 하나가 소매로 들어왔다. 팔뚝을 물었다. 팔이 저려 왔다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 받는 사람 칸의 글씨를 읽는다.', k:'gaze', dc:21,
      ok:`받는 곳은 종착역 약국. 그 밑에 작게 받는 사람 이름. 약사 이름이다.<br><br>글씨가 낯익다. 이쪽 글씨다. 이쪽 손버릇이 그대로 있다. 받침 쓰는 모양까지.<br>종착역 약국에서 약을 받을 사람이 이쪽으로 정해져 있다.<br><br>소포를 선반 맨 안쪽, 다른 소포들 밑에 묻었다. 받을 사람이 내리지 않으면 소포도 안 내린다.`,
      ng:`읽는데 글씨가 젖어 번진다. 이쪽 손에 땀이 났다.<br><br>번진 이름을 손가락으로 문지르는데 소포 끈이 손목에 걸렸다. 선반이 기울었다. 소포 더미가 쏟아졌다.<br>밑에 깔렸다. 상자 모서리가 갈비를 눌렀다. 빠져나오는 데 한참 걸렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B3', t:'2호차 — 입마개 한 개들',
  x:`2호차 화물칸에 개 다섯 마리가 묶여 있다. 입마개를 했다. 이쪽을 보고 낮게 운다.<br><br>
    줄이 길다. 칸 한가운데까지 닿는다. 지나가려면 그 사이를 지나야 한다.<br>
    짐승에게도 약은 듣는다. 몸무게만 셈하면 된다.<br><br>
    주머니에 아까 빼 둔 잠 오는 알약과 말린 고기 조금이 있다.`,
  o:[
    { l:'① 몸무게를 셈해 고기에 알약을 재워 던진다.', k:'fix', dc:21, wake:1,
      ok:`개 덩치를 눈으로 쟀다. 사람의 반. 알약 반 알이면 한 마리가 잔다. 더 주면 안 깬다. 덜 주면 화만 낸다.<br><br>알약을 반씩 쪼개 말린 고기 사이에 끼웠다. 입마개 틈으로 들어갈 크기로. 던졌다. 하나씩.<br>개들이 입마개 틈으로 고기를 핥아 먹는다. 한참 뒤 하나씩 엎드린다. 숨은 고르다.<br><br>사람 몸에만 맞추던 양을 짐승 몸에 다시 맞췄다. 무게 하나로 약을 다시 짓는 셈이 손에 붙었다. 다섯 다 살아서 잤다.`,
      ng:`던졌는데 고기가 입마개 틈으로 안 들어간다.<br><br>개들이 입마개째 고기를 문지르다 화를 낸다. 줄이 팽팽해진다. 하나가 줄을 끊을 듯 당긴다.<br>칸 끝으로 물러났다. 다른 길이 없다. 개들이 지칠 때까지 기다렸다. 그사이 시계가 한참 갔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 입마개를 풀어 직접 약을 먹인다.', k:'bond', dc:20,
      doom:{ title:'풀어 준 입마개', what:'개들에게 물려 끌려갑니다', dc:17, sec:50,
        text:`가장 순해 보이는 개에게 다가가 입마개 끈을 풀었다. 약은 입에 넣어야 확실하다.<br><br>끈이 풀리자 개가 기다렸다는 듯 손목을 문다. 아프지 않게. 정확하게. 놓지 않게.<br>다른 개들이 일어선다. 줄이 다 같이 한쪽으로 당겨진다. 칸 구석, 짐 더미 뒤로.<br><br>짐 더미 뒤에 무엇이 있는지 개들은 안다. 누가 줄을 끊어 주어야 한다.`,
        dieText:`약은 입에 넣어야 확실하다. 그 생각이 틀리지는 않았다.<br><br>개들도 입마개를 왜 하고 있었는지 알았다. 풀어 줄 사람을 기다렸다.<br>2호차 개는 여섯 마리가 됐다. 여섯 번째는 묶여 있지 않았다.` },
      ok:`끈에 손을 대다 멈췄다. 개 눈이 이쪽 손이 아니라 끈을 본다.<br><br>입마개는 짐승을 묶는 게 아니라 사람을 지키려고 한 것이다. 이 개들은 풀리기만 기다린다.<br>손을 거두고 알약을 고기에 끼워 입마개 틈으로 밀어 넣었다. 느렸다. 안전했다.`,
      win:{ exp:18, dream:3 } },
    { l:'③ 쓴 풀을 비벼 뿌려 코를 막는다.', k:'sense', dc:20,
      ok:`쓴 풀과 매운 씨앗을 손바닥에서 비벼 칸 바닥에 뿌렸다. 개들 코 쪽으로.<br><br>개들이 재채기를 한다. 고개를 돌린다. 냄새를 못 맡으니 이쪽이 어디 있는지 모른다.<br>벽에 붙어 지나갔다. 개들은 계속 재채기만 했다.`,
      ng:`뿌리는데 열차 바람이 거꾸로 분다.<br><br>매운 가루가 이쪽 눈으로 들어왔다. 눈을 못 뜬다. 더듬어 지나가다 개 줄에 발이 걸렸다.<br>개가 입마개째 정강이를 들이받았다. 다리에 시퍼런 멍이 들었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B3', t:'침대칸 — 잠든 승객들',
  x:`7호차 침대칸 승객이 전부 잔다. 하나도 안 깬다. 열차가 크게 흔들려도.<br><br>
    침대마다 머리맡에 찻잔이 놓였다. 다 비었다. 바닥에 갈색 얼룩이 말랐다.<br>
    잔 바닥을 맡으면 무엇을 마셨는지 안다. 차는 날아가도 약은 남는다.<br><br>
    이쪽 일행 다섯의 머리맡에도 찻잔이 놓였다. 아직 따뜻하다.`,
  o:[
    { l:'① 승객 찻잔 바닥을 맡아 무엇인지 가린다.', k:'sense', dc:20,
      ok:`빈 잔 바닥에 코를 댔다. 보리차 냄새, 그 밑에 쓴 흙냄새. 뿌리를 달인 냄새다.<br><br>잠을 깊게 하는 뿌리다. 하룻밤이면 깬다. 그런데 승객들 입가가 말랐다. 며칠을 이렇게 잤다. 매일 밤 누가 잔을 채웠다.<br>일행 다섯 잔을 다 창밖에 쏟았다. 빈 잔은 머리맡에 도로 놓았다.<br><br>잔을 채우는 사람은 잔이 비면 마신 줄 안다. 그게 이 칸의 셈이다.`,
      ng:`맡는데 찻잔 바닥에 남은 가루를 들이마셨다.<br><br>마른 가루는 김보다 세다. 눈꺼풀이 천근이다. 침대 사다리에 기대 섰다. 무릎이 녹는다.<br>일행이 뺨을 때려 깨웠다. 깨고 나서도 한참 열차가 두 대로 보였다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 승객 하나를 깨워 본다.', k:'heal', dc:21,
      ok:`가장 덜 마른 얼굴의 승객 귀밑을 세게 눌렀다. 쓴 잎을 혀 밑에 넣었다.<br><br>한참 뒤 눈꺼풀이 떨린다. 반쯤 뜬다. 이쪽을 본다. 입술이 움직인다. 『내리는 문은… 맨 앞….』<br>다시 잠들었다. 그래도 한마디를 얻었다. 며칠 잠든 사람이 붙들고 있던 한마디.`,
      ng:`눌렀는데 승객이 벌떡 일어난다. 눈은 감은 채로.<br><br>잠든 채로 이쪽 어깨를 잡는다. 힘이 세다. 침대로 끌어당긴다. 같이 자자는 듯이.<br>셋이 떼어 냈다. 어깨에 손가락 자국이 다섯 개 남았다. 승객은 다시 누웠다. 아무 일 없었다는 얼굴로.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ hp:-22, spirit:-14 } }
  ] }

]);

// ── 의원 (physician) · 내공 ──
kJob('physician', 'B', [

{ at:'B', t:'숨은 자리 — 맥을 늦춘다',
  x:`좁은 틈에 다섯이 숨었다. 밖에 무언가 서 있다. 움직이지 않는다.<br><br>
    듣고 있다. 숨소리를. 어쩌면 그보다 작은 것을.<br>
    의원은 겁먹은 사람의 맥이 얼마나 시끄러운지 안다. 귀 밝은 것은 그 소리를 듣는다.<br><br>
    다섯 맥이 다 빠르다. 손목을 잡지 않아도 들린다.`,
  o:[
    { l:'① 내공을 실어 동료들 손목 혈을 눌러 맥을 늦춘다.', k:'heal', dc:20, cost:{ qi:25 },
      ok:`손을 뻗어 옆 사람 손목 안쪽을 엄지로 눌렀다. 내공을 아주 가늘게 실어. 맥 하나가 반 박자 느려진다.<br><br>다음 사람, 그다음 사람. 다섯 손목을 차례로 눌렀다. 숨이 따라 느려진다. 틈 안이 조용해진다.<br>밖에 선 것이 한참 듣는다. 들을 게 없다.<br><br>그것이 떠났다. 눌렀던 손목을 놓자 맥들이 다시 뛰기 시작한다. 이번엔 안도해서.`,
      ng:`누르는데 한 사람 맥이 오히려 튄다. 갑자기 눌린 게 놀라웠던 것이다.<br><br>그 사람이 숨을 들이켠다. 크게. 밖에 선 것이 이쪽으로 고개를 돌린다.<br>틈 입구를 긁는 소리가 났다. 오래. 이쪽 엄지는 그 사람 손목을 놓지 못했다. 엄지가 저려서 감각이 없어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 제 맥까지 바닥으로 늦춘다.', k:'steady', dc:21,
      doom:{ title:'멈춘 맥', what:'맥이 멎어 갑니다', dc:17, sec:55,
        text:`제 목 옆 혈을 눌렀다. 맥이 느려진다. 더 눌렀다. 더 느려진다.<br><br>남의 맥은 어디서 멈춰야 하는지 안다. 제 맥은 어디서 멈추는지 모른다. 숫자를 세던 머리부터 느려지니까.<br>세 박자에 한 번. 다섯 박자에 한 번. 손가락이 혈에서 안 떨어진다.<br><br>밖에 선 것이 떠났다. 이쪽 맥도 떠나려 한다. 누가 손가락을 떼고 가슴을 쳐 주어야 한다.`,
        dieText:`의원은 남의 맥을 늦추고 다시 빠르게 할 줄 안다.<br><br>제 맥은 늦출 줄만 알았다. 다시 빠르게 하는 손이 제 목에 붙어 있었으니까.<br>틈 안이 아주 조용했다. 밖에서 무엇이 들어도 아무것도 안 들렸을 것이다.` },
      ok:`목 옆 혈에 손가락을 댔다가 엄지 하나만 남겼다. 반만 눌렀다.<br><br>맥이 느려진다. 다섯 박자에서 멈추고 손을 뗐다. 숫자를 세는 머리가 아직 맑을 때.<br>틈 안에서 이쪽 맥이 제일 조용했다. 다른 넷이 이쪽 숨에 맞춰 숨을 쉬었다.<br><br>밖에 선 것이 떠났다. 제 맥은 반만 건드린다. 그게 오래 사는 법이다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'B', t:'빗속 — 거짓말하는 맥',
  x:`빗속에서 남자 하나가 다가온다. 출구를 안다고 한다. 데려다주겠다고.<br><br>
    말은 차분하다. 얼굴도 차분하다. 손에는 힘이 없다.<br>
    맥은 사람이 말하지 않는 것을 말한다. 오래 짚은 손가락은 그걸 듣는다.<br><br>
    남자가 악수를 청한다.`,
  o:[
    { l:'① 악수하며 손목을 감싸 묻는다.', k:'gaze', dc:20, wake:1,
      ok:`악수를 받으며 엄지를 남자 손목 안쪽에 얹었다. 자연스럽게.<br><br>출구가 어디냐고 물었다. 맥이 고르다. 몇 명이 나갔냐고 물었다. 고르다. 당신도 나가 봤냐고 물었다.<br>한 박자가 건너뛴다. 그다음 두 박자가 붙어서 뛴다. 대답은 네. 맥은 아니라고 했다.<br><br>손을 놓고 고맙다고 했다. 그리고 반대쪽으로 갔다. 병을 짚던 손가락이 마음을 짚었다. 맥이 숨기는 것까지 듣는 귀가 하나 더 생겼다.`,
      ng:`손목을 감싸는 순간 남자가 이쪽 손목을 거꾸로 감싼다.<br><br>엄지가 정확히 맥 자리에 얹힌다. 남자가 묻는다. 무서우냐고. 이쪽 맥이 대답했다.<br>남자가 웃으며 손을 놓았다. 그 뒤로 남자는 이쪽이 겁먹는 길만 골라 앞장섰다. 골목 끝에서 둘이 미끄러져 다쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 빗물 젖은 얼굴빛을 본다.', k:'sense', dc:21,
      ok:`빗물이 얼굴을 씻어 낸다. 분칠한 데가 있으면 씻긴다.<br><br>남자 귀밑이 하얗게 드러난다. 입술은 붉게 칠했다. 귀밑은 피가 안 도는 색이다. 오래 굶었거나, 오래 무엇을 두려워한 사람.<br>그런 사람이 차분하다. 차분한 게 아니라 굳은 것이다. 누가 시켜서 하는 말이다.<br><br>남자가 앞장서는 길로 가지 않았다. 남자는 따라오지 않았다. 빗속에서 뒤를 돌아보며 한참 서 있었다.`,
      ng:`보는데 빗줄기가 굵어져 아무것도 안 보인다.<br><br>남자가 이쪽 팔을 잡아끈다. 이쪽이라고. 끌려가다 발을 빼냈다.<br>남자 손에서 팔을 빼느라 팔꿈치가 꺾였다. 남자는 놓친 걸 아쉬워하지 않았다. 다음 사람을 기다리는 얼굴이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'비 — 막힌 기',
  x:`밤새 비를 맞았다. 다들 등이 굳었다. 걸음이 뻣뻣하다.<br><br>
    찬 비는 살이 아니라 등줄기로 들어온다. 등의 혈이 하나씩 닫힌다.<br>
    닫힌 혈은 손바닥으로 안다. 닫힌 자리는 다른 데보다 차다.<br><br>
    다섯 등에 찬 자리가 다 있다. 뛰어야 할 다리가 그 혈에서 시작된다.`,
  o:[
    { l:'① 내공으로 등줄기 혈을 차례로 데운다.', k:'heal', dc:20, cost:{ qi:24 },
      ok:`한 사람씩 등을 돌려 앉혔다. 목뼈 밑에서 허리까지 손바닥을 미끄러뜨리며 내공을 실었다.<br><br>찬 자리에서 손을 멈추고 데웠다. 닫힌 혈이 열리면 손바닥 밑이 축축해진다. 찬 습기가 빠져나온 것이다.<br>다섯 등을 다 했다. 다들 허리를 편다. 걸음이 풀린다.<br><br>이쪽 등만 굳은 채로 남았다. 제 등에는 손이 안 닿는다.`,
      ng:`데우는데 빗물이 계속 등을 적신다.<br><br>여는 만큼 다시 닫힌다. 내공만 빠져나갔다.<br>다섯 다 그대로다. 이쪽은 손끝까지 찼다. 뛰다가 둘이 다리가 꼬여 넘어졌다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 서로 손바닥 가운데를 누르게 가르친다.', k:'fix', dc:19,
      ok:`둘씩 마주 앉혔다. 손바닥 한가운데 오목한 데를 엄지로 누르라고. 숨을 내쉴 때마다.<br><br>그 혈은 몸 안의 열을 손끝까지 보낸다. 스스로는 잘 안 된다. 남이 눌러 줘야 한다.<br>다섯이 서로를 눌렀다. 손이 따뜻해진다. 손이 따뜻하면 다리도 따라온다.<br><br>이쪽 손바닥은 일행 하나가 눌러 주었다. 서툴게. 그래도 데워졌다.`,
      ng:`누르는 자리를 다들 못 찾는다. 엉뚱한 데를 꾹꾹 누른다.<br><br>하나씩 다시 짚어 주는 사이 시간이 갔다. 비가 더 세졌다.<br>결국 차가운 손으로 일어섰다. 계단 난간을 놓쳐 하나가 굴렀다. 받다가 이쪽 손목이 접혔다.`,
      win:{ exp:15, dream:2, spirit:6 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'시계 없는 방 — 맥으로 센다',
  x:`시계를 빼앗겼다. 순찰 간격을 알아야 나간다.<br><br>
    방에는 아무것도 없다. 똑딱거릴 것도, 떨어지는 물방울도.<br>
    몸에는 시계가 있다. 손목에. 고른 맥은 일 분에 일흔 남짓 뛴다. 오래 짚은 손가락은 그 숫자를 몸으로 안다.<br><br>
    문제는 지금 이쪽 맥도 겁을 먹었다는 것이다.`,
  o:[
    { l:'① 제 맥을 고르게 앉히고 센다.', k:'steady', dc:20, wake:1,
      ok:`눈을 감고 숨을 길게 쉬었다. 맥이 가라앉기를 기다렸다. 일흔둘. 이 숫자에 앉을 때까지.<br><br>앉고 나서 셌다. 발소리가 지나가고 다음 발소리까지. 맥 천삼백. 다음에도 천삼백. 다음엔 천백.<br>새벽이 가까워 순찰이 빨라진다. 천백의 반에 문을 열었다.<br><br>복도를 다 지나고 나서 등 뒤로 발소리가 났다. 제 맥을 시계로 쓰는 법이 손목에 앉았다. 겁먹은 몸 안에서도 박자 하나는 제 것으로 붙들어 둘 수 있게 됐다.`,
      ng:`세다가 맥이 튀었다. 문밖 소리에 놀라서.<br><br>천삼백이 천육백이 됐는지 천이백이 됐는지 모른다. 숫자가 무너졌다.<br>무너진 숫자로 문을 열었다. 복도 끝에서 손전등이 켜졌다. 문을 닫다 손가락이 끼었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 내공을 돌려 맥을 억지로 고르게 한다.', k:'fix', dc:21, cost:{ qi:20 },
      ok:`단전에서 내공을 한 바퀴 돌렸다. 맥이 내공을 타고 고르게 펴진다. 억지로.<br><br>고르게 펴진 맥으로 셌다. 정확하다. 대신 내공이 계속 샌다. 돌리기를 멈추면 맥이 다시 날뛴다.<br>세 번 재고 문을 열었다. 틈은 정확히 거기 있었다.`,
      ng:`돌리는데 내공이 가슴에서 막힌다.<br><br>맥이 고르게 펴지는 대신 엉킨다. 가슴이 답답하다. 숨이 짧아진다.<br>세던 숫자를 놓고 주저앉았다. 그날 밤은 틈을 하나도 못 찾았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B', t:'추격 — 꺾인 발목',
  x:`뛰다가 동료가 발목을 꺾었다. 계단 끝에서.<br><br>
    순식간에 붓는다. 일어나려다 다시 주저앉는다.<br>
    발목은 만져 보면 뼈인지 힘줄인지 안다. 그리고 몇 분이면 다시 디딜 수 있는지도.<br><br>
    뒤쪽 계단에서 발소리가 내려온다. 몇 분도 없다.`,
  o:[
    { l:'① 발목 위아래 혈을 짚어 붓기를 묶어 둔다.', k:'heal', dc:20,
      ok:`발목 안쪽 복사뼈 위 혈, 그리고 발등 혈. 두 엄지로 동시에 눌렀다. 세게.<br><br>붓기가 더 번지지 않는다. 혈이 붓는 길을 막았다. 뼈는 아니다. 힘줄이 놀랐다.<br>천으로 발목을 8자로 감았다. 혈 자리에 매듭을 두었다. 걸을 때마다 매듭이 혈을 누르게.<br><br>동료가 절룩이며 뛴다. 절룩이는 만큼 매듭이 누른다. 뛸수록 덜 붓는다.`,
      ng:`누르는데 동료가 발을 뺀다. 아프다고.<br><br>다시 잡을 때 이미 발소리가 계단 중간이다. 감기만 하고 끌었다.<br>동료가 이쪽 어깨에 매달려 뛰었다. 둘이 같이 벽에 부딪쳤다. 어깨가 빠질 듯 아프다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 내공으로 발목을 감싸 한동안 버티게 한다.', k:'heal', dc:21, cost:{ qi:26 },
      ok:`발목을 두 손으로 감싸고 내공을 둘렀다. 붓기 위에 얇은 막을 씌우듯.<br><br>동료가 일어선다. 디딘다. 아프지 않다고 놀란다.<br>안 아픈 게 아니다. 아픔이 내공 밖에서 기다리는 것이다. 한 시간쯤.<br><br>한 시간 안에 숨을 곳을 찾았다. 막을 걷자 동료가 이를 악문다. 그래도 그때는 쫓는 것이 없었다.`,
      ng:`두르는데 내공이 발목에서 미끄러진다. 붓기가 너무 빠르다.<br><br>막이 찢어졌다. 동료가 디디다 비명을 지른다. 발소리가 빨라진다.<br>업었다. 업은 채로 계단을 뛰어내려 갔다. 무릎이 끊어질 것 같았다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'네온 아래 — 얼굴빛이 거짓말한다',
  x:`창밖 네온이 방 안을 물들인다. 빨강, 초록, 다시 빨강.<br><br>
    다섯 얼굴이 다 아파 보인다. 빨간 빛엔 열 난 얼굴, 초록 빛엔 피 빠진 얼굴.<br>
    얼굴빛으로 속을 보는 눈이다. 그런데 이 빛 아래서는 얼굴빛이 아무것도 말하지 않는다.<br><br>
    그런데 누군가 정말 아프다. 아까부터 숨이 이상하다. 누군지 모르겠다.`,
  o:[
    { l:'① 손톱을 하나씩 눌러 돌아오는 빛을 본다.', k:'gaze', dc:20, wake:1,
      ok:`다섯 손을 하나씩 잡아 엄지손톱을 꾹 눌렀다 뗐다. 하얘졌다가 붉게 돌아오는 데 걸리는 시간.<br><br>네온은 색을 바꿔도 시간을 바꾸지 못한다. 넷은 금방 돌아온다. 하나는 숨 두 번이 걸린다.<br>그 사람 배를 눌러 보니 오른쪽 아래가 딱딱하다. 아까 부딪친 데다. 안에서 피가 고이고 있다.<br><br>빛을 보던 눈이 시간을 보기 시작했다. 색이 거짓말하는 데서도 피가 도는 빠르기는 거짓말을 안 한다.`,
      ng:`누르는데 손톱 색이 네온에 따라 바뀐다. 하얀지 빨간지 모르겠다.<br><br>다섯 다 괜찮아 보였다. 넘어갔다.<br>한 시간 뒤 하나가 쓰러졌다. 배를 움켜쥐고. 그때서야 알았다. 알고 나서 할 수 있는 건 적었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 혀를 내밀어 보라고 한다.', k:'heal', dc:21,
      ok:`다섯에게 혀를 내밀라고 했다. 다들 웃다가 내민다.<br><br>혀는 입 안에 있어서 네온이 덜 닿는다. 넷은 붉다. 하나는 하얗다. 핏기가 없다.<br>그 사람을 눕혔다. 배 오른쪽 아래가 딱딱하다. 눌러 둘 혈을 짚고 움직이지 말라고 했다.`,
      ng:`혀를 보자니까 아무도 안 내민다. 지금 그럴 때냐고.<br><br>설명할 시간이 없었다. 그냥 넘어갔다.<br>쓰러진 사람을 업고 뛸 때 알았다. 혀를 봤어야 했다. 업고 뛴 이쪽 허리가 비틀렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'잠긴 방 — 숨이 막힌 동료',
  x:`문이 밖에서 잠긴 방이다. 공기가 탁하다. 오래 닫혀 있었다.<br><br>
    동료 하나가 숨을 쌕쌕거린다. 가슴을 움켜쥔다. 목이 조인다고 한다.<br>
    숨이 막힐 때 짚는 혈이 있다. 목 아래 오목한 데, 가슴 한가운데, 엄지 밑 두툼한 데.<br><br>
    쌕쌕 소리가 점점 가늘어진다.`,
  o:[
    { l:'① 세 혈을 차례로 짚어 숨길을 연다.', k:'heal', dc:20,
      ok:`목 아래 오목한 데를 엄지로 눌렀다. 쌕쌕 소리가 조금 굵어진다.<br><br>가슴 한가운데를 손바닥 뿌리로 눌렀다 뗐다. 엄지 밑 두툼한 데를 꼬집듯 짚었다. 세 번째에 동료가 기침을 한다. 길게.<br>기침 끝에 숨이 들어간다. 깊게.<br><br>숨길은 하나가 아니다. 셋이 같이 열려야 열린다.`,
      ng:`목 아래를 누르는데 동료가 손을 쳐 낸다. 목을 누르니 더 막힌다고.<br><br>틀린 말이 아니다. 너무 세게 눌렀다.<br>다시 짚을 때 동료가 정신을 반쯤 놓았다. 숨이 돌아오는 데 오래 걸렸다. 이쪽 손이 내내 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 앞으로 숙이게 하고 등을 두드린다.', k:'bond', dc:19,
      ok:`동료를 앉혀 앞으로 숙이게 했다. 팔을 무릎에 얹고. 그 자세가 숨이 제일 잘 들어간다.<br><br>등을 손바닥으로 둥글게 두드렸다. 천천히. 숨에 맞춰.<br>쌕쌕 소리가 굵어지다 기침으로 바뀐다. 가래를 뱉는다. 숨이 길어진다.<br><br>동료가 한참 숙인 채 있었다. 이쪽 손이 등에 있는 동안은 숨을 잘 쉬었다.`,
      ng:`숙이게 했는데 동료가 자꾸 일어선다. 문을 두드리러.<br><br>문을 두드릴수록 숨이 더 가빠진다. 붙잡아 앉혔다. 몸부림치는 팔꿈치에 이쪽 턱이 맞았다.<br>입 안이 터졌다. 동료 숨은 한참 뒤에야 돌아왔다.`,
      win:{ exp:15, dream:2, mind:6 }, lose:{ hp:-20, mind:-12 } },
    { l:'③ 방 안에서 바람 드는 틈을 찾는다.', k:'sense', dc:21,
      ok:`벽마다 손바닥을 대고 돌았다. 손바닥은 바람을 안다. 혈을 찾을 때처럼.<br><br>문 반대쪽 벽 아래 걸레받이 뒤에서 찬 기운이 샌다. 걸레받이를 뜯었다. 손가락 두 개 틈.<br>동료를 그 앞에 엎드리게 했다. 찬 바람을 마시게. 숨이 돌아온다.<br><br>틈 너머에서 비 냄새가 났다. 밖이 가깝다.`,
      ng:`도는 사이 동료 숨이 더 가늘어졌다.<br><br>틈을 찾았을 때는 동료가 쓰러진 뒤였다. 끌어다 틈 앞에 눕혔다.<br>숨은 돌아왔다. 늦게. 걸레받이를 뜯다 손톱이 두 개 들렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 쉼 — 제 맥',
  x:`마지막 문 앞이다. 다들 숨을 고른다.<br><br>
    의원이 제 손목을 잡았다. 남의 맥은 하루에 수십 번 짚는다. 제 맥은 잘 안 짚는다.<br>
    짚어 보니 지쳤다. 맥이 가늘고 빠르다. 내공도 바닥이 보인다.<br><br>
    문 너머에서 무엇이 기다리는지 모른다. 남은 것을 어디에 쓸지 정해야 한다.`,
  o:[
    { l:'① 눈을 감고 지친 제 맥을 끝까지 듣는다.', k:'steady', dc:20, wake:1,
      ok:`눈을 감았다. 제 맥을 남의 맥처럼 들었다. 가늘고 빠르고, 세 박자마다 한 번 약하다.<br><br>약한 박자는 피로다. 빠른 건 겁이다. 가는 건 굶주림이다. 셋을 갈라 들으니 겁은 생각보다 작다.<br>작은 것부터 내려놓았다. 숨 열 번. 맥이 굵어진다.<br><br>남을 짚던 손가락이 저를 짚었다. 제 몸을 남의 몸처럼 들을 수 있게 되자 겁이 병처럼 보였다. 병이면 다룰 수 있다.`,
      ng:`듣는데 맥 소리가 커진다. 들을수록.<br><br>제 맥에 겁을 먹었다. 겁먹은 맥은 더 빨라진다. 빨라진 맥에 더 겁을 먹었다.<br>손을 떼고도 한참 가슴이 뛰었다. 문을 열 때 손이 떨려 손잡이를 두 번 놓쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 남은 내공을 가장 지친 동료에게 넘긴다.', k:'heal', dc:21, cost:{ qi:22 },
      ok:`가장 지친 동료 등 한가운데에 손바닥을 댔다. 남은 내공을 천천히 밀어 넣었다.<br><br>그 사람 맥이 굵어진다. 이쪽 맥이 가늘어진다. 딱 그만큼.<br>그 사람이 일어선다. 문을 여는 손이 그 사람 손이었다.`,
      ng:`밀어 넣는데 그 사람 몸이 내공을 받지 못한다. 너무 지쳤다.<br><br>넘친 내공이 이쪽으로 되돌아와 가슴을 친다. 기침이 터졌다. 피가 조금 섞였다.<br>둘 다 더 지쳤다. 문 앞에서 한참 일어나지 못했다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-22, mind:-12 } },
    { l:'③ 다섯에게 숨 고르는 혈 하나를 가르친다.', k:'fix', dc:19,
      ok:`손목 안쪽 손가락 세 마디 위. 거기를 누르면 가슴이 가라앉는다. 다섯에게 짚어 주었다.<br><br>문 너머에서 무엇을 만나든 숨이 막히면 거기를 누르라고.<br>다섯이 제 손목을 잡고 섰다. 맥을 짚는 사람처럼.`,
      ng:`가르치는데 다들 손이 떨려 자리를 못 찾는다.<br><br>찾아 주는 사이 문 너머 소리가 바뀌었다. 기다리던 것이 움직이기 시작했다.<br>다 가르치지 못하고 문을 열었다. 문틀에 걸려 둘이 넘어졌다.`,
      win:{ exp:15, dream:2, spirit:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 먼저 갇힌 사람',
  x:`냉동 창고 안쪽 레일 밑에 사람이 웅크리고 있다. 이쪽 일행이 아니다. 먼저 갇혔다.<br><br>
    눈썹에 성에가 앉았다. 입술이 보랗다. 손목을 짚으니 맥이 아주 느리다. 느리지만 있다.<br>
    언 사람은 기가 안 도는 것이다. 피는 기를 따라간다. 기를 먼저 보내야 피가 따라온다.<br><br>
    창고 밖에서 고무장화 소리가 레일을 따라 온다.`,
  o:[
    { l:'① 손목 혈로 내공을 가늘게 흘려 깨운다.', k:'heal', dc:21, cost:{ qi:28 },
      ok:`손목 안쪽에 엄지를 얹고 내공을 실처럼 가늘게 흘렸다. 굵게 넣으면 언 혈이 터진다.<br><br>기가 팔꿈치, 어깨, 가슴으로 간다. 오래 걸린다. 기다렸다. 고무장화 소리를 세며.<br>맥이 조금 빨라진다. 눈꺼풀이 떨린다. 입술에 색이 돈다.<br><br>그 사람이 눈을 뜨고 처음 한 말은 이름이 아니었다. 『다섯 시에 문이 열려요. 바깥에서.』`,
      ng:`흘리는데 언 혈이 내공을 받지 못한다.<br><br>내공이 손목에서 고인다. 더 밀면 혈이 상한다. 손을 뗐다.<br>고무장화 소리가 가까워졌다. 그 사람을 두고 레일 그늘로 물러났다. 그 사람 눈이 이쪽을 따라왔다. 성에 낀 눈이.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 일단 업고 창고 밖으로 나간다.', k:'steady', dc:20,
      ok:`업었다. 언 사람은 나무처럼 굳어 무겁다. 등에 얼음을 업은 것 같다.<br><br>레일 사이로 빠져나왔다. 창고 밖 비가 오히려 따뜻하다.<br>그 사람을 박스 더미 그늘에 눕히고 품에 손을 넣어 녹였다. 맥이 조금씩 빨라진다.`,
      ng:`업는데 그 사람 옷이 바닥 얼음에 붙어 있다. 찢어지는 소리.<br><br>고무장화 소리가 멈췄다. 그리고 빨라졌다.<br>업은 채로 뛰었다. 레일 모서리에 정강이를 찍었다. 등의 사람이 더 무거워진 것 같았다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B1', t:'경매장 — 장대에 맞은 머리',
  x:`경매장 바닥을 기다 동료가 갈고리 장대에 머리를 맞았다. 휘두른 게 아니다. 세워 둔 게 넘어졌다.<br><br>
    동료가 일어선다. 괜찮다고 한다. 웃는다. 같은 말을 두 번 한다.<br>
    머리를 맞은 사람이 같은 말을 되풀이하면 걱정해야 한다.<br><br>
    이층 사무실 불이 아직 켜져 있다. 오래 머물 수 없다.`,
  o:[
    { l:'① 눈동자와 맥을 함께 본다.', k:'gaze', dc:20,
      ok:`손전등을 손가락 사이로 가려 아주 가는 빛만 냈다. 눈앞에 대고 움직였다.<br><br>두 동공이 같이 줄어든다. 같이 따라온다. 맥은 빠르지만 고르다.<br>머리 안은 괜찮다. 겁이 말을 되풀이하게 했다.<br><br>그래도 한 시간마다 이름을 물었다. 다섯 번 다 맞혔다. 맞힐 때마다 그 사람이 조금 덜 웃었다.`,
      ng:`빛을 비추는데 한쪽 동공이 안 줄어든다.<br><br>안에서 피가 고이기 시작했다. 지금 할 수 있는 게 없다. 눕혀야 하는데 누울 데가 없다.<br>그 사람을 부축해 걸었다. 남은 길 내내 그 사람 맥을 짚고 걸었다. 이쪽 손목도 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 목 뒤 두 혈을 짚어 어지럼을 가라앉힌다.', k:'heal', dc:21,
      ok:`목 뒤 머리뼈 밑, 양쪽 오목한 데를 엄지로 눌렀다. 위로 밀어 올리듯.<br><br>동료가 눈을 감는다. 숨을 길게 쉰다. 되풀이하던 말이 멈춘다.<br>어지럼은 목에서 머리로 올라간다. 목에서 막으면 덜 올라간다.<br><br>동료가 혼자 일어섰다. 처음으로 같은 말을 한 번만 했다.`,
      ng:`누르는데 동료가 토한다. 바닥에.<br><br>소리가 났다. 이층 사무실 창이 열린다. 회색 비옷이 내려다본다.<br>토한 자리를 두고 기었다. 회색 비옷이 그 자리를 오래 보았다. 그리고 내려왔다. 닦으러. 무릎이 수조 모서리에 갈렸다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B1', t:'야적장 — 컨테이너 사이 끼인 가슴',
  x:`컨테이너 두 개 사이 틈에 동료가 끼었다. 크레인이 하나를 옮기다 놓았다.<br><br>
    가슴이 눌렸다. 숨이 짧다. 한 번에 반밖에 못 쉰다.<br>
    숨소리를 들으면 갈비가 몇 대 나갔는지 안다. 둘이다. 하나는 안쪽으로 눌렸다.<br><br>
    크레인이 다시 돈다. 컨테이너가 조금씩 흔들린다.`,
  o:[
    { l:'① 틈으로 들어가 가슴 혈을 짚는다.', k:'heal', dc:21,
      doom:{ title:'좁아지는 틈', what:'컨테이너 사이에 끼었습니다', dc:17, sec:50,
        text:`옆으로 몸을 틀어 틈에 들어갔다. 동료 가슴 혈에 손가락이 닿았다. 짚었다. 숨이 반 치 길어진다.<br><br>그때 크레인이 다시 돌았다. 쇠가 쇠를 미는 소리. 틈이 손가락 한 마디만큼 좁아진다.<br>이번엔 이쪽 등이 눌린다. 숨이 반으로 줄었다. 동료처럼.<br><br>둘이 같은 틈에서 반씩 숨을 쉰다. 누가 바깥에서 컨테이너를 밀어 주어야 한다.`,
        dieText:`숨을 짚으러 틈에 들어가는 손이 있다.<br><br>쇠는 숨을 모른다. 크레인 운전석은 비어 있었다. 아무도 돌리지 않았는데 돌았다.<br>새벽에 컨테이너가 배에 실렸다. 두 개가 꼭 붙은 채로.` },
      ok:`들어가려다 컨테이너 바닥을 봤다. 바닥 쇠가 조금씩 미끄러진다. 크레인 줄이 아직 걸려 있다.<br><br>들어가지 않았다. 팔만 넣어 동료 겨드랑이 아래 혈을 짚었다. 숨이 반 치 길어진다.<br>그 반 치로 동료가 몸을 틀어 빠져나왔다. 빠지자마자 틈이 닫혔다. 쾅.<br><br>빗소리가 한참 그 소리를 덮지 못했다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 내공을 실어 컨테이너를 밀어 틈을 연다.', k:'break', dc:21, cost:{ qi:26 },
      ok:`컨테이너 벽에 두 손바닥을 붙이고 발을 땅에 박았다. 내공을 손바닥으로 몰았다.<br><br>쇠가 웅 하고 운다. 한 뼘 밀렸다. 그 한 뼘에 동료가 빠져나왔다.<br>손을 떼자 컨테이너가 도로 미끄러져 와 붙는다. 빈 틈을 물었다.<br><br>손바닥에 녹이 붙었다. 손 안쪽이 뜨겁다.`,
      ng:`밀었는데 쇠가 꿈쩍 않는다. 컨테이너 안에 무언가 무거운 것이 가득 찼다.<br><br>내공만 빠졌다. 크레인이 돈다. 틈이 더 좁아진다.<br>동료 손을 잡고 당겼다. 셋이 같이 당겨 겨우 뺐다. 동료 갈비 하나가 더 나갔다. 이쪽 어깨도 빠졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 짧게 끊어 쉬는 숨을 가르쳐 버티게 한다.', k:'bond', dc:20,
      ok:`틈에 얼굴을 대고 말했다. 크게 쉬지 말라고. 갈비가 찌른다. 반만, 짧게, 자주.<br><br>박자를 세 주었다. 하나, 둘. 하나, 둘. 동료가 그 박자로 숨을 쉰다.<br>그사이 일행이 쇠지렛대를 찾아왔다. 틈이 벌어지자 동료가 반 숨을 쉬며 빠져나왔다.`,
      ng:`세 주는데 동료가 크게 들이쉰다. 겁이 나서.<br><br>갈비가 안을 찔렀다. 동료 숨이 끊긴다. 얼굴이 하얘진다.<br>지렛대가 왔을 때 동료는 정신을 놓았다. 끌어내고 한참 가슴 혈을 눌렀다. 손가락이 저렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B1', t:'수로 — 물 먹은 폐',
  x:`수로에서 동료를 건졌다. 숨을 안 쉰다. 입술이 파랗다.<br><br>
    기름 섞인 물이 코와 입에 찼다.<br>
    물 먹은 사람을 살리는 데는 순서가 있다. 물을 빼는 것보다 숨을 넣는 게 먼저다. 그리고 숨이 안 들어가면 넣는 길을 연다.<br><br>
    방파제 끝에서 배 고동이 한 번 울린다.`,
  o:[
    { l:'① 숨길 혈을 짚으며 숨을 불어 넣는다.', k:'heal', dc:21, wake:1,
      ok:`고개를 젖히고 숨을 불어 넣었다. 가슴이 반만 오른다. 막혔다.<br><br>불어 넣으며 다른 손으로 목 아래 오목한 혈을 짚었다. 위로 밀어 올리듯. 다시 불었다. 가슴이 다 오른다.<br>여섯 번째에 기름물을 토한다. 기침한다. 숨을 쉰다.<br><br>숨을 넣는 입과 길을 여는 손이 동시에 움직였다. 혈을 짚는 일이 따로가 아니라 숨을 넣는 일 속에 들어갔다. 두 손이 한 가지 일을 하게 됐다.`,
      ng:`불어 넣는데 가슴이 안 오른다. 혈을 짚을 손이 동료 고개를 받치느라 비어 있지 않다.<br><br>다른 사람에게 고개를 맡기는 사이 시간이 갔다.<br>숨은 돌아왔다. 한참 늦게. 동료가 눈을 떴는데 초점이 늦게 왔다. 이쪽 입술이 기름에 부르텄다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 거꾸로 들어 물부터 뺀다.', k:'steady', dc:20,
      ok:`허리를 안아 거꾸로 들었다. 무겁다. 등을 쳤다. 물이 쏟아진다.<br><br>그다음 눕혀 숨을 불었다. 물이 빠진 길로 숨이 들어간다.<br>세 번째에 기침이 났다. 순서가 바뀌었지만 이번엔 됐다.`,
      ng:`들어 올리다 미끄러졌다. 젖은 몸은 잡히지 않는다.<br><br>판자 위에 같이 넘어졌다. 동료 머리가 판자에 부딪쳤다.<br>다시 눕혀 숨을 불었다. 돌아왔다. 머리에 혹이 하나 더 생겼다. 이쪽 허리도 삐끗했다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B2', t:'한방 처치실 — 꽂혀 있는 침',
  x:`한방 처치실 침대에 환자 셋이 누웠다. 팔다리에 침이 꽂혔다. 가지런히.<br><br>
    셋 다 눈은 떴는데 움직이지 않는다. 손가락 하나도.<br>
    침 자리를 보면 무엇을 하려는 침인지 안다. 같은 혈도 깊이와 방향에 따라 여는 침이 되고 닫는 침이 된다.<br><br>
    이 침들은 다 닫는 쪽으로 꽂혔다. 깊게, 아래로.`,
  o:[
    { l:'① 침을 뽑고 같은 혈을 반대로 짚어 연다.', k:'heal', dc:21, wake:1,
      ok:`한 사람씩 침을 뽑았다. 꽂힌 순서의 거꾸로. 마지막에 꽂은 것부터.<br><br>뽑은 자리를 엄지로 위로 쓸어 올렸다. 닫힌 길을 같은 자리에서 반대로 연다. 손끝에서 기가 다시 돈다.<br>첫 번째 사람 손가락이 움찔한다. 두 번째 사람 눈꺼풀이 깜빡인다.<br><br>막는 자리와 여는 자리가 한 자리의 앞뒤라는 걸 손이 알았다. 혈 하나를 두 쪽에서 읽는 법이 손끝에 생겼다.`,
      ng:`뽑는 순서가 틀렸다. 가운데 것부터 뽑았다.<br><br>남은 침들이 더 깊이 문다. 환자가 숨을 몰아쉰다. 눈만 움직여 이쪽을 본다. 아프다고.<br>급히 다 뽑았다. 셋 다 축 늘어졌다. 처치실 밖에서 딸깍 소리가 다가왔다. 침에 손바닥을 찔렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 침 자리를 읽어 놓은 손의 버릇을 본다.', k:'gaze', dc:20,
      ok:`침을 건드리지 않고 각도만 봤다. 셋 다 같은 각도, 같은 깊이. 한 사람이 놓았다.<br><br>오른쪽으로 조금씩 기울었다. 놓는 손이 왼손잡이다. 그리고 셋째 사람은 한 군데가 다르다. 정수리 침이 얕다. 서둘렀다.<br>셋째는 방금 놓았다. 놓은 사람이 아직 가까이 있다.<br><br>처치실 커튼 아래로 흰 신발이 보인다. 왼발이 조금 앞에 나와 있다.`,
      ng:`보는 사이 커튼이 젖혀졌다.<br><br>흰 가운이 들어온다. 손에 침통을 들었다. 이쪽 침대를 가리킨다. 다음이라고.<br>뒷걸음질 치다 약탕기를 엎었다. 뜨거운 약이 발등에 쏟아졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 선반의 새 침통을 챙긴다.', k:'luck', dc:21,
      ok:`선반에 침통이 줄지어 있다. 하나를 열었다. 새것이다. 끝이 곱다.<br><br>침통째 품에 넣었다. 이 병동에서 침은 닫는 데 썼다. 이쪽은 여는 데 쓸 것이다.<br>같은 쇠다. 쥐는 손이 다를 뿐이다.`,
      ng:`침통을 여는데 안이 비었다. 대신 종이가 하나. 『반납 확인.』<br><br>빈 통을 든 이쪽을 커튼 너머 누가 본다. 반납하지 않은 사람을 찾는 눈이다.<br>통을 내려놓고 나왔다. 복도 모서리에 어깨를 부딪쳤다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B2', t:'병실 — 맥 없는 대답',
  x:`정각 점검이다. 간호사가 이름을 부른다. 침대마다 대답이 나온다.<br><br>
    점검이 끝나고 옆 침대 환자를 봤다. 가슴이 오르내리지 않는다.<br>
    방금 대답한 사람이다. 또렷하게. 네, 하고.<br><br>
    손목을 짚어 보면 안다. 짚지 않아도 알 것 같다.`,
  o:[
    { l:'① 손목을 잡아 맥을 짚는다.', k:'heal', dc:21,
      doom:{ title:'짚힌 손목', what:'맥 없는 손에 손목을 잡혔습니다', dc:17, sec:55,
        text:`손목을 잡았다. 차다. 맥이 없다. 아주 오래전부터 없었다.<br><br>손을 떼려는데 그 손이 돌아 이쪽 손목을 잡는다. 엄지가 정확히 맥 자리에 얹힌다.<br>이쪽 맥을 센다. 하나, 둘. 셀수록 느려진다. 저쪽이 세는 만큼 이쪽에서 빠져나간다.<br><br>다음 정각에 대답할 맥이 필요하다. 누가 엄지를 떼어 내야 한다.`,
        dieText:`의원은 누운 사람을 그냥 못 지나간다. 맥을 짚어야 한다.<br><br>그 침대는 맥이 필요했다. 대답은 할 줄 아는데 맥이 없었다.<br>다음 정각에 그 침대가 대답했다. 또렷하게. 손목에서 맥이 뛰었다. 남의 박자로.` },
      ok:`손을 뻗다 멈췄다. 손목 대신 목 옆을 봤다. 손을 대지 않고.<br><br>목 옆이 안 뛴다. 그런데 손가락은 침대 시트를 쥐었다 폈다 한다. 맥 없이 움직이는 손이다. 무엇을 기다리는 손.<br>손을 거두고 침대를 하나 건너 앉았다.<br><br>다음 정각에도 그 침대가 대답했다. 이쪽은 그 목소리를 들으며 손목을 품에 넣고 있었다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 멀리서 숨을 센다.', k:'sense', dc:20,
      ok:`침대 하나 떨어져 앉아 숨을 셌다. 가슴이 안 오른다. 대신 이불이 아주 조금 움직인다. 일정하게.<br><br>숨이 아니다. 이불 밑에서 무언가 숨 쉬는 시늉을 한다. 점검 때만 대답하고, 나머지는 시늉.<br>병실을 둘러봤다. 가슴이 오르는 침대는 이쪽 일행 다섯뿐이다.<br><br>다섯이 이 병실의 유일한 숨이다. 정각마다 그걸 세러 온다.`,
      ng:`세는 사이 그 침대 환자 눈이 떠졌다.<br><br>이쪽을 본다. 숨을 세는 걸 안다. 눈이 웃는다. 가슴은 안 움직인다.<br>그 뒤로 정각이 될 때마다 그 눈이 이쪽을 봤다. 밤새 한숨도 못 잤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B2', t:'처치실 — 진정제 맞은 동료',
  x:`처치실에서 동료를 찾았다. 진정제를 맞았다. 깨어는 있는데 고개가 무겁다.<br><br>
    다음 정각까지 깨어 걸어야 한다. 처치실에 남은 사람은 다음 점검에서 처치실 숫자가 된다.<br>
    약에 눌린 사람을 깨우는 혈이 있다. 코 밑, 손끝 열 개, 발바닥 한가운데.<br><br>
    복도 시계가 정각 십이 분 전이다.`,
  o:[
    { l:'① 인중을 누르고 손끝을 따서 깨운다.', k:'heal', dc:20,
      ok:`코 밑 인중을 엄지로 세게 눌렀다. 동료가 헉 하고 숨을 들이켠다.<br><br>처치실 바늘로 열 손가락 끝을 하나씩 땄다. 피가 한 방울씩. 따는 아픔이 약을 밀어낸다.<br>열 번째에 동료 눈이 이쪽을 찾는다. 이름을 불렀다. 맞는 이름이다.<br><br>정각 이 분 전에 처치실을 나왔다. 둘 다 걸어서.`,
      ng:`인중을 눌러도 동료가 안 깬다. 너무 깊다.<br><br>손끝을 따는데 피가 안 나온다. 약이 피까지 느리게 했다.<br>열을 다 땄을 때 정각이 됐다. 딸깍. 처치실 숫자에 둘이 세어졌다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 내공으로 발바닥 혈에서 약 기운을 밀어 올린다.', k:'steady', dc:21, cost:{ qi:24 },
      ok:`동료 신을 벗기고 발바닥 한가운데에 엄지를 박았다. 내공을 실어 위로 밀었다.<br><br>발바닥에서 무릎, 허리, 가슴, 목. 내공이 지나가며 약 기운을 밀어 올린다. 위로, 밖으로.<br>동료가 기침을 한다. 쓴 침을 뱉는다. 고개가 선다.<br><br>정각 오 분 전. 동료가 먼저 일어섰다.`,
      ng:`밀어 올리는데 약 기운이 내공을 붙든다. 무겁다.<br><br>가슴께에서 내공이 멈췄다. 약과 같이 고였다. 동료가 숨을 몰아쉰다.<br>손을 떼야 했다. 동료를 업고 나왔다. 정각 일 분 전. 다리가 풀려 복도에 무릎을 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B2', t:'당직실 — 의사 가운의 차트',
  x:`당직실 옷걸이에 흰 가운이 걸렸다. 가슴 주머니에 차트가 꽂혔다.<br><br>
    병동 환자 전부의 기록이다. 체온, 혈압, 맥박. 매시 정각.<br>
    맥 기록을 보면 그 사람이 어떻게 지냈는지 안다. 맥은 밤에 느려지고 새벽에 빨라진다. 사람이면.<br><br>
    차트를 넘겼다. 맥박 칸이 전부 같은 숫자다. 일흔둘.`,
  o:[
    { l:'① 차트를 끝까지 읽는다.', k:'gaze', dc:20,
      ok:`넘겼다. 모든 환자, 모든 정각. 일흔둘. 체온도 다 같다. 혈압도.<br><br>재지 않았다. 적기만 했다. 그런데 맨 뒷장에 다섯 줄만 숫자가 다르다. 아흔, 백, 여든여섯. 오늘 밤 생긴 다섯 이름.<br>이 병동에서 맥이 다른 건 다섯뿐이다. 그 다섯 칸 옆에 볼펜으로 작은 표시가 있다. 『조정 예정.』<br><br>차트를 도로 꽂았다. 일흔둘이 되면 이 병동 사람이 되는 것이다.`,
      ng:`넘기는데 차트 사이에서 종이가 떨어졌다.<br><br>주우려 엎드리자 옷걸이의 가운이 흔들린다. 바람도 없는데. 가운 소매가 이쪽 어깨에 얹힌다.<br>소매 속이 비었다. 그래도 무겁다. 빠져나오는 데 한참 걸렸다. 어깨가 오래 시렸다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 가운을 걸치고 복도를 지나간다.', k:'hide', dc:21,
      ok:`가운을 걸쳤다. 차트를 손에 들었다. 의사처럼 걷는 법은 안다. 서두르지 않고, 차트를 보면서.<br><br>복도에서 간호사와 마주쳤다. 간호사가 고개를 숙인다. 차트를 내민다. 서명하라고.<br>서명란 옆 맥박 칸에 일흔둘이라고 적고 서명했다. 간호사가 다시 고개를 숙였다.<br><br>복도 끝 비상문 앞까지 아무도 막지 않았다.`,
      ng:`걸치고 나가자 간호사가 다가온다. 맥을 짚어 달라고 손목을 내민다.<br><br>짚었다. 맥이 없다. 무엇이라고 적어야 할지 몰라 머뭇거렸다.<br>간호사가 손목을 거둔다. 머뭇거린 의사는 이 병동 의사가 아니다. 계수기가 딸깍했다. 가운을 벗어 던지고 뛰었다. 계단에서 발을 헛디뎠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 덜컹 박자의 맥',
  x:`9호차 승객 열한 명이 잔다. 고개가 전부 창 쪽이다.<br><br>
    열차가 덜컹거린다. 덜컹, 덜컹. 일정하게.<br>
    잠든 사람 손목을 짚었다. 버릇이다. 맥이 덜컹 박자와 똑같다. 옆 사람도, 그 옆 사람도.<br><br>
    제 손목을 짚었다. 제 맥도 그쪽으로 끌려가고 있다.`,
  o:[
    { l:'① 숨을 덜컹 박자에서 어긋나게 쉰다.', k:'steady', dc:21, wake:1,
      ok:`덜컹, 하는 사이에 들이쉬고 덜컹 소리에 참았다. 박자의 틈에 숨을 끼웠다.<br><br>맥이 열차에서 떨어진다. 제 박자로 돌아온다. 일행 넷 손목을 짚고 하나씩 같은 숨을 가르쳤다.<br>다섯 맥이 열차와 어긋났다. 졸음이 걷힌다.<br><br>남의 박자에 끌려가는 맥을 제 숨으로 떼어 냈다. 맥을 듣기만 하던 귀가 맥을 붙들기 시작했다. 박자를 고르는 손이 제 몸 안에도 생겼다.`,
      ng:`어긋나게 쉬려는데 덜컹 소리가 바뀐다. 이쪽 숨에 맞춰서.<br><br>틈을 찾을수록 틈이 이쪽을 따라온다. 맥이 다시 끌려간다. 눈꺼풀이 무겁다.<br>일행이 뺨을 쳐서 깨웠다. 깨어 보니 고개가 창 쪽으로 기울어 있었다. 목이 굳어 오래 아팠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 일행 손목 혈을 하나씩 튕겨 깨운다.', k:'heal', dc:20,
      ok:`일행 넷 손목 안쪽을 엄지손톱으로 탁 튕겼다. 하나씩.<br><br>튕길 때마다 맥이 한 번 튄다. 열차 박자에서 미끄러진다. 넷 다 눈을 번쩍 뜬다. 언제 졸았는지 모른다고.<br>9호차를 서둘러 빠져나왔다. 뒤에서 열한 명의 맥이 덜컹 소리를 냈다.`,
      ng:`튕기는데 손이 무겁다. 이쪽도 이미 끌려갔다.<br><br>둘을 깨우고 셋째에서 손이 멈췄다. 깨어난 둘이 이쪽을 흔들었다.<br>다섯이 깨어났을 때 열차는 역 하나를 지나 있었다. 시간이 그만큼 갔다. 목덜미가 식은땀에 젖었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'특실 — 바꿀 수 없는 맥',
  x:`특실 복도에서 일행이 흩어졌다 모였다. 다섯이다.<br><br>
    얼굴은 다 맞다. 목소리도 맞다. 그런데 열차에 얼굴을 바꾸는 것이 타고 있다.<br>
    오늘 다섯 맥을 수십 번 짚었다. 맥은 얼굴보다 사람을 잘 말한다. 빠르기, 굵기, 건너뛰는 버릇.<br><br>
    얼굴은 베낄 수 있다. 맥은 어떨까.`,
  o:[
    { l:'① 다친 데를 본다며 다섯 손목을 차례로 짚는다.', k:'gaze', dc:20, wake:1,
      ok:`하나씩 손목을 짚었다. 하나는 일흔여덟에 넷째 박자가 약하다. 맞다. 하나는 빠르고 가늘다. 맞다.<br><br>넷째 사람. 맥이 고르다. 너무 고르다. 겁먹은 열차 안에서 일흔둘에 딱 맞춰 뛴다. 오늘 짚은 그 사람 맥은 늘 다섯째 박자에서 한 번 건너뛰었다.<br>얼굴과 목소리는 베꼈다. 버릇은 못 베꼈다.<br><br>손목을 놓고 웃어 주었다. 다음 칸 문을 열 때 그 사람을 맨 뒤에 세웠다. 맥 하나하나가 이름처럼 손끝에 남았다. 손가락이 사람을 알아보기 시작했다.`,
      ng:`넷째 손목을 짚는 순간 그 사람이 이쪽 손목을 거꾸로 짚는다.<br><br>엄지가 맥 자리에 얹힌다. 이쪽 맥을 센다. 다섯째 박자에서 일부러 한 번 건너뛴다. 이쪽이 아는 그 버릇으로.<br>배웠다. 지금. 손을 빼려다 손목이 비틀렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 내공을 흘려 넣어 받는 몸을 본다.', k:'sense', dc:21, cost:{ qi:22 },
      ok:`어깨를 두드리며 내공을 아주 조금씩 흘려 넣었다. 다섯에게.<br><br>사람 몸은 남의 내공을 받으면 따뜻해진다. 넷은 그렇다. 하나는 차가워진다. 내공을 먹는다.<br>그 사람이 웃는다. 고맙다고. 더 달라는 눈이다.<br><br>그 뒤로 그 사람에게는 손을 대지 않았다. 문을 지날 때 그 사람만 문 너머에 남았다.`,
      ng:`흘려 넣는 순간 그 사람이 내공을 빨아들인다.<br><br>손바닥이 어깨에 붙었다. 내공이 줄줄 빠져나간다. 떼어 내는 데 셋이 붙었다.<br>떼고 나서 손바닥이 하얗게 식었다. 그 사람은 혈색이 좋아졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, mind:-16 } },
    { l:'③ 맥 이야기를 꺼내 넌지시 떠본다.', k:'bond', dc:19,
      ok:`쉬는 척 말을 꺼냈다. 아까 짚었을 때 누가 맥이 건너뛰더라고. 괜찮냐고.<br><br>진짜인 사람은 고개를 갸웃한다. 자기 맥을 모르니까. 넷째 사람만 바로 대답한다. 자기라고. 괜찮다고.<br>자기 맥이 건너뛰는 걸 아는 사람은 없다. 짚어 본 사람만 안다.<br><br>그 대답 하나로 충분했다.`,
      ng:`말을 꺼내자 다섯이 다 이쪽을 본다.<br><br>넷째 사람이 웃는다. 그럼 의원 맥은 어떠냐고. 짚어 보자며 손을 뻗는다.<br>손을 빼다 복도 벽에 팔꿈치를 찧었다. 의심한 걸 들켰다. 그 뒤로 그것도 이쪽을 지켜봤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'식당칸 — 목에 걸린 것',
  x:`식당칸을 지나는데 승객 하나가 목을 움켜쥐고 일어선다.<br><br>
    소리가 안 난다. 얼굴이 붉어지다 보라색이 된다. 식탁 위 접시가 흩어진다.<br>
    목에 걸린 사람은 소리로 가린다. 기침을 하면 아직 숨이 있다. 소리가 없으면 숨길이 막혔다.<br><br>
    다른 승객들은 고개도 안 든다. 계속 먹는다.`,
  o:[
    { l:'① 뒤에서 안아 명치 아래를 밀어 올린다.', k:'heal', dc:20,
      ok:`뒤로 돌아가 안았다. 주먹을 명치 아래에 대고 다른 손으로 감싸 위로 밀어 올렸다. 세게.<br><br>한 번, 두 번. 세 번째에 무언가 튀어나와 식탁에 떨어진다. 고기 조각이 아니다. 동전이다. 오래된.<br>승객이 숨을 몰아쉰다. 이쪽을 본다. 고맙다는 얼굴이 아니다. 놀란 얼굴이다.<br><br>다른 승객들이 처음으로 고개를 든다. 이쪽을 본다. 계속 먹으며.`,
      ng:`밀어 올리는데 승객이 몸을 비튼다. 놓으라고 손톱으로 할퀸다.<br><br>놓쳤다. 승객이 바닥에 쓰러진다. 다른 승객들은 여전히 먹는다.<br>엎드린 채 등을 내리쳐 겨우 뱉게 했다. 이쪽 팔뚝에 손톱자국이 넷 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 혈을 짚어 기침을 억지로 터뜨린다.', k:'fix', dc:21,
      ok:`목 아래 오목한 혈을 손가락으로 깊게 찔렀다. 안쪽으로, 아래로.<br><br>몸이 놀라 기침을 터뜨린다. 막힌 숨이 기침에 밀려 나온다. 걸린 것도 같이 나온다. 작은 열쇠다.<br>승객이 숨을 쉰다. 열쇠를 이쪽 손에 쥐여 준다. 아무 말 없이 다시 앉아 먹는다.<br><br>열쇠에 번호가 있다. 특실 번호다.`,
      ng:`찔렀는데 기침이 안 터진다. 막힌 게 너무 깊다.<br><br>두 번, 세 번. 승객 눈이 뒤집힌다. 급히 뒤에서 안아 밀어 올렸다. 겨우 나왔다.<br>승객 목에 이쪽 손가락 자국이 시퍼렇게 남았다. 다른 승객들이 그 자국을 오래 봤다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B3', t:'기관실 앞 — 쓰러진 화부',
  x:`탄수차 끝, 기관실 문 앞에 화부가 쓰러져 있다. 석탄 삽을 쥔 채.<br><br>
    얼굴이 붉고 땀이 없다. 보일러 열에 오래 서 있었다.<br>
    땀이 멈춘 열은 위험하다. 몸이 식히기를 포기한 것이다. 빨리 빼지 않으면 머리가 익는다.<br><br>
    그런데 이 열차에서 쓰러진 사람이 사람인지는 모른다.`,
  o:[
    { l:'① 열 손가락 끝을 따서 열을 뺀다.', k:'heal', dc:20,
      ok:`화부를 문에서 떨어뜨려 탄수차 물탱크 옆으로 끌었다. 바늘로 열 손가락 끝을 땄다.<br><br>검붉은 피가 한 방울씩. 짜낼 때마다 얼굴 붉은 기가 한 겹씩 내려간다. 젖은 천을 목과 겨드랑이에 댔다.<br>화부가 눈을 뜬다. 땀이 다시 난다. 사람이다.<br><br>화부가 갈라진 목소리로 말한다. 기관실 문 열쇠는 압력계 뒤에 있다고.`,
      ng:`따는데 피가 안 나온다. 너무 진하게 끓었다.<br><br>짜내는 사이 보일러가 한 번 울었다. 증기가 문틈에서 뿜는다. 이쪽 팔에 닿았다.<br>팔이 익었다. 화부는 반쯤만 깨어났다. 둘이 같이 물탱크에 기대 앉았다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 손목을 짚어 사람인지부터 본다.', k:'gaze', dc:21,
      doom:{ title:'화부의 손목', what:'화실 쪽으로 밀려납니다', dc:17, sec:50,
        text:`화부 손목을 짚었다. 뜨겁다. 맥이 뛴다. 아주 빠르게. 사람 맥보다 빠르게. 보일러 박자로.<br><br>손을 떼려는데 화부 손이 이쪽 손목을 쥔다. 삽 쥐던 손아귀로.<br>화부가 일어선다. 이쪽을 앞세우고 기관실 문을 연다. 화실 문이 열려 있다. 붉다. 열이 얼굴을 친다.<br><br>삽질하듯 밀린다. 한 걸음씩. 누가 저 손아귀를 떼어 내야 한다.`,
        dieText:`의원은 쓰러진 사람의 손목부터 짚는다.<br><br>그 화부는 매번 그 자리에 쓰러져 있었다. 짚어 줄 사람을 기다리며.<br>열차는 그날 밤 조금 더 빨리 달렸다. 압력계 바늘이 한 칸 올라가 있었다.` },
      ok:`손목을 짚으려다 멈췄다. 손목 대신 쥔 삽을 봤다.<br><br>삽자루가 손에 녹아 붙었다. 사람 손이 그렇게 될 때까지 쥐고 있으면 사람이 아니다.<br>화부를 건너뛰어 지나갔다. 압력계 뒤에서 열쇠를 찾았다.<br><br>뒤에서 삽 긁는 소리가 났다. 일어난 것이다. 문을 열고 뛰었다.`,
      win:{ exp:18, dream:3 } }
  ] }

]);

// ── 수도사 (monk) · 무력 ──
kJob('monk', 'B', [

{ at:'B', t:'추격 — 업고 뛴다',
  x:`동료가 다리를 다쳤다. 걷지 못한다. 뒤에서 발소리가 다가온다.<br><br>
    서두르지 않는 발소리다. 쫓는 쪽은 이쪽이 지칠 걸 안다.<br>
    수도사는 무거운 것을 지고 먼 길을 가는 법을 안다. 물동이를 지고 산을 오르내리며 배웠다. 숨과 걸음을 맞추는 법.<br><br>
    사람은 물동이보다 무겁다. 그리고 겁을 먹으면 더 무거워진다.`,
  o:[
    { l:'① 힘을 끌어올려 업고 끝까지 뛴다.', k:'steady', dc:20, cost:{ might:26 }, wake:1,
      ok:`등에 업고 허리띠로 묶었다. 뛰었다. 숨 둘에 걸음 넷. 숨이 흐트러지면 걸음도 흐트러진다.<br><br>등의 사람이 미안하다고 한다. 대답하지 않았다. 대답하면 숨이 샌다.<br>계단 둘, 복도 셋. 발소리가 멀어졌다. 쫓는 쪽이 먼저 지쳤다.<br><br>내려놓고 나서 알았다. 등이 그 사람 무게를 기억한다. 다음에 업으면 처음부터 맞는 자리에 얹을 것이다. 짐을 지는 몸이 사람을 지는 몸으로 바뀌었다.`,
      ng:`반쯤 뛰다 무릎이 꺾였다. 둘이 같이 넘어졌다.<br><br>다친 다리가 바닥에 부딪쳤다. 등의 사람이 비명을 지른다.<br>발소리가 빨라진다. 다른 동료가 거들어 둘이 같이 끌었다. 이쪽 무릎이 깨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 둘이 팔을 엮어 가마를 만들어 나른다.', k:'bond', dc:19,
      ok:`다른 동료와 서로 손목을 엮었다. 네 손으로 자리를 만들었다. 다친 사람을 앉혔다.<br><br>혼자 업는 것보다 느리다. 대신 둘 다 덜 지친다. 숨을 맞췄다. 하나, 둘.<br>모퉁이를 돌 때마다 말없이 같이 돌았다.<br><br>혼자 지는 게 늘 옳은 건 아니다. 나눠 지면 더 멀리 간다.`,
      ng:`엮은 손이 엇박자로 움직였다. 다친 사람이 기운다.<br><br>떨어질 뻔한 걸 붙잡느라 멈췄다. 멈춘 사이 발소리가 모퉁이를 돌았다.<br>빛이 등에 닿았다. 셋이 같이 굴러 숨었다. 손목이 꺾였다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'잠긴 문 — 어깨',
  x:`문이 잠겼다. 쇠문은 아니다. 두꺼운 나무다.<br><br>
    등 뒤 복도 끝에서 발소리가 다가온다. 열쇠를 찾을 시간은 없다.<br>
    장작은 많이 패 봤다. 나무는 결을 따라 쪼개진다. 문짝도 나무다.<br><br>
    문짝 가운데 판자에 결이 세로로 났다.`,
  o:[
    { l:'① 힘을 모아 결 따라 판자를 친다.', k:'break', dc:20, cost:{ might:24 },
      ok:`어깨가 아니라 손바닥 뿌리로 쳤다. 결 한가운데. 도끼 떨어지는 자리.<br><br>판자가 쩍 소리를 내며 세로로 갈라진다. 한 번 더. 손이 들어갈 틈이 났다.<br>틈으로 손을 넣어 안쪽 빗장을 들었다.<br><br>문이 열렸다. 판자 한 장만 상했다. 손바닥이 얼얼하다.`,
      ng:`쳤는데 결이 아니라 옹이를 쳤다.<br><br>판자가 버틴다. 손바닥 뼈가 울린다. 소리만 크게 났다.<br>발소리가 뛰기 시작했다. 다시 쳤다. 세 번째에 겨우 갈라졌다. 손바닥이 찢어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 경첩 쪽 틈을 본다.', k:'gaze', dc:21,
      ok:`잠긴 쪽 말고 경첩 쪽을 봤다. 오래된 문이다. 경첩 나사가 나무에서 헐거워졌다.<br><br>문짝을 경첩 쪽에서 들어 올리듯 당겼다. 나사가 나무에서 빠진다. 하나, 둘.<br>잠긴 채로 문이 반대쪽으로 열렸다.<br><br>잠근 사람은 잠긴 쪽만 지킨다.`,
      ng:`보는 사이 발소리가 복도 중간에 왔다.<br><br>경첩 나사가 단단하다. 헐거운 게 아니었다.<br>결국 어깨로 들이받았다. 두 번. 문 대신 어깨가 먼저 탈이 났다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'배신 — 등 뒤의 칼',
  x:`같이 도망치던 사람이 있다. 오늘 밤 처음 만났다. 길을 잘 안다.<br><br>
    좁은 통로에서 그 사람이 맨 뒤로 빠졌다. 맨 앞 동료 등 뒤에 붙었다.<br>
    사람의 어깨를 보면 손이 무엇을 쥐었는지 안다. 빈손은 어깨가 풀려 있다.<br><br>
    그 사람 오른쪽 어깨가 굳었다. 소매 안이 무겁다.`,
  o:[
    { l:'① 동료와 그 사람 사이에 몸을 넣는다.', k:'steady', dc:21,
      doom:{ title:'막아선 등', what:'칼에 찔려 쓰러졌습니다', dc:17, sec:55,
        text:`둘 사이로 몸을 밀어 넣었다. 그 순간 소매가 움직였다.<br><br>칼이 들어왔다. 옆구리로. 차갑다가 뜨겁다. 동료 대신.<br>그 사람이 칼을 뺀다. 놀라지 않는다. 누구든 하나면 됐다는 얼굴이다.<br><br>무릎이 꺾인다. 피가 손가락 사이로 샌다. 누가 상처를 눌러 주어야 한다. 지금.`,
        dieText:`수도사는 남의 앞을 막는 사람이다.<br><br>칼은 누구 등인지 묻지 않는다. 그 사람도 묻지 않았다.<br>동료는 살았다. 통로 바닥에 염주 알이 몇 개 흩어져 있었다. 끈이 끊겨서.` },
      ok:`둘 사이로 몸을 밀어 넣으며 그 사람 오른쪽 팔꿈치를 손바닥으로 덮었다. 막는 게 먼저가 아니라 누르는 게 먼저다.<br><br>소매 속 칼이 나오다 멈췄다. 팔꿈치가 펴지지 않으면 칼은 못 찌른다.<br>그 사람과 눈이 마주쳤다. 아무 말도 하지 않았다. 그 사람도.<br><br>그 사람이 팔을 빼 통로 반대쪽으로 사라졌다. 칼은 끝내 소매 밖으로 나오지 않았다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 힘을 실어 소매 쥔 손목을 꺾는다.', k:'break', dc:20, cost:{ might:22 },
      ok:`뒤에서 그 사람 손목을 잡아 비틀었다. 소매에서 칼이 떨어진다. 바닥에서 쨍 운다.<br><br>그 사람이 돌아본다. 놀란 얼굴이 아니다. 들킨 얼굴이다.<br>칼을 발로 밟고 손목을 놓았다. 가라고 했다. 그 사람이 갔다.<br><br>살생은 하지 않는다. 칼은 챙겼다. 쓰지 않을 칼이다.`,
      ng:`꺾는데 그 사람이 먼저 몸을 돌린다. 칼끝이 이쪽 팔뚝을 긋는다.<br><br>피가 튄다. 동료들이 소리를 지른다. 그 사람은 어둠으로 뛰어갔다.<br>팔뚝을 묶었다. 깊다. 그 사람이 간 쪽에서 다른 발소리들이 모여들었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B', t:'비 — 밤 기도',
  x:`다들 잠깐 눈을 붙였다. 혼자 일어나 앉았다.<br><br>
    두 손을 모은다. 하루 끝의 기도다. 오늘 다친 사람 이름을 하나씩 부른다.<br>
    창에 빗줄기가 긋는다. 창밖 네온이 빗물에 번진다.<br><br>
    셋째 이름을 부를 때 창밖에서 누가 같은 이름을 부른다. 한 박자 늦게.`,
  o:[
    { l:'① 멈추지 않고 기도를 끝까지 마친다.', k:'steady', dc:20,
      ok:`멈추지 않았다. 넷째, 다섯째. 창밖 소리가 따라온다. 늘 한 박자 늦게.<br><br>마지막 이름 뒤에 한 줄을 더 붙였다. 창밖의 그것을 위한 줄. 이름을 몰라서 이름 없이.<br>창밖 소리가 그 줄은 따라 하지 않았다. 따라 할 이름이 없으니까.<br><br>조용해졌다. 빗소리만 남았다.`,
      ng:`셋째 이름에서 목소리가 떨렸다.<br><br>창밖 소리가 떨림까지 따라 한다. 넷째 이름이 생각나지 않는다. 창밖 소리가 대신 부른다. 맞는 이름을.<br>그 이름의 동료가 잠결에 대답했다. 네. 깨워서 입을 막았다. 밤새 둘 다 창을 등지고 앉아 있었다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-14, spirit:-18 } },
    { l:'② 기도를 접고 잠든 이들 상처를 씻긴다.', k:'heal', dc:19,
      ok:`기도를 접었다. 물을 조금 데웠다. 잠든 사람들 상처를 하나씩 씻겼다. 깨지 않게.<br><br>창밖 소리는 부를 이름이 없어 멈췄다. 손으로 하는 기도는 소리가 없다.<br>다섯째 상처를 묶었을 때 창밖이 조용했다. 빗물만 흘렀다.`,
      ng:`씻기다 한 사람이 깼다. 놀라 팔을 휘둘렀다.<br><br>물그릇이 엎어졌다. 소리가 났다. 창밖 소리가 멈추고 창에 손바닥이 붙는다. 바깥에서.<br>손바닥이 오래 붙어 있었다. 빗물이 그 손바닥만 피해 흘렀다.`,
      win:{ exp:15, hp:8 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'시계 — 숨을 센다',
  x:`시계가 없다. 순찰은 일정하게 돈다. 그 간격을 알아야 한다.<br><br>
    시계 없이 사는 데서 왔다. 새벽 종을 치기 전에 일어난다. 숨으로 시간을 잰다.<br>
    고요한 숨은 한 번에 열을 센다. 일 분에 여섯 번.<br><br>
    지금 숨은 고요하지 않다. 오늘 많이 뛰었다.`,
  o:[
    { l:'① 숨을 고요히 앉히고 숨으로 센다.', k:'steady', dc:20, wake:1,
      ok:`벽에 등을 대고 앉았다. 숨을 하나씩 내려놓았다. 가쁜 숨, 놀란 숨, 지친 숨. 하나씩.<br><br>숨이 고요해지자 셌다. 발소리에서 발소리까지. 숨 백이십. 이십 분. 다음에도 백이십. 다음엔 백.<br>백의 반에 문을 열었다. 복도가 비어 있었다.<br><br>쫓기는 몸 안에서도 고요한 숨 하나를 꺼낼 수 있게 됐다. 앉는 자리가 바닥이 아니라 몸 안으로 들어왔다.`,
      ng:`숨을 앉히려는데 문밖 소리에 숨이 다시 튄다.<br><br>앉히고, 튀고, 다시 앉히고. 세는 숫자가 매번 달라진다.<br>틀린 숫자로 문을 열었다. 복도 끝에서 발소리가 멈췄다. 문을 닫다 손가락을 찧었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 염주 알을 굴리며 센다.', k:'fix', dc:19,
      ok:`염주를 꺼냈다. 알 하나에 숨 하나. 백여덟 알을 한 바퀴 돌리면 대략 한 순찰이다.<br><br>손가락이 셈을 맡으니 머리가 쉰다. 쉬는 머리가 발소리를 더 잘 듣는다.<br>두 바퀴째 끝에서 문을 열었다. 맞았다.`,
      ng:`굴리다 끈이 끊어졌다. 오늘 하도 당겨서.<br><br>알이 바닥에 흩어진다. 또르르. 이 방에서 그 소리는 크다.<br>문밖 발소리가 멈췄다. 엎드려 알을 주웠다. 다 못 주웠다. 무릎이 저려 오래 일어나지 못했다.`,
      win:{ exp:15, dream:2, mind:6 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B', t:'쓰러진 사람 — 시간이 없다',
  x:`통로 벽에 낯선 사람이 기대 있다. 다른 일행이었다. 혼자 남았다.<br><br>
    숨을 보면 얼마 남았는지 안다. 많이 안 남았다. 업고 가면 이쪽 일행이 늦는다.<br>
    그 사람이 손을 든다. 잡아 달라는 것 같다.<br><br>
    등 뒤 어딘가에서 시계 소리가 난다. 째깍, 째깍.`,
  o:[
    { l:'① 손을 잡고 마지막까지 곁에 있는다.', k:'bond', dc:20,
      ok:`일행에게 먼저 가라고 했다. 금방 따라가겠다고. 앉아서 손을 잡았다.<br><br>그 사람이 이름을 말한다. 따라 불러 주었다. 숨이 길어졌다가 멎었다.<br>눈을 감기고 일어났다. 시계 소리가 그새 가까워졌다. 뛰었다.<br><br>일행을 따라잡았을 때 숨이 끊어질 것 같았다. 손에는 아직 그 사람 손의 온기가 있었다.`,
      ng:`손을 잡는데 그 사람이 꽉 쥔다. 놓지 않는다. 숨이 멎은 뒤에도.<br><br>손가락을 하나씩 펴는 데 오래 걸렸다. 시계 소리가 바로 뒤에서 났다.<br>뛰었다. 펴지 못한 새끼손가락 하나가 이쪽 소매를 붙들고 따라오는 것 같았다.`,
      win:{ exp:16, dream:3, spirit:6 }, lose:{ mind:-14, spirit:-16 } },
    { l:'② 힘을 끌어 업고 같이 간다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`업었다. 가볍다. 너무 가볍다. 오래 굶었다.<br><br>일행 뒤를 따라 뛰었다. 등의 사람이 한 번 웃는다. 업혀 보는 게 얼마 만이냐고.<br>숨은 자리에 내려놓았을 때 그 사람은 잠들어 있었다. 숨은 얕지만 있다.<br><br>살렸다고는 못 한다. 혼자 두지 않았다. 그건 했다.`,
      ng:`업고 뛰는데 그 사람이 등에서 미끄러진다.<br><br>추스르는 사이 일행이 멀어졌다. 시계 소리가 가까워졌다.<br>내려놓을 수도 업을 수도 없었다. 결국 끌다시피 갔다. 둘 다 계단에서 굴렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 물 한 모금을 먹이고 떠난다.', k:'heal', dc:19,
      ok:`수통을 열어 입술을 적셔 주었다. 한 모금 넘긴다.<br><br>그 사람이 고개를 끄덕인다. 가라고. 손짓으로 통로 한쪽을 가리킨다. 그쪽으로 가지 말라는 손짓이다.<br>그 손짓을 따라 반대쪽으로 갔다. 나중에 알았다. 그쪽이 막혀 있었다.<br><br>물 한 모금이 길을 하나 돌려주었다.`,
      ng:`먹이는데 그 사람이 사레가 들렸다. 기침을 한다.<br><br>기침 소리에 시계 소리가 빨라진다. 떠나야 했다. 기침하는 사람을 두고.<br>멀리 가서도 그 기침이 들렸다. 그러다 멎었다. 그게 더 오래 귀에 남았다.`,
      win:{ exp:15, dream:2, hp:6 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'숨은 자리 — 움직이지 않는다',
  x:`숨을 곳이 없었다. 기둥 그림자에 앉았다. 그대로.<br><br>
    무언가 다가와 바로 옆에 선다. 손을 뻗으면 닿는 거리다. 그것도 움직이지 않는다. 기다린다. 움직이는 것을.<br>
    오래 앉아 있는 법은 몸에 있다. 다리가 저려도, 벌레가 기어도.<br><br>
    옆의 동료 손이 떨린다.`,
  o:[
    { l:'① 숨까지 고요히 하고 바위처럼 앉는다.', k:'steady', dc:21, wake:1,
      ok:`눈을 반쯤 감았다. 숨을 아주 가늘게. 들이쉬는지 내쉬는지 저도 모를 만큼.<br><br>그것이 고개를 숙인다. 이쪽 얼굴 앞으로. 숨결이 닿는다. 차다. 눈을 뜨지 않았다. 아무것도 하지 않았다.<br>한참 뒤 그것이 물러났다. 움직이지 않는 것은 그것에게 돌로 보인다.<br><br>무서움 앞에서 앉아 있는 것. 그게 피하는 것보다 어렵다는 걸 알았다. 그리고 할 수 있다는 것도. 고요가 숨는 법이 됐다.`,
      ng:`가늘게 쉬던 숨이 마지막에 걸렸다. 작은 소리 하나.<br><br>그것이 멈춘다. 고개를 돌린다. 이쪽으로.<br>눈을 떴다. 눈이 마주쳤다. 그 뒤는 뛰었다. 기둥에 이마를 부딪쳤다. 그것이 뒤에서 아주 천천히 따라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 떨리는 동료 손을 덮어 누른다.', k:'bond', dc:20,
      ok:`동료 손 위에 손바닥을 덮었다. 무겁게. 떨림이 이쪽 손으로 넘어온다. 이쪽 손은 떨지 않는다.<br><br>떨림이 멎었다. 동료가 숨을 고른다.<br>그것이 둘 앞에 오래 섰다가 지나갔다. 손을 떼자 동료가 이쪽 손을 다시 잡았다.`,
      ng:`덮는 순간 동료가 놀라 손을 뺀다.<br><br>옷자락이 스친다. 사각. 그것이 동료 쪽으로 고개를 돌린다.<br>동료를 끌어안고 기둥 뒤로 굴렀다. 그것의 손이 방금 앉은 자리를 쓸었다. 이쪽 발목을 스쳤다. 발목이 얼음처럼 식었다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'마지막 쉼 — 피 묻은 손',
  x:`마지막 문 앞에서 쉬었다. 제 손을 봤다.<br><br>
    피가 말라붙었다. 제 피가 아니다. 오늘 업고 끌고 막아 준 사람들 것이다.<br>
    물이 귀하다. 문 너머에서 무엇을 만날지 모른다.<br><br>
    다들 지쳐 졸고 있다. 누군가 지켜야 한다.`,
  o:[
    { l:'① 물 한 줌으로 손을 씻고 이름을 부른다.', k:'heal', dc:19,
      ok:`손바닥에 물을 한 줌만 붓고 천천히 비볐다. 손가락 하나하나, 손톱 밑까지.<br><br>씻으면서 그 사람들 이름을 불렀다. 작게. 피가 한 겹씩 풀린다.<br>씻은 손이 가볍다. 다음 사람을 만질 손이다.`,
      ng:`비비는데 피가 안 지워진다. 문지를수록 번진다. 손금마다 붉다.<br><br>그만두었다. 물만 썼다.<br>무거운 손으로 문 앞에 섰다. 문고리를 잡는 손이 미끄러졌다.`,
      win:{ exp:15, mind:8 }, lose:{ mind:-14, spirit:-16 } },
    { l:'② 등을 세우고 끝까지 지킨다.', k:'steady', dc:20, wake:1,
      ok:`등을 세우고 앉았다. 숨을 셌다. 천까지 세고 다시 하나부터.<br><br>문 너머에서 무언가 몇 번 다가왔다. 문틈 아래 그림자가 멈췄다. 앉은 사람이 깨어 있는 걸 보고 물러났다.<br>졸던 동료들이 깼다. 다들 조금씩 덜 지쳤다.<br><br>지친 몸으로 앉아 지키는 일. 오늘은 그것이 몸을 닦았다. 어디서든 앉으면 그 자리가 지킬 자리가 된다는 걸 알았다.`,
      ng:`세다가 숫자를 놓쳤다. 눈꺼풀이 내려왔다.<br><br>눈을 떠 보니 문틈 아래 그림자가 바로 앞이다. 손가락이 문틈으로 들어와 있다.<br>소리를 지르자 물러났다. 다들 놀라 깼다. 아무도 다시 못 잤다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 동료들 상처를 다시 묶어 준다.', k:'heal', dc:20,
      ok:`잠든 동료들 붕대를 하나씩 봤다. 풀린 것은 다시 감고 덧난 데는 씻었다.<br><br>아무도 깨지 않았다. 다섯째를 마치니 문 너머가 조용하다.<br>다들 일어나 상처가 덜 아프다고 했다. 왜인지는 몰랐다.`,
      ng:`묶다가 등잔이 꺼졌다.<br><br>어둠 속에서 엉뚱한 데를 감았다. 한 사람이 깨어 비명을 질렀다.<br>문 너머에서 무언가 그 소리에 반응했다. 문이 한 번 덜컹했다.`,
      win:{ exp:16, hp:8 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 소금 자루에 깔린 사람',
  x:`팔레트가 무너졌다. 소금 자루 더미 밑에 동료가 깔렸다. 다리부터 허리까지.<br><br>
    자루 하나가 이십 킬로다. 열 개쯤 얹혔다.<br>
    무거운 것은 허리가 아니라 땅으로 든다.<br><br>
    셔터 밖에서 사슬 소리가 난다. 누가 들어오려 한다.`,
  o:[
    { l:'① 힘을 모아 팔레트째 들어 올린다.', k:'break', dc:21, cost:{ might:28 }, wake:1,
      ok:`팔레트 모서리 밑에 어깨를 넣고 발을 바닥에 박았다. 숨을 한 번 내쉬고 땅을 밀었다.<br><br>팔레트가 한 뼘 뜬다. 소금 자루 열 개가 같이 뜬다. 그 한 뼘으로 동료를 끌어냈다.<br>내려놓고 주저앉았다. 어깨가 떨린다. 떨리면서 숨을 골랐다.<br><br>버티는 힘과 드는 힘은 같은 데서 나온다. 땅에서. 오늘 처음으로 그 길을 몸이 끝까지 다 썼다.`,
      ng:`드는데 팔레트가 비틀린다. 자루 하나가 미끄러져 이쪽 등으로 떨어졌다.<br><br>무릎이 바닥에 박혔다. 내려놓을 수밖에 없었다.<br>자루를 하나씩 덜어 내는 사이 사슬 소리가 멎었다. 셔터가 올라가기 시작한다. 등이 끊어질 듯했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 위에서부터 자루를 하나씩 덜어 낸다.', k:'fix', dc:20,
      ok:`맨 위 자루부터 내렸다. 하나씩, 소리 안 나게 내려놓았다. 던지면 쿵 한다.<br><br>여섯을 덜자 동료가 숨을 크게 쉰다. 여덟을 덜자 다리를 뺐다.<br>셔터 사슬 소리가 다시 났을 때는 다 같이 상자 뒤에 있었다.`,
      ng:`셋째 자루를 내리는데 더미가 기울었다. 나머지가 한꺼번에 쏟아진다.<br><br>동료 위로. 더 깊이 깔렸다. 다 같이 달려들어 파냈다.<br>파내는 소리가 컸다. 셔터가 반쯤 올라왔다. 그 밑으로 고무장화가 보였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 벽을 보고 앉은 사람',
  x:`창고 구석에 사람이 벽을 보고 앉았다. 다리를 포개고 손을 무릎에 얹었다.<br><br>
    수도사는 그 자세를 안다. 벽을 보고 앉는 수련이다. 몇 해씩 하는 사람도 있다.<br>
    그런데 숨이 다르다. 고요한 숨이 아니다. 무언가를 기다리며 참는 숨이다.<br><br>
    등에 분필로 숫자가 적혔다. 3.`,
  o:[
    { l:'① 옆에 같은 자세로 앉아 같이 벽을 본다.', k:'steady', dc:20, wake:1,
      ok:`옆에 앉았다. 같은 자세. 벽을 봤다. 숨을 맞췄다.<br><br>한참 지나 그 사람이 입을 연다. 벽을 보고 있으면 안 센다고. 얼굴을 안 보이면 숫자에 안 들어간다고. 셋은 이미 세어졌고 나머지는 벽을 봐서 살았다고.<br>그리고 말한다. 다섯 시가 되면 벽이 열린다고. 벽을 보고 있던 사람만 그 문을 안다고.<br><br>앉아서 배운 것이 처음으로 길을 알려 주었다. 벽을 보는 눈이 벽 너머를 듣는 귀가 됐다.`,
      ng:`앉는 순간 그 사람이 이쪽을 돌아본다.<br><br>돌아보면 안 되는 사람이 돌아봤다. 이쪽 때문에. 얼굴이 보였다.<br>멀리서 손전등이 그 얼굴을 비춘다. 그 사람이 벽을 향해 다시 돌아앉았다. 늦었다. 이쪽은 그 자리를 뛰쳐나왔다. 숨이 오래 가라앉지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 어깨를 짚어 다친 데가 있는지 본다.', k:'heal', dc:21,
      ok:`등 뒤에서 어깨에 손을 얹었다. 그 사람이 움찔한다. 돌아보지는 않는다.<br><br>어깨가 굳었다. 몇 시간을 이렇게 앉았다. 손바닥으로 어깨를 천천히 눌러 풀었다. 돌아보지 않게.<br>그 사람이 작게 말한다. 고맙다고. 그리고 벽에 대고 손가락으로 무언가 쓴다. 『정문 X. 방파제.』<br><br>등의 3을 소매로 지워 주었다.`,
      ng:`어깨에 손을 얹자 그 사람이 비명을 지른다. 숨을 참던 게 터졌다.<br><br>창고에 비명이 울린다. 빗소리 위로.<br>멀리서 사슬 소리가 다가온다. 그 사람은 벽을 보며 계속 비명을 질렀다. 이쪽은 숨을 데를 찾다 상자 모서리에 갈비를 찧었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B1', t:'방파제 — 파도',
  x:`방파제 위를 걸었다. 파도가 옆으로 친다. 콘크리트가 미끄럽다.<br><br>
    큰 파도 하나가 넘어왔다. 동료가 쓸려 나갔다. 방파제 가장자리 쇠고리에 걸린 밧줄을 겨우 잡았다.<br>
    물살과 싸우지 않는 법은 안다. 버티는 것과 싸우는 것은 다르다.<br><br>
    다음 파도가 저 멀리서 일어선다.`,
  o:[
    { l:'① 힘을 끌어 밧줄을 몸에 감고 버틴다.', k:'steady', dc:20, cost:{ might:26 },
      ok:`밧줄을 허리에 두 바퀴 감고 쇠고리 옆에 주저앉았다. 발을 고리에 걸었다.<br><br>파도가 왔다. 동료가 밧줄 끝에서 들린다. 밧줄이 이쪽 허리를 끊을 듯 조인다. 버텼다. 싸우지 않고. 물이 지나가기를.<br>파도가 빠졌다. 그 틈에 당겼다. 손바닥 하나만큼씩.<br><br>동료가 방파제 위로 올라왔다. 허리에 밧줄 자국이 붉게 남았다.`,
      ng:`감는데 파도가 먼저 왔다.<br><br>밧줄이 손바닥을 훑고 지나간다. 살갗이 벗겨졌다. 다시 잡았다. 동료가 물을 먹는다.<br>다 같이 당겨 겨우 올렸다. 이쪽 손바닥에서 피가 바닷물에 섞였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 뛰어들어 동료를 잡아 온다.', k:'bond', dc:21,
      doom:{ title:'검은 파도', what:'파도에 휩쓸려 끌려갑니다', dc:17, sec:50,
        text:`뛰어들었다. 물이 차고 무겁다. 동료 옷자락을 잡았다.<br><br>동료를 밧줄 쪽으로 밀었다. 동료가 밧줄을 잡는다. 그만큼 이쪽이 밀려난다.<br>다음 파도가 왔다. 방파제가 멀어진다. 아래로 당기는 물살이 있다. 발목을 잡는다.<br><br>검은 물 위로 해무호 불빛이 보인다. 누가 줄을 던져야 한다.`,
        dieText:`수도사는 남이 붙잡게 하고 제가 놓는 사람이다.<br><br>파도는 그걸 잘 안다. 늘 하나를 놓고 하나를 가져간다.<br>새벽에 해무호가 떴다. 뱃전 그물에 무언가 걸려 있었다. 염주 한 줄이.` },
      ok:`뛰어들려다 멈췄다. 파도 사이에 틈이 있다. 물이 빠지는 틈.<br><br>그 틈에 방파제 가장자리에 엎드려 팔을 뻗었다. 동료 손목을 잡았다. 다음 파도가 오기 전에 당겼다.<br>파도가 둘을 덮쳤다. 엎드린 쪽은 버틴다. 서 있던 쪽은 쓸린다.<br><br>파도가 빠지자 둘 다 방파제 위에 있었다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'B1', t:'냉동 창고 — 얼음 위의 좌선',
  x:`냉동 창고에 숨었다. 문밖에 회색 비옷이 서 있다. 언제 갈지 모른다.<br><br>
    다들 떤다. 이가 딱딱 부딪친다. 그 소리가 문밖까지 들릴 것 같다.<br>
    추위 속에 앉아 본 적이 있다. 겨울 법당 마루에서.<br><br>
    떨면 열이 난다. 대신 소리가 난다.`,
  o:[
    { l:'① 앉아서 추위를 몸 안쪽으로 들인다.', k:'steady', dc:21,
      ok:`얼음 위에 앉았다. 등을 세웠다. 추위를 밀어내지 않고 들였다. 살을 지나 뼈로.<br><br>뼈를 지나 더 안쪽에 데워지는 데가 있다. 거기에 숨을 모았다. 이가 멈췄다.<br>다른 넷에게 손짓했다. 등을 세우고, 숨을 아래로. 넷의 이 소리가 하나씩 멎는다.<br><br>문밖 회색 비옷이 한참 듣다가 갔다. 들을 게 없었다.`,
      ng:`들이려는데 추위가 뼈에서 멈추지 않는다.<br><br>손가락이 감각을 잃는다. 이가 더 크게 부딪친다. 숨을 아래로 모으려 할수록 떨린다.<br>문밖 발소리가 멈췄다. 손잡이가 내려갔다. 다들 레일 뒤로 굴렀다. 얼음 바닥에 뺨이 붙었다 떨어졌다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 다섯 손을 모아 품에 넣는다.', k:'heal', dc:20,
      ok:`다섯을 붙여 앉혔다. 손을 다 걷어 이쪽 품에 넣었다. 옷 안, 배에.<br><br>차다. 열 개의 얼음. 숨을 크게 쉬지 않고 견뎠다.<br>손들이 녹는다. 떨림이 멈춘다. 이 소리가 멎었다.<br><br>이쪽 배는 한동안 감각이 없었다. 그래도 다섯 손이 다 살았다.`,
      ng:`손을 품에 넣는 순간 너무 차서 숨이 터졌다.<br><br>헉 소리가 났다. 문밖에서 고무장화가 돌아선다.<br>다들 숨을 멈췄다. 회색 비옷이 문 앞에서 오래 섰다. 이쪽 배는 그동안 얼음을 품고 있었다. 나중까지 배가 아팠다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B2', t:'병실 — 묶인 침대',
  x:`눈을 뜨니 침대에 묶여 있다. 손목, 발목. 하얀 끈. 정각 점검 뒤에 묶였다.<br><br>
    옆 침대 동료도 묶였다. 둘 다 입은 자유롭다. 소리를 지르면 간호사가 온다.<br>
    몸이 묶여도 숨은 묶이지 않는다. 숨이 풀리면 몸도 풀 길이 보인다.<br><br>
    다음 정각까지 사십 분.`,
  o:[
    { l:'① 힘을 한 점에 모아 끈을 끊는다.', k:'break', dc:20, cost:{ might:22 },
      ok:`숨을 길게 쉬어 팔에 힘을 모았다. 한 번에 몰아 손목을 비틀었다. 당기지 않고 돌렸다. 끈은 당기면 버티고 비틀면 꼬인다.<br><br>꼬인 끈이 버클에서 툭 빠졌다. 한 손이 풀리자 나머지는 금방이다.<br>동료 끈도 풀었다. 끈은 도로 침대에 느슨하게 감아 두었다. 멀리서 보면 묶인 것처럼.`,
      ng:`비트는데 끈이 손목을 판다. 살이 쓸린다.<br><br>버클은 안 빠지고 침대가 삐걱인다. 소리가 복도로 나간다.<br>딸깍 소리가 다가왔다. 눈을 감고 잠든 척했다. 손목에서 피가 시트로 번졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 고개를 숙여 이로 매듭을 푼다.', k:'fix', dc:21,
      ok:`손목을 최대한 끌어당기고 고개를 숙였다. 이가 매듭에 닿았다.<br><br>천천히 물어 당겼다. 병원 매듭은 단단하다. 한 올씩. 턱이 아프다.<br>이십 분 걸렸다. 한 손이 풀렸다. 그다음은 손으로.<br><br>동료 끈을 다 풀었을 때 정각까지 칠 분이 남았다.`,
      ng:`물다가 이가 미끄러졌다. 입술이 찢어졌다.<br><br>피 맛이 난다. 매듭에 피가 스며 더 단단해졌다.<br>정각에 간호사가 와서 끈을 봤다. 젖은 매듭을 손가락으로 만져 보고 한 번 더 묶었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B2', t:'휴게실 — 천 마리 학',
  x:`휴게실 탁자에 노인이 앉아 종이학을 접는다. 탁자 위에 수백 마리가 쌓였다.<br><br>
    노인이 접으면서 센다. 칠백 하고 몇. 천 마리를 접으면 나갈 수 있다고 한다.<br>
    수를 세며 무언가를 쌓는 일은 익숙하다. 염주를 돌리며, 절을 하며.<br><br>
    노인 손이 떨린다. 학 날개가 자꾸 비뚤어진다.`,
  o:[
    { l:'① 마주 앉아 같이 접으며 같이 센다.', k:'steady', dc:20, wake:1,
      ok:`마주 앉아 종이를 집었다. 노인이 센 다음 수를 이쪽이 불렀다. 하나 접고, 노인 하나 접고.<br><br>손이 맞춰진다. 노인 손 떨림이 줄어든다. 수를 혼자 세는 것과 둘이 세는 것은 다르다. 둘이 세면 수가 덜 무겁다.<br>구백구십구에서 노인이 멈췄다. 마지막 하나를 이쪽 손에 쥐여 준다. 접어 달라고.<br><br>접었다. 노인이 학을 탁자 맨 위에 얹었다. 그리고 일어나 휴게실 뒤 창고 문을 열었다. 남의 수를 이어서 세 주는 일도 닦는 일이었다. 수를 쌓는 손이 남의 손과 맞물리는 법을 알았다.`,
      ng:`같이 접는데 이쪽이 센 수가 노인 수와 어긋났다.<br><br>노인이 멈춘다. 처음부터 다시 센다. 하나, 둘. 쌓인 학을 하나씩 세면서.<br>칠백까지 다시 세는 데 정각이 지나갔다. 노인 얼굴이 굳었다. 이쪽 때문에 하루가 밀렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 쌓인 학을 세어 본다.', k:'gaze', dc:21,
      ok:`노인이 접는 동안 쌓인 학을 셌다. 눈으로, 열씩 묶어서.<br><br>칠백이 아니다. 구백구십이다. 노인은 같은 수를 몇 번이나 다시 세고 있었다. 천에 닿을까 봐.<br>천에 닿으면 나가야 한다. 나가는 게 무서운 것이다.<br><br>노인에게 수를 말해 주지 않았다. 대신 학 열 마리 밑에 비상구 열쇠가 깔려 있는 걸 봤다. 노인이 깔아 둔 것이다. 언젠가를 위해.`,
      ng:`세는데 학이 무너졌다. 수백 마리가 바닥에 쏟아진다.<br><br>노인이 소리 없이 운다. 바닥에 엎드려 줍는다. 세면서.<br>같이 주웠다. 주우면서 몇 마리가 밟혔다. 정각 종이 울렸다. 둘 다 바닥에서 일어나지 못했다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B2', t:'이중문 — 두 문 사이',
  x:`병동 출구는 이중문이다. 첫 문이 열리고 닫혀야 둘째 문이 열린다.<br><br>
    다섯이 첫 문을 지났다. 첫 문이 닫힌다. 둘째 문은 안 열린다. 문 사이 좁은 칸에 다섯이 갇혔다.<br>
    벽 스피커에서 숫자가 나온다. 다섯. 다섯. 다섯.<br><br>
    첫 문이 다시 열리려 한다. 안쪽에서 누가 연다. 흰 소매가 보인다.`,
  o:[
    { l:'① 힘을 끌어 열리려는 첫 문을 몸으로 받친다.', k:'steady', dc:21, cost:{ might:27 },
      doom:{ title:'받친 문', what:'두 문 사이에 갇혔습니다', dc:17, sec:55,
        text:`첫 문에 등을 대고 섰다. 두 발을 버텼다. 흰 소매가 민다. 버텼다.<br><br>그런데 둘째 문이 그때 열린다. 첫 문이 막혀 있으니 둘째가 열린다. 일행 넷이 둘째 문으로 빠져나간다.<br>넷이 나가자 둘째 문이 닫힌다. 이쪽 등은 첫 문에 붙어 있다. 칸 안에 하나만 남았다.<br><br>스피커가 말한다. 하나. 하나. 첫 문이 더 세게 민다. 누가 둘째 문을 밖에서 열어 주어야 한다.`,
        dieText:`문을 막아서는 사람이 있다. 남이 지나가게.<br><br>문은 둘이었다. 하나를 막으면 하나가 열렸다. 공평했다.<br>칸 안에서 스피커가 한동안 하나라고 말했다. 그러다 다섯이라고 말했다. 숫자는 결국 맞았다.` },
      ok:`첫 문에 등을 대려다 멈췄다. 스피커 숫자를 들었다. 다섯이 칸 안에 있으면 둘째가 안 열린다.<br><br>문은 칸 안 숫자를 센다. 하나를 첫 문 쪽에 세워 두면 숫자가 넷이 된다. 넷이면 열린다.<br>첫 문을 등으로 반만 받치고 넷을 둘째 문 앞으로 보냈다. 스피커가 넷이라고 말한다. 둘째가 열렸다.<br><br>넷이 나가는 순간 첫 문에서 등을 떼고 몸을 날렸다. 둘째 문이 닫히기 전에. 뒤꿈치가 문틈에 쓸렸다.`,
      win:{ exp:18, dream:3 } },
    { l:'② 둘째 문 틈 고무를 본다.', k:'gaze', dc:20,
      ok:`둘째 문 아래 고무 틈을 봤다. 바닥에 빗물이 스며든다. 문 너머가 바깥 쪽이다.<br><br>고무 한쪽이 찢어져 있다. 손가락이 들어간다. 그 안에 쇠막대가 있다. 수동 걸쇠다. 불이 났을 때 쓰는.<br>손가락 둘로 걸쇠를 밀었다. 둘째 문이 한 뼘 열린다.<br><br>흰 소매가 첫 문을 열었을 때 칸은 비어 있었다.`,
      ng:`보는 사이 첫 문이 열렸다.<br><br>흰 소매가 칸 안으로 손을 뻗는다. 가장 가까운 동료 어깨를 잡는다.<br>떼어 내느라 넷이 붙었다. 손톱이 동료 어깨를 긁고 갔다. 둘째 문은 끝내 열리지 않았다. 다른 길로 돌았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B2', t:'점검 — 빈 이름',
  x:`정각 점검이다. 간호사가 이름을 부른다. 하나씩.<br><br>
    일행 하나가 침대에 없다. 화장실에 갔다가 아직 안 왔다. 그 사람 명패 이름이 곧 불린다.<br>
    목소리는 다룰 줄 안다. 경을 읽을 때 높낮이를 바꾼다. 낮게, 길게, 끊어서.<br><br>
    간호사가 바로 옆 침대 앞에 섰다.`,
  o:[
    { l:'① 제 이름과 빈 침대 이름 둘 다 대답한다.', k:'steady', dc:20,
      ok:`제 이름에 대답했다. 낮게. 간호사가 한 걸음 옮긴다. 빈 침대 이름을 부른다.<br><br>베개에 고개를 묻고 대답했다. 높게, 짧게. 목소리를 경 읽을 때처럼 바꿨다. 다른 사람 목소리처럼.<br>계수기가 딸깍했다. 간호사가 지나간다.<br><br>화장실 갔던 동료가 돌아왔다. 제 이름이 이미 대답한 걸 모른다. 모르는 게 낫다.`,
      ng:`빈 침대 이름에 대답하는데 목소리가 제 목소리 그대로 나왔다.<br><br>간호사가 멈춘다. 빈 침대를 본다. 그리고 이쪽을 본다. 같은 목소리가 두 번 났다.<br>계수기를 한 번 누르고 펜을 꺼낸다. 이쪽 이름 옆에 무언가 적었다. 하나 많다고.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 빈 침대에 베개를 넣어 사람처럼 만든다.', k:'hide', dc:21,
      ok:`옆 침대 이불 밑에 베개 둘을 넣고 둥글게 말았다. 머리 쪽엔 수건을 뭉쳐 넣었다.<br><br>간호사가 그 침대 이름을 부른다. 대답이 없다. 간호사가 이불을 본다. 둥글게 솟은 것을 본다.<br>세어졌다. 대답보다 모양을 센다. 이 병동은 그렇다.<br><br>동료가 돌아왔다. 베개를 빼고 대신 누웠다. 이불이 같은 모양으로 솟았다.`,
      ng:`말다가 베개가 하나 모자랐다. 이불이 납작하다.<br><br>간호사가 이불을 걷는다. 비었다. 계수기를 누르지 않는다.<br>복도로 나가 다른 간호사를 부른다. 정각 점검이 다시 시작됐다. 처음부터. 이번에는 손전등을 들고. 다들 눈이 부셔 한참 앞을 못 봤다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'4호차 지붕 — 바람',
  x:`복도가 막혔다. 지붕으로 올라갔다. 열차 지붕이다.<br><br>
    바람이 옆에서 친다. 빗줄기가 칼처럼 얼굴을 긋는다. 터널이 다가온다. 입구가 검다.<br>
    산꼭대기 바람 속에 앉아 본 적이 있다. 바람은 낮은 것을 지나친다.<br><br>
    뒤따라 올라온 동료가 휘청인다.`,
  o:[
    { l:'① 힘을 끌어 동료를 끌어안고 지붕에 엎드린다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`동료 허리를 끌어안고 같이 엎드렸다. 지붕 이음새에 손가락을 걸었다. 발끝도.<br><br>바람이 등을 친다. 들어 올리려 한다. 힘을 아래로 눌렀다. 땅에 앉듯이 지붕에 앉았다.<br>터널이 왔다. 검은 천장이 머리 위 한 뼘을 스친다. 엎드린 둘은 그 밑으로 지나갔다.<br><br>터널을 나왔다. 손가락이 이음새에 박혀 피가 났다. 동료는 이쪽 밑에서 숨을 쉬고 있었다.`,
      ng:`끌어안는데 바람이 둘을 같이 민다. 지붕 가장자리 쪽으로.<br><br>손가락을 이음새에 걸었다. 미끄러진다. 하나가 걸렸다. 그 하나로 버텼다.<br>터널 천장이 등을 스쳤다. 옷이 찢어지고 등이 쓸렸다. 둘 다 살았다. 등이 불에 덴 듯했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 바람이 약한 틈에 먼저 앞 칸 사다리로 간다.', k:'evade', dc:20,
      ok:`바람에 박자가 있다. 세게 치고, 숨 쉬듯 약해진다. 약해지는 틈에 엎드린 채 앞으로 기었다.<br><br>세 틈 만에 앞 칸 사다리에 닿았다. 사다리를 잡고 뒤로 손을 뻗었다. 동료가 그 손을 잡았다.<br>터널 직전에 둘 다 사다리 아래로 내려왔다.`,
      ng:`틈을 잘못 셌다. 기는 도중에 바람이 쳤다.<br><br>몸이 옆으로 밀린다. 지붕 끝 배수 홈통을 잡았다. 홈통이 휘었다.<br>동료가 이쪽 발목을 잡아 끌어 올렸다. 정강이가 지붕 모서리에 찢어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B3', t:'2호차 — 입마개 한 개들',
  x:`2호차 화물칸에 개 다섯 마리가 묶였다. 입마개를 했다. 낮게 운다.<br><br>
    동료들은 몽둥이를 찾는다. 다섯 마리면 다 쳐야 지나간다.<br>
    수도사는 살생을 하지 않는다. 짐승도. 대신 짐승이 무엇을 무서워하는지 안다. 눈을 똑바로 보는 것, 서 있는 것, 서두르는 것.<br><br>
    개들 눈이 이쪽을 본다. 겁먹은 눈이다. 겁먹은 개가 제일 세게 문다.`,
  o:[
    { l:'① 바닥에 앉아 눈을 내리깔고 기다린다.', k:'steady', dc:20,
      ok:`몽둥이를 든 동료 손을 내리게 했다. 칸 한가운데 바닥에 앉았다. 눈을 내리깔았다. 숨을 고요히.<br><br>개들이 으르렁거린다. 한참. 앉은 것은 덮치지 않는다. 내려다보는 것만 덮친다.<br>하나가 줄 끝까지 와서 냄새를 맡는다. 앉은 이쪽 무릎을. 그리고 엎드린다. 나머지도 하나씩.<br><br>앉은 채 기어서 지나갔다. 다섯이 다. 개들은 고개만 돌려 봤다.`,
      ng:`앉는데 열차가 크게 흔들려 옆으로 쓰러졌다.<br><br>갑자기 움직인 것을 개들이 덮친다. 입마개째 들이받는다. 줄이 팽팽해진다.<br>정강이를 들이받혔다. 동료들이 몽둥이를 들었다. 말릴 틈이 없었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 손등을 내밀어 냄새를 맡게 한다.', k:'bond', dc:21,
      doom:{ title:'내민 손등', what:'개들에게 물려 끌려갑니다', dc:17, sec:50,
        text:`천천히 다가가 손등을 내밀었다. 냄새를 맡으라고. 짐승은 냄새로 사람을 믿는다.<br><br>한 마리가 맡는다. 그리고 입마개 고리를 이쪽 손목에 건다. 고리가 손목에 걸리게 고개를 돈다. 배운 동작이다.<br>다섯이 같이 당긴다. 칸 구석, 짐 더미 뒤로. 줄이 그쪽으로 길게 나 있었다.<br><br>짐 더미 뒤에 무엇이 기다리는지 개들은 안다. 누가 고리를 풀어 주어야 한다.`,
        dieText:`짐승에게도 손을 내미는 사람이 있다. 믿으면 믿는다고.<br><br>이 개들은 손을 내미는 사람을 기다리도록 길러졌다.<br>짐 더미 뒤에서 한동안 소리가 났다. 개들은 다시 엎드렸다. 입마개는 그대로였다.` },
      ok:`다가가다 멈췄다. 개들 입마개 고리가 너무 크다. 손목이 들어갈 만큼.<br><br>입마개가 아니라 다른 것이다. 손을 거두었다. 그 자리에 앉았다. 눈을 내리깔고.<br>개들이 한참 이쪽을 보다 엎드렸다. 손을 내밀지 않은 사람은 기다릴 필요가 없다는 듯이.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'B3', t:'얼음 칸 — 갇힌 밤',
  x:`얼음 칸에 숨었다가 문이 밖에서 잠겼다. 톱밥 덮은 얼음 사이에 다섯이 갇혔다.<br><br>
    입김이 하얗다. 손발부터 굳는다. 다음 역까지 얼마인지 모른다. 이 열차는 서지 않는다.<br>
    추운 법당에서 밤을 새워 봤다. 혼자서. 다섯이 같이 새운 적은 없다.<br><br>
    가장 약한 동료가 졸리다고 한다.`,
  o:[
    { l:'① 다섯을 둥글게 모아 체온을 돌린다.', k:'heal', dc:20, wake:1,
      ok:`다섯을 둥글게 붙여 앉혔다. 등과 가슴을 맞대게. 가장 약한 사람을 가운데.<br><br>바깥쪽 자리를 돌게 했다. 열 번 숨 쉬면 한 칸씩. 바깥은 춥고 안은 따뜻하다. 다들 한 번씩 안에 들어간다. 이쪽은 늘 바깥이다.<br>졸리던 동료가 다시 떤다. 떠는 건 산 것이다.<br><br>문이 열린 건 한참 뒤였다. 다섯 다 일어섰다. 혼자 견디던 법을 다섯이 견디는 법으로 바꿨다. 한 몸의 고요가 여럿의 온기가 됐다.`,
      ng:`모으는데 다들 손발이 굳어 잘 안 움직인다.<br><br>자리를 돌게 하는 박자가 흐트러졌다. 바깥의 하나가 너무 오래 바깥에 있었다.<br>그 사람 귀가 하얗게 얼었다. 문이 열렸을 때 다섯 다 일어서지 못했다. 업어서 나왔다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 힘껏 문을 쳐서 문틀 얼음을 깬다.', k:'break', dc:21,
      ok:`문틀에 성에가 두껍게 앉았다. 잠긴 게 아니라 얼어붙었다.<br><br>손바닥 뿌리로 문틀을 쳤다. 한 번, 두 번. 성에가 금이 간다. 손이 얼얼하다.<br>다섯 번째에 얼음이 갈라지며 문이 덜컥 밀렸다. 한 뼘. 차가운 바람이 아니라 덜 차가운 바람이 들어온다.`,
      ng:`쳤는데 문틀이 아니라 얼음이 단단하다. 손바닥 살이 붙었다 떨어진다.<br><br>치는 소리가 칸 밖으로 나간다. 통로에서 발소리가 멈췄다.<br>멈춘 발소리가 문 앞에서 똑같이 문을 두드린다. 바깥에서. 이쪽 박자로. 손바닥이 터져 피가 얼었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 경을 외며 다섯의 숨을 이끈다.', k:'steady', dc:20,
      ok:`낮게 경을 외웠다. 숨에 맞춰. 들이쉬고 한 구절, 내쉬고 한 구절.<br><br>다들 그 박자로 숨을 쉰다. 숨이 길어지면 몸이 덜 떤다.<br>가장 약한 동료가 따라 웅얼거린다. 졸지 않으려고. 웅얼거림이 끊기지 않았다.`,
      ng:`외우는데 이가 부딪쳐 구절이 끊긴다.<br><br>끊길 때마다 다들 숨이 흐트러진다. 가장 약한 동료가 따라 하다 멈췄다.<br>흔들어 깨웠다. 한참 뒤에 깼다. 그 사이 이쪽 발가락 감각이 없어졌다.`,
      win:{ exp:15, dream:2, spirit:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'서지 않는 역 — 승강장의 손',
  x:`열차가 역을 지나간다. 서지 않는다. 승강장 불빛이 길게 늘어진다.<br><br>
    승강장에 사람들이 서 있다. 열차를 보고 손을 든다. 타게 해 달라는 손이다. 젖은 얼굴들이다.<br>
    수도사는 내민 손을 그냥 못 지나간다.<br><br>
    다음 역에도, 그다음 역에도 같은 얼굴들이 서 있다. 하나도 다르지 않다.`,
  o:[
    { l:'① 창에 손을 대고 그들을 위해 경을 읽는다.', k:'steady', dc:20,
      ok:`창에 손바닥을 대고 경을 읽었다. 짧게. 지나가는 역마다 한 구절씩.<br><br>승강장의 손들이 하나씩 내려간다. 경이 닿은 데부터. 젖은 얼굴들이 고개를 숙인다.<br>다음 역에는 사람이 줄었다. 그다음 역은 비어 있었다.<br><br>창에 손바닥 자국이 남았다. 김이 서려서. 그 자국만 오래 지워지지 않았다.`,
      ng:`경을 읽는데 승강장의 손들이 창 쪽으로 다가온다. 열차를 따라 뛴다.<br><br>손바닥들이 창에 붙는다. 바깥에서. 이쪽 손바닥 맞은편에.<br>창이 차가워진다. 손을 뗄 수가 없다. 일행이 떼어 냈다. 손바닥 살갗이 창에 남았다.`,
      win:{ exp:16, dream:3, spirit:6 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 창 커튼을 내리고 일행을 앉힌다.', k:'hide', dc:21,
      ok:`커튼을 내렸다. 객차의 커튼을 하나씩 다. 일행에게 창 쪽을 보지 말라고 했다.<br><br>내민 손을 못 본 척하는 일은 어렵다. 그래도 했다. 저 손을 잡으면 열차가 선다. 서면 끝이다. 시간표 맨 아래가 생각났다.<br>역들이 지나갔다. 커튼 너머로 불빛만 깜빡였다.<br><br>마지막 역을 지났을 때 커튼 하나를 걷었다. 승강장이 비었다. 기도는 그다음에 했다.`,
      ng:`내리는 사이 일행 하나가 창 밖 손을 봤다. 아는 얼굴이 있다고 한다.<br><br>창을 열려 한다. 붙잡았다. 그 사람이 운다. 이쪽 손을 뿌리치다 손톱이 얼굴을 긁었다.<br>창은 열리지 않았다. 그 사람은 끝까지 이쪽을 보지 않았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] }

]);
